/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20051005-4","meetingId":"h17-c-settlement","date":"2005年10月5日","dateIso":"2005-10-05","committee":"決算特別委員会","time":"午前１０時０５分～午後５時２７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を124件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"武内委員","kind":"質問","question":"私は、１０４ページの成年後見センター助成事業と、１０８ページの視覚障害者用触地図の作成の２点でお伺いしたいと思います。初めに１０４ページの成年後見センター助成事業のほうですけれども、この事業の大体の内容について教えてください。","respondent":"早津高齢福祉課長","answer":"そういったことに対する助成金というものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"そういった実態があるかなと思うんですけれども、この相談と問い合わせ、これの違いを簡単に教えていただきたいのと、あと、そうした制度をなかなか利用に至らない実情というのはどのように認識されているか教えてください。","respondent":"早津高齢福祉課長","answer":"それで、なかなかつながらないというのは、先ほども申し上げたように、将来のことが不安なんだけれども、例えばそれをサービスにつなげていくためには公正証書遺言の書き方ですとか、任意後見人をどういうふうに選定するかというようなお話に順に進んでいきますので。","voiceIndex":6,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"そうした中で、ちょっといろんな質問が錯綜してしまって申しわけないんですけれども、これは、社会福祉協議会の「社協だより」ですね、これの９月１日の「社協だより」を今ちょっと見ていましたら、品川区が何と全国１位の実績みたいなことが書かれておりまして、これは法人後見としての活動している件数が１７件で全国第１位というふうに出ておりますけれども、非常にびっくりしたんですけれども。","respondent":"早津高齢福祉課長","answer":"その方に対して後見人をつけるということになるわけですが、この後見人をつけるに当たっては、通常は弁護士ですとか、あるいは親族ということになるんですが、個人であるよりも法人であることのほうが、連続性とか信頼性というのが高いというような立場から。","voiceIndex":8,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"よくわかりましたが、非常に難しいなという、それはすばらしいなと考えています。それで、ちょっとこれも教えていただきたいんですけれども、国の補助金がこれに成年後見制度を利用支援事業ということで、国の補助金が出て、例えばこういった制度の利用促進のための広報とか、こうしたものに対しての補助金が出ているというふうに聞いているんですけれども、この辺のところも教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"全体的なこの制度の普及のためにはどうしているかということですが、社会福祉協議会のほうでリーフレットをつくって、相談や問い合わせ等に応じているというのもありますし、また在宅介護支援センターを通じて。","voiceIndex":10,"id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"お聞きしたいのは、身寄り、特に多いのが、これからひとり暮らしの高齢者が多いものですから、身寄りがない方で、また身寄りがあってもなかなか兄弟等で行き来していなくて、いろいろなことを頼めない、自分の将来の不安を兄弟に任せるわけにいかないということで、そういったケースで自分が認知症になってしまったり、そうしたときにという、そういうケースが多いんですけれども、実際に今。","respondent":"早津高齢福祉課長","answer":"身内の方であるから、自然人であるということも含めて、身内の方であると、自分より先にもしかしたら亡くなるかもしれないという懸念もありますので、法人が任意後見人になるということの意味というのがもう一つあるのではないかです。","voiceIndex":12,"id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"これはまた事務事業評価でも今回Ａになっていますけれども、こうした社会的な背景を踏まえて、そういう形でこれから増やしていこうというか、取り組みを強めていこうとされていると思うんですけれども、その辺のところを教えてください。","respondent":"早津高齢福祉課長","answer":"大体１,５００万円程度の助成というふうに考えているところです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"武内委員","kind":"質問・要望","question":"取り組みを一層強めていただきたいと思います。そういったときに、またこれは何年か後に、この地図をやり直すのかどうか、その辺のところを教えてください。","respondent":"西島障害者福祉課長","answer":"どのサイクルでというのはなかなか難しいところがありますし、それからまた機械の進歩というんですか、ユビキタス社会とかというような言葉も今出てきておりますが、そのようなこともありますので、今後、どういうふうにしていくか。","voiceIndex":16,"id":"exchange-007"},{"speaker":"武内委員","kind":"質問・要望","question":"非常に好評だということで、また各問い合わせ等もいろいろあるということで、非常にいいなと考えていますけれども、おっしゃるとおり、地図はつくった途端に、もう古くなってしまうんですけれども、特に我々みたいに健常の目が見える方はいろんな形で確認できるからよろしいんですけれども、目の見えない方用につくっている地図なので、その辺のフォローというか、そういったものをぜひしていただきたいのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-008"},{"speaker":"大西委員","kind":"質問","question":"私のほうからは、成果報告書の１０４ページ、路上生活者実態調査、それと、今少しだぶるところになりますが、成年後見センター助成事業、そして、１０６ページの品川区シルバー人材センター支援事業、しながわお休み石設置事業、高齢者生活支援事業、それと、事務事業評価の２２ページ、２３ページの生活支援型一時保育事業のオアシスルーム、２３ページの休日保育の実施、病後児保育の実施について。","respondent":"蓼沼高齢事業課長、早津高齢福祉課長、小林保育課長、山口交通安全担当課長","answer":"お休み石についてですけれども、お休み石につきましては、幾つかタイプがありますけれども、バス停に設置するタイプあるいはくつろぎ型とか。通常、ホームへルプの派遣事業は介護保険の認定を受けた方が選んで、必要な場合にホームへルプの派遣というようなことが起こるわけですが。平成１６年実施園、現在は１０園ですが、平成１６年度５園で、利用者数は２,７１３人という実績を持っております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"大西委員","kind":"質問・要望","question":"それと路上生活者の実態ということで、これが現在何名ぐらいいるか、ということをちょっと教えていただきたい。これが一時的なものと言われておりますが、一時的なものが恒常的な形で子どもと職員に対しての負担になるのではないかということなので、その改善をできるだけ図っていただきたいと思いますが、どのようなものでしょうか。以上お答えをお願いいたします。","respondent":"志村生活福祉課長、早津高齢福祉課長、山口交通安全担当課長、小林保育課長","answer":"私から路上生活者の実態調査のご報告です。この実態調査を行いましたのは、平成１６年の８月、それから１０月と２回に分けて行いました。回数でいけば、７,０００回ぐらいの派遣をしているです。ただ、広範囲にわたって腕章をして札をつけて、とめないようにしてくださいと、防止指導の形のものについては、大井町駅、大崎駅西口、武蔵小山駅。","voiceIndex":25,"id":"exchange-010"},{"speaker":"大西委員","kind":"質問","question":"先ほどの高齢者支援事業ですが、ヘルパーを派遣して１時間当たり２,２３０円ということでしたが、そうすると、これは介護保険の認定を受けていない人たちからの費用負担、介護保険を受けていると本人負担はたしか１割だったというふうに認識しているんですが、この本人負担というのはどういう形なんでしょうか。","respondent":"早津高齢福祉課長","answer":"保険と同様に１割の負担をしていただいているところです。","voiceIndex":30,"id":"exchange-011"},{"speaker":"大西委員","kind":"質問","question":"わかりました。路上生活者の実態調査ですが、この４８名ぐらいが現状で生活しているんじゃないかということですけれども、こういう人たちに対して、アドバイスというんですか、就業支援というか、そういう形のものは何か行っているんでしょうか。","respondent":"志村生活福祉課長","answer":"就労の支援につきましても、平成１７年度から取り組みを始めたところですので、これからも強めてまいりたい、かように考えてあります。","voiceIndex":32,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１１２ページの保育園運営費、そして障害児放課後生活サポート事業、やんちゃっこクラブについてお伺いをします。数年来、事業の拡大が行われていますけれども、子どもたちにどのような影響を及ぼしているのか、この点でお伺いをしたいと思います。我が党としては保育園建設、この状況だと２つは新しくつくっていただきたいなと思っていますが、この点でもお答えをいただきたいと思います。","respondent":"小林保育課長","answer":"これからの需要をどう想定しているのかというお尋ねですけれども、一番ダイレクトに需要が反映してくるのは、やはり大規模建築物ということでございまして、それはある程度を把握して、計画の中で対応していくように努めてはあります。","voiceIndex":35,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"延長夜間保育の時間延長とか、土曜日、日曜日、そして年末保育、開園日の日数が増えたこと、あとは定員の弾力化で特に乳児のところが１１０％増になっていること、あとオアシスルームの利用も大変多くなっていますけれども、この間、１０年間ぐらいでいいんですけれども、事業量がどのぐらい増えているのかをちょっと数字でお示しいただきたいなと思うんですが、その辺は可能でしょうか。","respondent":"小林保育課長","answer":"特別保育等のことで事業量ということなんですけれども、それぞれの事業量で過去１０年のそれぞれのというのは、ちょっと今手元には持ち合わせておりませんけれども、これまで行ってきたところは、平成１０年度の年末保育から。","voiceIndex":37,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一時的に入っても、認可に入りたいというところが強いので、ぜひ補完的な施設として考えていただきたいなと思います。先ほど非常勤の職員、ちょっと私が聞き漏らしてしまったんでしょうか、もう１回非常勤職員がここに何人分なのか、ぜひ正規換算に直してお知らせをいただきたいと思います。もう１点質問なんですが、この間１０年間の正規職員の削減数がわかりましたらお知らせをしてください。","respondent":"小林保育課長","answer":"正規職員のこの間の推移をというお求めですけれども、今、手持ちですぐご報告できますのは、平成１２年度からの数で、いわゆる園長を含めました保育士の数で推移を申しますと５１０名、平成１２年が５１０名、平成１３年が５９９名、平成１４年が５８０名、平成１５年が５７７名。","voiceIndex":39,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"今、非常勤と人材派遣のところの人数を伺ったんですが、非常勤にしてもすごい大勢の人数ということで、今の保育の現場が、短時間雇用の非常勤、そして人材派遣、私はこれ人材派遣の方は１日かと思ったら、３時間の人材派遣もあると聞いてびっくりしたんですが、保育体制が本当にこういった不安定雇用の方に支えられているんだなというのを強く今感じていますが、子どもの立場に立ったとき。","respondent":"小林保育課長","answer":"１つの例で７時間の職員が３時間の職員２人に分かれたというご指摘がございましたが、逆に本来であれば、７時間の無資格の職員が長時間対応するよりも、現行人員の中で、正規の職員ないしは派遣職員を含めて対応していくほうが。","voiceIndex":41,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど改善点もあるというお話でしたけれども、専用室があるところとないところとちょっと数を教えていただきたいのと、現状でも、保育室、ゆとりがないのに各０歳とか１歳とか２歳に新たにこういったオアシスの子がここに加わって保育を受けることへの、現在いる子どもたちへの影響をどう考えているのか、あとスタッフもぜひ専用にしていただきたいんですが、いかがでしょうか。","respondent":"小林保育課長","answer":"これから、オアシスルームの環境整備ということは、施設の制約のある中で努めてまいりますが、そういった意味で、オアシスルームの部屋というのは、その中に子どもを全部詰め込む、その部屋だけでやるという考えではなくて、その部屋を拠点として考えて。","voiceIndex":43,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大崎保育園、ポップンポップルームですか、今の地域の交流のところのお部屋ができて、利用が高くて喜ばれているということなんですが、この部屋を確保するために４・５歳児の子どもたちが、学童保育クラブの跡地、園舎から１００メートルぐらい離れた屋根のないところを通って、毎日昼食とおやつを食べに２往復しなくてはいけないという、こういった状況を子どもたちの負担をどう考えているのか、１点と。","respondent":"小林保育課長","answer":"西品川、大井、これも施設の活用で３階に一部保育室が移るところですが、それぞれ年齢、保育環境の状況に応じて、問題のないように今後も対応してまいりたいと考えています。","voiceIndex":45,"id":"exchange-018"},{"speaker":"築舘委員","kind":"質問・要望","question":"成果報告書の１０６ページ、認知症高齢者ケア事業というところと、１０７ページ、高齢者の福祉電話、それから、１１１ページの保育園０歳児保育、それから１１２ページの児童センターに関してご質問いたしたいと思います。ですから、その辺のことの現状と将来を見越してのご意見をお聞かせいただきたいと思います。","respondent":"早津高齢福祉課長、小林保育課長、辻田児童課長","answer":"今年度からは、さらに区内に勤める介護職員ならば全員の方を対象にしまして、認知症ケアの集中的な研修コースを設けまして。それからもう１つ、３点目に大切なのは、保育ニーズが多様化しているということですから。今後そのような中で、いろいろな形のことを検討していきたいというふうに考えております。","voiceIndex":49,"id":"exchange-019"},{"speaker":"築舘委員","kind":"質問・要望","question":"それと、福祉電話に関しましては、やはりこれは電話機を貸与しますと言っても電話機、従来の電話機を貸与するんですかね、そのどういうふうに、どんな電話機だかよくわかりませんけれども、なかなかかけにくいというふうに思うんで、かける人がいるのかどうか、その辺のことはやはりある程度は貸しますと言っても、ほとんどいないんではないかと私は思うんですが。","respondent":"早津高齢福祉課長","answer":"福祉電話は区が加入権を持っているものをお貸しするということでございまして、その電話では、民生委員が安否を確認したりというようなことにも使っているというのが実情です。","voiceIndex":53,"id":"exchange-020"},{"speaker":"築舘委員","kind":"確認","question":"安否を確認するということだけで、福祉電話というものを貸与していこうということだと、これは、ほかの安否確認もあるんではないかということもありますし、平成１７年度からは都のほうの補助も打ち切られた……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"評判よく出ていたんですが、こういう施設がこれからの方向性として、こちらではなく、都南病院の跡地の問題が以前から再三にわたって質問させていただいていますが、まず土地の取得が遅れている中で、前回の本会議の中で、来年１月ごろをめどに取得の方向性ということでお答えいただいているんですが、９月になってから、国有地売却に対して自治体の割引廃止というのが新聞報道に出まして。","respondent":"早津高齢福祉課長","answer":"都南病院の跡地の取得につきましては、さきに一般質問等でお答えしましたように、区といたしまして新たな補助金等の制度の改正を踏まえまして、新たな計画案を策定いたしまして、用地取得に向けての折衝を再開をしたところです。","voiceIndex":57,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"当初、金額とか取得時期については今までと同じような状況で進んでいるのかどうか、現状の進みぐあい的なものはお答えできるのでしょうか。","respondent":"早津高齢福祉課長","answer":"用地の取得の見込みですが、先ほど委員の新聞等の記事にもございましたように、用地取得についてはなかなか難しい状況も見えております。そうした中で、区としては新しい構成案を考えましたので、それをもって折衝をするという状況です。","voiceIndex":59,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"構成案というのは、要するに複合施設としての構成案をある程度おつくりになって、それをもって区のほうで国のほうと社会保険庁と交渉しているという考え方でよろしいんですか。","respondent":"早津高齢福祉課長","answer":"新しい案を持って社会保険庁と折衝しているということでございまして、具体的に申し上げますと、あの地域全体を見た上で、高齢者施設とそれから保育園との合築施設というものを新たな案として社会保険庁に提示し、それに基づいて用地の取得の折衝を続けていきたいというものです。","voiceIndex":61,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えば高齢者施設としてもどの程度のものが含まれているのか、それと保育園として考えると、私も前から言っていたんですけれども、保育園と高齢者施設を一緒のがある程度いいんじゃないかと質問もさせてもらったこともありますし、あの辺だから保育園も老朽化したところもあるということで改築できないか、その辺を一体ということでよろしいんでしょうか。","respondent":"木下福祉高齢事業部長","answer":"施設構成案につきましては、この間、高齢者を中心とした地域密着型の施設内容ということで、グループホーム、ケアハウス、小規模多機能拠点、介護予防拠点などを考えてまいりましたけれども、あわせまして、品川保育園の老朽化という問題もありますので、これも取り込んだ形で。","voiceIndex":63,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ですから、今度品川保育園の移設が、時期がずれますけれども、そのときにはぜひその辺のところも検討していただいて、規模がどの程度、たしか１,５００m2ぐらいの広さの中ですので、どこまで保育園施設がとれるのか、定数もどこまで弾力化できるのかというのはわからないと思うんですが、今もう、そちらでは計算を出していると思うんですけれども、まだ我々のほうではちょっとわからないので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"ちょっとお聞きしますけれども、土地の購入との関係ですけれども、これまで、３つに分かれていまして大きな土地だけを買うということでしたけれども、今のお話を聞いていますと、また新しい構成案で保育園まで併設をしていくという話ですけれども、２つに、小さいほうの土地、ここを買うという予定はその辺は変わりはないのか、買わないという予定は変わりはないのか、ちょっとお聞かせを願いたいと思います。","respondent":"早津高齢福祉課長","answer":"取得予定の土地は真ん中の土地です。先ほどお答えしましたように合築型です。","voiceIndex":67,"id":"exchange-027"},{"speaker":"菊地委員","kind":"質問","question":"構成案を、制度の変更もあり得るんでしょうけれども、大きく変えたわけですよね。私は改めて申し上げておきたいんですけれども、２つの小さいほうの土地、これを買いつけて、新たに特養ホームの建設等を考えることも可能ではないかというふうに思いますけれども、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"用地の取得には当然お金もかかりますし、真ん中の土地という中で、高齢者の需要にも十分答えられるというふうに考えてあります。","voiceIndex":69,"id":"exchange-028"},{"speaker":"菊地委員","kind":"質問・要望","question":"いずれにしても、小規模多機能にしても何にしても、高齢者の皆さんが必要な施設だというふうにはもちろん考えています。ですから、本当にだれもが入所が可能だという施設をぜひ改めて考えていただきたいというふうに思って終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"そのときに総合の評価で２３区の中で、暮らしの満足度が品川区がトップだ、１２項目あるうちで保育が３位以内に入っていますというお話をさせていただいたんですが、私は保育、教育は品川区が２３区でトップだと考えていますが、子育てについて、まず担当の保育課長、また児童課長は、２３区で自分たちはどのくらいかと思っているかということをまずお伺いしたいのと、それと子育てについてお伺いしますが。","respondent":"辻田児童課長、小林保育課長、榎本行財政改革担当課長","answer":"いろんな形で決断をしていく中で先駆性を保っていくというのは大変難しいことですが、今後も努力してまいりたいというぐあいに考えております。保育課はとりわけ０～５歳の年齢対象ですけれども、思いは児童課長と同じです。次世代育成の行動計画として推進している事業をピックアップして行動計画としてまとめたものですので、さらにその中で個別に充実を図っていきますけれども。","voiceIndex":73,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"お答えで、充実させていくということなんですが、具体的に、保育園があり、幼稚園、子育てですけれども、幼稚園があり、ぷりすくーるという総合施設があって、それの施設があって、その中でメニューもものすごく多様化していると思うんですけれども、メニューをそろえてこれから親に選択をしてもらうのかということと、あと、今まで夜１０時までの延長夜間保育とか、病児病後児保育、それと休日保育。","respondent":"小林保育課長","answer":"今後の展開ですけれども、保育におきましては０～５歳児の就学前児童総体に対して、総合的な対応、その保育園、幼稚園あるいは在宅、施設に預かっている、関係なく必要な教育を提供できるサービスメニューの設定を含めて。","voiceIndex":77,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"今後とも２３区だけではなくして、日本一と言われるぐらいな子育て施策をしていただきたいと要望します。","respondent":"原国保年金課長","answer":"お尋ねの大江戸温泉の関係です。予算ですけれども、２００万円の定額ということで予算を執行しています。それから、利用者の数ですが、この事業といたしまして、保険事業ということで被保険者の健康の保持増進を図るため、保養施設の補助、それから海の補助等を実施しています。","voiceIndex":79,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"８万世帯で利用が３,８００ですよね。というのは、私が平成１１年に初めて議員になったときの行政視察が秋田でした。どうしてかと聞いたら、それは、やっぱりここの地域に来たら、ここの地域でお金を落とすんだよとお話をしてくれたんです。大江戸温泉にお金を落とさないで、保養という意味であるならば、何か品川区にお金が落ちることも考えていったらいいと思うんですけれども、その辺はいかがでしょうか。","respondent":"原国保年金課長","answer":"やはり近くでなかなかこういう時間を費やしていただくということを考えますと、まだ品川区の中ではそういった施設がございませんで、やはり品川の土地から考えますと、大江戸温泉が、通えて、それから３時間から４時間ゆっくりしていただけるということで。","voiceIndex":81,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"私は、成果報告書１８０から１８１ページ、介護について、あと、１０９ページのシルバーセンターについてお聞きしたいと思います。最近、４０代、５０代の方から、自分の親が徘徊するようになり大変心配で困っております。現在、品川区の人口は約３３万人で、６５歳以上の高齢者人口は６万２,０００人ぐらいですが、このうち、軽度を含めて認知症と認定される方は何人ぐらいいらっしゃるのでしょうか。","respondent":"早津高齢福祉課長","answer":"認知症の症状をお持ちの方の人数ですが、一昨年度、私どもで認知症ケアの検討を行ったときに、認知症の症状があらわれている方の人数をお出ししたことがあります。このときは、要介護高齢者と認定されている方が９,２２７人、平成１５年１２月現在です。","voiceIndex":85,"id":"exchange-034"},{"speaker":"須貝委員","kind":"質問","question":"このたびは人件費等々、職員費も入っておりますけれども、約８億円ぐらいまた予算が増えているんじゃないかなと思うんですけれども、この現状を踏まえますと、やはり介護のいろいろケアをするよりは、その以前に何とか手だてを打たなきゃいけないんじゃないか。こういう方たちに対して、各施設に利用人数に見合った安全ないすを常備できないかということをちょっと４点お答えください。","respondent":"早津高齢福祉課長、蓼沼高齢事業課長","answer":"回数を増やせば、必ずしもというものではありませんが、新しくできます小規模多機能という、亀田邸の後に利用しているところなどは、回数についても弾力的な運営がなされるというようなことで効果を期待しています。今後もそうした点は十分踏まえて運営をしていきたいと考えています。通所に関しましては、ちょっと今具体的に即お答えできませんけれども、実態をちょっとよく把握して、対応していきたいというふうに思っております。","voiceIndex":87,"id":"exchange-035"},{"speaker":"堺委員","kind":"質問","question":"私のほうからは、成果報告書１０９ページにあります心身障害者福祉会館運営費に関連をして、お伺いをします。","respondent":"西島障害者福祉課長","answer":"この食堂を設置をする工事とあわせて、従来事務所だったところを食堂にいたしましたので、事務所をつくらなければいけないという工事あるいは廊下がちょっと滑りやすくなっておりましたので、その辺の改修工事を実施しています。","voiceIndex":91,"id":"exchange-036"},{"speaker":"堺委員","kind":"質問・要望","question":"わかりました。快適な環境が整いましたので、よりいいサービスが区民に提供されることを望むわけです。これで１年経過を見るわけですが、この成果報告書の中ではこのように記載されております。要するに指定管理者制度が導入される以前、導入された以降、まだこの１年間ではっきりとした成果が出てこないのかもしれませんが、その辺のところをちょっと確認をする意味で教えていただきたいと思います。","respondent":"西島障害者福祉課長","answer":"１年たって、平成１６年度の問題は何だろうかというお尋ねだろうかと思いますが、指定管理者に指定をしまして１年目ということで、援護事業そのものは従来品川区総合福祉センターがやっている事業と関連しますので、その部分はちょっとおきまして。","voiceIndex":93,"id":"exchange-037"},{"speaker":"堺委員","kind":"質問・要望","question":"いわゆる中途失聴者の方々の状況ですね。そこで、私も実は相談を受けておりましたので、ちょっと何点かこの中で確認をしておきたいと思うんです。お願いしたいことは、こういう方々に、ぜひいろいろなことはあるかと思いますが、区としても全面的にバックアップをしていただきたい、こういうお願いなんですが、その辺はいかがでございましょうか。","respondent":"西島障害者福祉課長","answer":"さつき会ですが、これは区が心身障害者福祉会館で実施をいたしました要約筆記の講習会の卒業生の方を中心につくられた会でございまして、今委員がご案内いただきましたようにひばりの会と連携をとりながら中途失聴難聴者に対するいわゆる情報保障というんですか。","voiceIndex":95,"id":"exchange-038"},{"speaker":"堺委員","kind":"質問","question":"今ご答弁いただきましたので、よく理解はできました。先ほども関係団体の援助というようなことでお話がございましたので、ぜひひとつ重ねてこの辺のところについてのご見解をお尋ねしておきたいと思います。","respondent":"西島障害者福祉課長","answer":"利用者のコミュニケーションにつきましては、何せ心身障害者福祉会館ができたのが昭和５２年で二十数年の歴史がありまして、その間ずっと職員が携わってきたということで、十分コミュニケーションというか、お互いの気持ちがわかっていた部分があったのが。","voiceIndex":97,"id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０６ページの緊急通報システムと、それから介護保険についてお伺いをしたいと思います。この少し前に１度倒れたので、お友達の方が緊急通報システムを進めたそうなんですけれども、民生委員の方にお願いをしたら、お金がかかると言われたのであきらめたということでした。それとあと、利用者の実態が平成１６年度の総数と、それから民間型、直結型がそれぞれ何人の方が利用されているかも教えてください。","respondent":"早津高齢福祉課長","answer":"もちろん個別のご相談には詳細な説明をしますが、考え方としてはそのように対応しているです。","voiceIndex":100,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところでは、改めてＰＲもぜひしていただきたいと思いますし、この中身がわかるパンフレット、ちょっと私もインターネットで調べましたら、仙台市でこういうのは緊急通報システムの手引きというものでしっかりしたのをつくっていたんですけれども、ここまでいかなくてもわかりやすいパンフレットをぜひつくっていただきたいということでお願いをしたいんですが、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"いずれにしましても制度の周知というのはこの緊急通報システムに限らず、今後ともしっかり行ってまいりますし、先ほどの２つあるということについての周知についても改めて行ってまいります。","voiceIndex":102,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"介護保険では、特養ホームの入所調整会議が９月に行われたと思うんですけれども、今回の入所調整会議にかかった方の人数と、平成１６年度と比べて増えているのかどうか、それからあと、今回から三多摩の特養ホームの希望者を申し込みはそれぞれ行って調整会議にはかけない仕組みにしたというふうに聞いたんですけれども、そうすると。","respondent":"早津高齢福祉課長","answer":"今回、平成１７年度の９月に行いましたところでは、４８０人の申し込み、入所希望者がいらっしゃいました。その半年前が６５８人、さらに半年前が６８９、７０４、７２１、７０７人というような形で半年ごとの推移です。","voiceIndex":104,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのことを要望をしておきます。そこのところで、今、在宅を基本というふうなことで言えば、やはり在宅サービスをどんどん受けられるように、充実をしていくということこそが必要だと思うんですね。それで、品川区としても、ヘルプ、介護報酬の減額を財源にぜひこの負担軽減策を区独自の負担軽減策をしていただきたいというふうに思うんですが、この点に関しては、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"デイサービスにつきましては、確かに食費が外に出る関係で、例えば要支援の方ですと、今まで１回につき９０９円の自己負担を頂戴していたのが、１,０６７円と１５０円ほど負担増になるですが、これについては、先ほどの繰り返しになりますが。","voiceIndex":106,"id":"exchange-043"},{"speaker":"大沢委員","kind":"質問","question":"マスコミまたは新聞、週刊誌などの報道、刊行物などによって、個人情報ということに対して非常にいろいろな情報が飛び交っているということで、対象者の方がそれを個人情報という言葉を楯に事情を述べなかったりするというようなことが多々あると聞かれますが、その辺について、民生委員から行政側に情報を共有化する意味で、それは非常に支障を来すという部分がありますので。","respondent":"早津高齢福祉課長","answer":"この問題は、一方で個人情報をきちんと保護するという必要がある一方、民生委員のように、きちんとした守秘義務規定があり、なおかつ高齢者の福祉を増進しようという任務を背負っている方のよりＰＲにつとめる中で。","voiceIndex":110,"id":"exchange-044"},{"speaker":"大沢委員","kind":"質問","question":"新しく始まったということで、また新しい対応ということがあるんですけれども、今、高齢者のということとまた別の視点で、民生委員は児童委員も兼ねているわけですけれども、未然に児童虐待を防ぐには、やはりそれの疑いのあるところ、情報を是が非とも知りたい部分があると思うんですが、これは逆に今度行政の側から見た場合の、個人情報を守るという。","respondent":"早津高齢福祉課長、辻田児童課長","answer":"民生委員活動、それから児童委員活動は、法に基づく活動ですので、その法に基づく活動である限り、区とは必要な情報については、十分な連携をとりながら、対象者の保全等に努めているです。そういう形で、いわゆる知り得た秘密をむしろそういう場面では、きちっとした形で関係機関に通告しなければならないという義務がありますので、その辺につきましては。","voiceIndex":112,"id":"exchange-045"},{"speaker":"大沢委員","kind":"質問・要望","question":"この件については、私も前にも一般質問で区長にもお伺いしましたけれども、民生委員は、これから団塊の世代が非常に高齢化に向かいます。次に移ります。本年におきます平成１６年度におきましては、同じものを生活保護費弁償金なんですが、１,７００万円余、これが６７件、弁償金という性質上は、これはこのように３倍ですか、４倍になりますか、４倍に膨れ上がってしまっている。","respondent":"志村生活福祉課長","answer":"そのときに返していただく決定をするんですけれども、たまたま平成１７年度のこの事例の中にありましたのは、開始を始めた矢先に実は亡くなられてしまったわけです。","voiceIndex":115,"id":"exchange-046"},{"speaker":"大沢委員","kind":"意見","question":"非常に尊い税金ですので、そこのところは厳格にまた運用していただくようにお願いを、今回のように避けるべからざるような事態が起こったから４倍に時効が完成しちゃいましてこういう数字になりましたけれども、もともとそこのところ、またはどう言っていいかわかりませんけれども、税金の運用を厳正にお願いをいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-047"},{"speaker":"川西委員","kind":"質問","question":"初めに、成果報告１１１ページ、保育園業務システムの開発委託のこの年度の成果と今後の保育園運営にどうつながっていくか伺います。それについては、私はもう４月からの実施に向けて、施設の改造もあるかもしれませんが、今後児童センターはどう運営されるか、１日のカリキュラムをつくるためのプロジェクトみたいなものをつくるべきだというふうに思っておりますが、この辺いかがでしょうか。","respondent":"小林保育課長、辻田児童課長、高橋幼保一元担当課長","answer":"それで、その成果といたしましては、来年度以降、より適切に園の運営状況を把握することに役立ててまいりたいと考えております。０歳から１８歳までの子どもたちを対象とする、またその子育て家庭を対象にするということで、乳幼児への対応、特に在宅子育て支援というようなこと。それで、ぷりすくーるのほうの保護者補助金につきましては、区の一般財源の持ち出しで、東京都のほう、国のほう、どちらも補助金はなくて。","voiceIndex":119,"id":"exchange-048"},{"speaker":"川西委員","kind":"質問・要望","question":"私は、職員といいますか、担当者の方が周りの地域の皆さんが来るのを待っている姿勢ではなくて、いろいろ企画をして来られるような条件づくりをぜひしていただきたいと要望いたします。それで、これは総務費で質問すべきだったんでしょうか。これはぷりすくーるのほうは民生費に載っているということの違いを教えていただきたいと思います。それで、１つ質問を忘れました。これについてちょっと伺います。","respondent":"高橋幼保一元担当課長、小沼児童保健事業部長、辻田児童課長","answer":"ぷりすくーるの件ですけれども、こちら私立幼稚園でもなく、認可のときに総合施設というもので、建設した経緯がありまして、ここは総合施設に関しましては。こういうことです。平成１６年度につきましては、それを少し下回りまして５００人ちょっとという状況の中で、これは在宅子育て支援ということで児童課が担ってきている。","voiceIndex":123,"id":"exchange-049"},{"speaker":"川西委員","kind":"質問","question":"母子の方から相談がありましたが、じゃあ、ずっと３歳を越して、そういう支出が負担ならば、他の一般の保育園に移動してほしいというような指導もあったようですけれども、今後の総合施設、いわゆる保育園と就学前幼児教育施設に入った場合には、その負担が厳しければ、３歳になってから移動もやむなくというのが区のお考えなんでしょうか。その辺について伺います。","respondent":"高橋幼保一元担当課長","answer":"今後につきましても、総合施設は０歳から就学前の子どもを保育、教育するという部分でありまして、まだ総合施設の要綱等は出ていませんけれども、新しくつくる台場については、保育園型、幼稚園型の合築という形のすこやか園を倣ってつくっていくところですけれども。","voiceIndex":127,"id":"exchange-050"},{"speaker":"川西委員","kind":"質問","question":"次に移らせていただきます。１０５ページの特別養護老人ホーム建設費助成に関連してなんですが、これは、平成１６年度の実績として、これは特別養護老人ホームが少ないころにこういう制度ができたものですけれども、とりあえず平成１６年度の実績を教えてください。","respondent":"早津高齢福祉課長","answer":"これは三多摩地区の特別養護老人ホームのベッドを確保するための施策でございまして、ここに１０５ページの記載のとおり、６つの法人に対して年割でお約束の金額を支払ったです。","voiceIndex":129,"id":"exchange-051"},{"speaker":"川西委員","kind":"質問・要望","question":"本当は細かくもうちょっと細かく人数も知りたかったですし、それから、要望も知りたかったんですが、これはいいです。そういうので、これに類したようないわゆる品川区外にグループホームとか、いろいろケアホームとか、多少の自己負担ありで、そういうものが後にできてくることに対して、区がそれに類したような応援ができるかどうかということを、ちょっと方向性を伺います。健康。この２点。","respondent":"早津高齢福祉課長","answer":"区内のグループホーム等に同じことができないかというお尋ねなんですが、実は今度の制度改正、法改正の中で、グループホームは地域密着型サービスというジャンルに位置づけられまして、所在地の市民ないし区民でないと、基本的には入れないということになりましたので、事実上。","voiceIndex":131,"id":"exchange-052"},{"speaker":"川西委員","kind":"質問・要望","question":"今のさっき午前中の質問の中で、福祉カレッジの中で、研修をいろいろ進められているというのはほかの方の答弁で聞いておりました。私は、直接処遇に携わる方々の資質というものは今後区がある程度いつも目を光らせていく必要があるというふうに思っておりますので、要望といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":133,"id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"成果報告書の１０４ページ、１点目は民生委員経費に関連して、２点目は、路上生活者実態調査、ホームレスに関連してお聞きしたいと思います。民生委員に関しましては、今も質問がありましたけれども、この民生委員の今現在の人数と仕事の内容、そしてまた、定数があるんでしたら、充足率がどうなっているのか、今後また増やす方向にあるのかどうかということをお聞きしたいと思います。","respondent":"早津高齢福祉課長","answer":"定数、先般の一斉更新のときに定数を１６名増員いたしまして、現在は民生委員と並びに児童委員として兼任されている方が２８０人、それから主任児童委員になられている方が２６人ということで、３０６人です。定数は、両方合わせて３２２ですので、充足率９５％というものです。","voiceIndex":135,"id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"ただ、いろいろ仕事を各分野でかかわり合っているんですけれども、その中の１つの社会福祉協議会と民生委員とのかかわり、どんな形でかかわっているのかについて、お聞きしたいと思います。","respondent":"早津高齢福祉課長","answer":"今後、まず、人数を増やすかどうかですが、これは、この前回増やしたばかりですので、この間の状況を見ながら、また関係機関等とも相談して、対応を決めていきたいというふうに考えてあります。","voiceIndex":137,"id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"民生委員は本当に意識は高いんですね。あれがつらいと。何でこんな仕事があるのかしらというふうに言われました。民生委員の方の研修もしているんでしょうけれども、先ほども守秘義務の話もありましたけれども、そういう中で、奉仕の中で会員集めというのはどういう形で研修をされているのか、その辺をちょっとお聞きしたいと思います。","respondent":"早津高齢福祉課長","answer":"表面的には会費の納入みたいな形になりますけれども、それはそうではなくて、社会福祉活動への参加の取りかかりというような形で、新任の民生委員の研修会等ではそういうお話をしているんですが、実際上、かなり難しい面があろうかと思います。","voiceIndex":139,"id":"exchange-056"},{"speaker":"松澤委員","kind":"質問・要望","question":"それだけまた意識が高いということかもしれませんけれども、そんな中で、民生委員の経費の中に顕彰制度というのがあるんですけれども、これは国のものかどうかわかりませんが、品川区、東京都、国と分けて、民生委員に対するどんな顕彰制度があるのか、なければないということでお聞かせいただきたいと思います。","respondent":"早津高齢福祉課長","answer":"民生委員に対する顕彰制度としましては、まず品川区におきましては、自治功労の対象として民生委員活動を１０年お務めの方には普通表彰、２０年の方に特別表彰という制度があります。そのほかにも東京都の都知事の表彰制度があります。ちょっと年数等は申しわけございません。","voiceIndex":141,"id":"exchange-057"},{"speaker":"松澤委員","kind":"質問","question":"自治功労賞の件ですけれども、民生委員を兼任、民生委員と地区委員を兼任している、同じく１０年、２０年と表彰制度があるんですけれども、そういう場合に、合算して、若干短い期間で表彰できないかなと。やはりいろいろ頑張っているわけですから、そういうような優遇制度はあっていいんじゃないかなと思うんですが、それについて、お聞きをしたいと思います。","respondent":"本間総務部長","answer":"確かに他の職務と兼務されている方はいらっしゃいますが、それぞれのところで表彰するということで、それぞれの分野について、現在、表彰させていただいているところでございまして、年数をさらに短縮するということは考えてございませんので、よろしくお願いいたします。","voiceIndex":143,"id":"exchange-058"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。次のホームレスのほうの話に行きたいと思います。これも質問がありましたけれども、実態調査の中で５３人とか４８人とかいう話がありますけれども、これは実態調査しているだけでは意味がない。","respondent":"志村生活福祉課長","answer":"ですので、私どもは今までですと、こうしたホームレス等の相談窓口に参りますと、例えばそうした緊急一時保護センター等の紹介等で対応しています。","voiceIndex":145,"id":"exchange-059"},{"speaker":"松澤委員","kind":"質問","question":"東京都の地域生活移行支援事業の中では、ホームレスの方に３,０００円の経費で住宅を世話しよう、そのような形の中で、人数が減ってきているのかななんていうコメントが出ていますけれども、品川区でも減っているように感じるんですけれども、委員長に聞きましたら、まだ水神公園にはいるよなんていうお話がありましたので、なかなかなくならないのかなと思いますけれども。","respondent":"志村生活福祉課長","answer":"失礼いたしました。蒲郡市の条例のことについて、私はまだ承知してございませんので、これから検討します。","voiceIndex":147,"id":"exchange-060"},{"speaker":"本多委員","kind":"質問","question":"１０８ページの障害児放課後生活サポートやんちゃっこクラブと、１１１ページ、児童措置費、１１３ページ児童福祉施設費、それに関連して、質問をいたします。","respondent":"西島障害者福祉課長","answer":"その事業が平成１１年４月ですが、その事業が３年ほど続いたところで、区のほうでこの事業を応援しようということで、平成１４年４月から品川福祉工場のある品川児童学園内の一室を使いまして、実施をしたところです。","voiceIndex":150,"id":"exchange-061"},{"speaker":"本多委員","kind":"質問","question":"その辺が、ちょっと拡充ということがどうなったのかなと思いまして、それと、予算に対するこの執行率なんですけれども、その辺についても、運営について絡むんだと思うんですけれども、委託をされている運営について、１３時３０分から１７時までが基本サービスということでなっていると思うんですけれども、その実質的な付加サービスというところで、その仕組みといいますか。","respondent":"西島障害者福祉課長","answer":"あるいは早朝サービスとして、７時半から８時半まで、それからトワイライトサービスとして１７時半から２０時まで実施しているものもございまして、この分については、別途このＮＰＯ法人が料金を利用者からいただいているというふうになってあります。","voiceIndex":152,"id":"exchange-062"},{"speaker":"本多委員","kind":"意見","question":"それと、この利用者なんですけれども、養護学校の在校生などが対象ということだと思うんですけれども、区内在住の心身障害児、養護学校にするかしないか、本人また親の判断があると思うんですけれども、その辺の養護学校に入っていない方でも、利用できるのかどうか、その辺をお聞かせください。","respondent":"西島障害者福祉課長","answer":"事業の当初の趣旨としては、主に養護学校の在校生等を中心にということでございましたけれども、それ以外に障害児の方でご希望の方があれば、受け入れているところです。","voiceIndex":154,"id":"exchange-063"},{"speaker":"本多委員","kind":"質問・要望","question":"例えば子育てガイドなんかも見ますと、この保育所から医療から、幼稚園、保育園、それぞれもう総合的に品川区が施策を打っているというふうに感じるんですけれども、これまでの施策を打つに当たりまして、現場の区立、私立、保育園、幼稚園の関係者との協議といいますか、話し合いについて、どのようにしたのか、また今後の施策に移るに当たりましてどのように対応していくのか。","respondent":"小林保育課長","answer":"その際に、園の状況ですとか、今後の課題等意見を聞かせていただける場合もあります。私立保育園につきましては、定例的に各園の会合を開催していただいておりますので、その際に必要に応じて、ご説明に上がったり、また意見を頂戴したりという連携をとらせていただいております。","voiceIndex":156,"id":"exchange-064"},{"speaker":"本多委員","kind":"質問・要望","question":"総合的なところで、お伺いしました。幼保一元化に限って、改めてそのことをお聞かせいただきたいと思います。","respondent":"高橋幼保一元担当課長","answer":"今回、台場につきましては、やはり地域の方たち、保護者の方たち、そういった方たちとの説明会を開きながら、どういう形で進めていくのが一番いいかなということを連携をとりながらやっているです。","voiceIndex":158,"id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問","question":"私は、国民健康保険と介護保険の２つの特別会計に関連して伺いたいと思います。そういう実態だと思います。そこで、ちょっと伺いたいんですけれども、特に私はリストラ等で失業された方々への保険料の減額とか免除制度、これはどうしても必要だというふうに私は思います。それともう一つは、今時点で短期証と資格証をどのくらい発行されているのか、伺いたいと思います。","respondent":"原国保年金課長","answer":"そういった意味で、２３区統一で今申請減免の関係をやってありますけれども、それに対して、品川区として、特に独自でつくるという考え方は現在のところ、もってございません。それから、短期証等の件数のことです。","voiceIndex":161,"id":"exchange-066"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私はぜひリストラ等の方には猶予だけではなくて、減額の制度をぜひつくってほしいということで、再度お願いしておきたいと思います。そこのところは私はぜひそういうところでも改善してほしいということを言っておきたいと思うので、それは要望しておきます。それと、この額が１号被保険者６５歳以上の方１人当たり幾らになっているのか、お伺いしたいと思います。そういう実態になるかと思うんです。","respondent":"早津高齢福祉課長","answer":"多岐にわたっておりまして、ちょっと答弁漏れがありましたら申しわけございません。基金の残高ですが、平成１７年度末現在で１８億５,７９４万円です。６万２,０００人で割りますと、１人２９万９,０００円ですから、約３０万円ぐらいということになろうかと思います。","voiceIndex":163,"id":"exchange-067"},{"speaker":"宮崎委員","kind":"確認","question":"先ほど１人当たり２９万９,０００円というのは、それは確かかどうかちょっと確認しておきたいんですけれども、あと、事業費のほうですね、今度は保険制度の変更で、かなり出入りが出てくるんじゃないかというふうに思うんですけれども、今、事業費の点ではわからない人も、例えば品川区は今まで特別給付としてやってきた均等割が、今度は保険給付に入るんで、これは、そういう意味では。","respondent":"早津高齢福祉課長","answer":"委員ご指摘のように、例えば特別給付の市町村特別給付で行っている身近でリハビリ等については、新しく新予防給付という法内化がかなりの部分されるかと思われますが、一方で、増要因となります地域支援事業というようなものもありますので。","voiceIndex":165,"id":"exchange-068"},{"speaker":"宮崎委員","kind":"質問・要望","question":"６５歳以上の１人当たりの人が約３万円ということになるわけですね。これは、１年間１万円ということですが、単純計算で。これを強く要望しておきたいと思います。ですから、これはぜひ鈴木ひろ子委員も紹介しましたけれども、千代田区とか、港区とか、荒川区では、引き上げないように、いろいろ努力しています。この検討をぜひ求めたいと思うんですが、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"お尋ねの減額制度、千代田区等の関係ですが、先ほど言いましたように、５０円というような緩和措置もとっていることでもありますし、２３区を比べても高いという状況でもありませんので、特段考えてはございません。","voiceIndex":167,"id":"exchange-069"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この６００円は非常に高いというのは、例えば普通の町場のそば屋に行くと、６００円を出すと何が食える。例えば、あとはコンビニでも弁当は大体５００円内に抑えています。５９０円ですよ。私は、民間の努力ということであれば、それを学べというのであれば、やはりこうした努力を学んでほしい。そうやって、区民にサービスを見えるようにしてほしいということを強く要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-070"},{"speaker":"山路委員","kind":"質問","question":"品川区も、こういう団地におひとり暮らしで生活保護世帯の方がいらっしゃるわけですが、現場に行きますと、品川の生活福祉課の方が連携をとってよく面倒を見ていただいているという非常に高い評価は聞いているわけですが、ここで、品川区も団地が多いので、人権を守るという視点で、改めてその安全・安心確保はどういうふうにやられているか、お伺いをいたします。","respondent":"日下部企画財政課長、小林保育課長、志村生活福祉課長","answer":"それで、実際の実績が出ますのは、これは年度の最終段階、年度末になりますので、そうなりますと、当初の見込みとそれから最後の実績と。病児保育の利用実態をというお尋ねですけれども、ご承知のとおり、病児保育につきましては、本年１月から施行し。私どもの生活保護受給開始あるいは廃止、世帯に変動がありましたら、私ども民生委員の方に連絡を文書で通知しています。","voiceIndex":171,"id":"exchange-071"},{"speaker":"山路委員","kind":"質問・要望","question":"返還金につきましては、詳しい説明内容をありがとうございました。よく勉強させていただきました。それで、品川医師会の先生も積極的な先生もいらっしゃるやにお伺いしているんですが、病気の子どもを抱えた働くお母さんたちから、とても大事な私たちの生活に大事な事業ではないかという意見もありますので、その辺の今後の考えを聞かせていただきたいと思います。","respondent":"小林保育課長","answer":"ちなみに、ちょっと中途の数字なんですけれども、例えば９月は４５名の利用がございましたが、それをほぼ住所別に見ますと、大崎、大井、荏原という部分で、６２％ほどになっておりまして、品川地区は３３％ほどの割合になっているかと思いますので。","voiceIndex":175,"id":"exchange-072"},{"speaker":"山路委員","kind":"質問・要望","question":"品川地区が３０％ですか、まだちょっと遠いんですね。百反坂を登ってずっと医院のところに。近かったら、もっと利用したいという声はたくさんあります。先生も熱心な先生もいらっしゃいますので、医療機関とかクリニックとかいろいろな条件もありますので、一概には申し上げられませんけれども、品川地域に病児保育の箇所を設けていただくことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-073"},{"speaker":"林（宏）委員","kind":"確認","question":"成果報告書の１１０ページ、児童福祉費に絡んで、幾つかお伺いしますけれども、その前に、国保、老人医療、それから介護と決算が出ているんですけれども、決算特別委員会ですから、数字の確認だけちょっとしたいと思いますけれども、国保の１５７ページに利子の収入があります。","respondent":"冨田副収入役、高橋幼保一元担当課長","answer":"それで、これは、普通預金、平成１６年度は普通預金をしておりましたけれども、現在は、決済用預金ということで、平成１７年度以降は原則なくなりました。平成１６年度までの措置です。お尋ねのぷりすくーるが１０カ月たった評価ということで、民間企業の活力を生かした評価ということで、どういうふうに考えているかですけれども、評価につきましては、１０カ月の中で、協定書も含めまして、民間活力等について。","voiceIndex":180,"id":"exchange-074"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"ぷりすくーるですけれども、今の答えがこれから、指定管理者はいろいろきゅりあんだなんだとやっていくんですけれども、その程度の我々に対する説明ですか。その行動計画が３月の末に発表されて、４月から計画に沿って行動がされているんでしょうか、されていないんでしょうか。それから、この計画の一番後ろに協議会の要綱があるんですけれども、今もこの協議会というのは、活動しているんですか。","respondent":"新美企画部長、榎本行財政改革担当課長","answer":"ということで、基本方針にも述べておりますとおり、各事業部での評価、そしてさらに全庁的な評価という２段階の評価システムを確立していきたいというふうに考えております。それで、こちらの推進状況を報告して意見をもらう形をとる予定です。","voiceIndex":183,"id":"exchange-075"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"私立幼稚園、私立保育園、公立保育園、公立幼稚園、それから在宅、それぞれ就学前の子どもたちへどのように財源が配分されているのかというのもききたいですけれども、もう時間がないから、数字はまたあとでお聞きしますけれども、きちんと配分がなされた上で、私は私立幼稚園をどう活用していくのか、この一番最後の行の民間活力を引き出すというのは、幼稚園に関しては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-076"},{"speaker":"井上委員","kind":"質問・要望","question":"私からは成果報告書１１１ページの保育サービス、第三者評価経費と、１１２ページの児童福祉施設費、家庭安心センター運営費、１１３ページの学童保育運営費に関連してお伺いいたします。成果報告書の児童福祉施設費のところなんですけれども、園児経費と維持管理費の金額が２００３年度と２００４年度では大きく異なっているのですが、この金額の違いの理由を教えてください。","respondent":"小林保育課長","answer":"お手元にお届けいたしました主要施策の成果報告書、今年度から、従前は保育園運営費の中で、園児経費、施設管理費、設備充実費というふうに従前大くくりであったものをより審査に適するようにということで、項目別に分解をいたしましたので、若干例年と表示が異なっております。","voiceIndex":188,"id":"exchange-077"},{"speaker":"井上委員","kind":"質問","question":"わかるように分解して、内訳を書かれたということですけれども、２００４年度の予算書でみますと、保育士補助と非常勤職員経費というのが、掲載されていませんでしたが、今回の決算書では、はっきりと区民に見える形で載せているわけですけれども、この点について理由をお伺いいたします。","respondent":"日下部企画財政課長","answer":"ただいま保育課長のほうから申し上げましたように、実際の決算報告の項目の整理、できる限りわかりやすくですけれども、実は具体的に申し上げますと、平成１７年度の当初予算の段階でも、ご覧いただきますと、今。","voiceIndex":190,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"ここで、予算書のほうで保育士補助と非常勤経費というのを改めてここに出されたというところでは、これから非常勤職員を恒常化して、そういった意味で、ここに載せたのかということを考えられるんですけれども、その辺についてはいかがでしょうか。","respondent":"小林保育課長","answer":"特に非常勤職員について、この表示があらわすような形で方針が何か変わったということはございません。","voiceIndex":192,"id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"わかりました。それで先ほど私がお伺いしたかった保育士の正規職員と非常勤職員の割合はというところで、先ほど飯沼委員の質問で、正規職員が５６９人、非常勤職員が４１４人ということで、答弁がありましたけれども、これらの保育園の非常勤職員の採用規定とか雇用期間なんかは、どのようになっているんでしょうか。","respondent":"小林保育課長","answer":"非常勤職員は本年度より主に３時間ないしは４時間の雇用形態というふうになっております。それでこちらは基本的には１年を任用期間にするものと、それ以外に２年３年という期間を任用形態とするものとに分かれております。","voiceIndex":194,"id":"exchange-080"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちも３時間、４時間の保育士の子どもに対する向き合いかたがどうかという疑問を持っているんですけれども、子どもたちにとって、そういう人がかわるということで与える影響をもう一度子どもの視点で考えていただきたいと思いますし、一方、働く側の立場としても、生きがいをもってこの場所で働けられるのか、そしてまた安定した保障というものがあって、やっぱり私たちもそうですけれども。","respondent":"小林保育課長","answer":"そういった意味で、円滑に業務をこなす上で、どういうような配置をしていくかということは、毎年見直していくつもりで対応しております。","voiceIndex":196,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ子どもの声はなかなか小さくて難しいかもしれませんけれども、この子どもの様子をきちっと把握していただくことや、皆さん働く方も保護者の声もきちんとお伺いした上で、これから子どもにとっての最善の利益を考えた体制づくりをしていっていただきたいということを要望します。","respondent":"小林保育課長","answer":"福祉サービスの第三者評価事業につきましては、平成１５年度から開始いたしまして、本年度平成１７年で全園評価を終了できるという段階に来ております。","voiceIndex":198,"id":"exchange-082"},{"speaker":"井上委員","kind":"質問","question":"それで、今のような状況を保護者の方にどういった形で返されたのか、お伺いをいたします。それから、平成１７年度で全園が終了するということですけれども、今後、この第三者評価は終わるのか、また継続するのか、いかがなんでしょうか。","respondent":"小林保育課長","answer":"今後の事業のことですけれども、これから政策予算等を経まして決定されますが、保育課としては引き続きこの事業を継続させていただきたいと今は考えております。","voiceIndex":200,"id":"exchange-083"},{"speaker":"井上委員","kind":"質問・要望","question":"結果、せっかくきちんとした評価をされたわけですから、ぜひとも保護者の方に各園のデータとして個別にお返しいただきたいということを要望いたします。それで、現在障害を持つ子どもたちの放課後や長期休みの居場所などはどのように対応されているのか、お伺いをいたします。","respondent":"辻田児童課長","answer":"学童保育クラブ、ことしは１３カ所で実施しておりますけれども、その中でたしか７人のお子さんをお預かりしております。そういう意味では、それから既にこれだけ少なくなったというのは当然すまいるスクールのほうにも障害を持った方が行っているということです。","voiceIndex":202,"id":"exchange-084"},{"speaker":"井上委員","kind":"質問","question":"それで、２０日間預けると、９万円という費用になる。そしてまたここで送迎が必要とすると、１回５５０円ということになるんですけれども、このことに対して区としてはどのようにお考えでしょうか。","respondent":"西島障害者福祉課長","answer":"たしかに、利用の形によっては、多い方もいらっしゃいます。現在、障害児の放課後対策につきましては、それぞれいろいろな課題がありますけれども、関係する児童課、それから教育委員会、障害者福祉課の中で今後のことについて現在検討を始めている最中です。","voiceIndex":204,"id":"exchange-085"},{"speaker":"井上委員","kind":"質問","question":"そういった中で、現在でもすまいるスクールに通いたくても通えないお子さんが今いらっしゃる。そして、そういう中で、すまいるスクールの利用のときにかかる費用とか、今言いましたような多額の費用負担の差があるということでは、差額の補助も考えていくべきだと思いますけれども、その辺のお考えはいかがでしょうか。","respondent":"西島障害者福祉課長","answer":"それで、この事業は区が始めて３年で、今年の９月に荏原地区で国のタイムケア事業を活用いたしまして、荏原地区でも同様の事業を実施しています。今後、この事業を利用者のニーズあるいは利用者の意見等さまざま聞きながら、まだ始まったばかりの事業です。","voiceIndex":206,"id":"exchange-086"},{"speaker":"井上委員","kind":"質問・要望","question":"さまざまな選択ができる施設が増えてきたということでは、保護者のほうでも歓迎するところであるかと思いますけれども、やはり障害によって区別されるような施設ではなくて、すまいるスクールなど学校改築など広がってまいりますけれども、そういったところで改修を重ねて、障害による区別をしないで、一緒にともに学べる、そして育てるような環境をぜひ品川区で子どもたちの支援ということでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問","question":"それについて。それから、保育サービス第三者評価費と、１１２ページの児童センター運営費について、ご質問したいと思います。子育て支援総合推進モデル事業、ここに普及啓発セミナーとか、取り組み事業、事例集作成費というふうにあるわけですが、これらはどういうものなのか、今どういう形で進んでいるのか、その辺をお尋ねします。","respondent":"辻田児童課長","answer":"そういう中で、まず、昨年の１２月１１日にゲートシティ大崎、ゲートシティホールのほうで子育て普及啓発セミナーということで、トークショー、それからアトラクション、お子さんがやっぱり一緒に参加できないとまずいということで。","voiceIndex":210,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"これは、品川独自というよりは、東京都ですか、おろされてきたという形でやっているのか、品川区としての位置づけというのはどういう位置づけで、これを行ってきたのでしょうか。たしかに好評だということの、アンケートの結果、そうではあると思いますが、実際にどういう問題が区にあって、この制度を利用して、どういうふうにしていこうかと。これは将来的にどうするのかという、その辺はいかがでしょうか。","respondent":"辻田児童課長","answer":"これは何か問題があったからこういうことをやったということはございません。いわゆる品川区としては、非常に先駆的な取り組みをしているということで、いわゆる区からいろいろな情報を発信してほしいというような形の要請がございました。","voiceIndex":212,"id":"exchange-089"},{"speaker":"西本委員","kind":"質問","question":"たしかに品川区では、いろいろな施策をされておりますので、それが他のところ、他の自治体に広げていくということは、当然先駆的なところからは、役割なんだろうなというふうに思っておりますが、将来性としてはどういうふうにこの事業が発展していこうとしているのでしょうか。","respondent":"辻田児童課長","answer":"こういうようなことを実施するというからには、今後につきましては、次世代育成支援をさらに推進して、先駆的な立場で事業を推進していかなければならないという道義的な責務というんですか、そういうものが発生してくると思います。","voiceIndex":214,"id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"ぜひ品川区では、かなりの実績があると思いますので、今、次世代育成推進のほうと絡めてという話もありましたので、さらなる発展をお願いしたいと思います。次に、ＩＳＯが今回項目に入っていないんですが、それはどうしてでしょうか。","respondent":"小林保育課長","answer":"ＩＳＯ１４００１につきましては、各園取り組みが進みまして、基本的に外部委託の委託料を払って何かをするということではなくて、みずからかかわりながら、内部審査も含めて、安定運用の時期に入りましたので、特段の費用の計上はございませんでした。","voiceIndex":216,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"ほぼ全園でＩＳＯの導入が終了ということなのでしょうが、ＩＳＯを導入しまして、質の向上になっているのかどうか、その辺の評価はいかがでしょうか。","respondent":"小林保育課長","answer":"その１件１件の事例をもとにして、その原因、要因、今後の対応等が分析できる体制が整ったという意味では、まさにサービスの水準を維持する基本的なベースラインに立てたというふうに思っております。","voiceIndex":218,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"最低ラインのところは、抑えるにしても、応用編という形でそれぞれが対応できないといけない。特に、管理者等々についてはその応用ができなきゃいけないというふうに思うわけですが、その辺はいかがなんでしょうか。どこの位置まで来ているのでしょうか。じゃあ、その応用編そしてそちらにいこうとしているのか、逆にそれが束縛、制約につながっていないだろうか、その辺の評価はいかがでしょうか。","respondent":"小林保育課長","answer":"現場では、いろいろなお求めがあります。それについて、すべてマニュアルに書いておくこともできませんし、マニュアルどおりやれというのも現実的な対応ではございません。","voiceIndex":220,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問","question":"こうやっちゃいけない、ああやっちゃいけないという指導の中にあると思いますが、ある程度の権限を持たせておいて、その臨機応変にやっていくような、そういう指導、経営能力、それから現場対応ができるような、そういう教育といいますか、研修といいますか、そういう方向にぜひとも行ってほしいという願いがあるわけですが、そういうお考えはいかがでしょうか。","respondent":"小林保育課長","answer":"それにつきましては、どこまで規制、統一、処理手順にするのか、どこから判断の余地にするのか、それは一律定めるものではなくて、個々の事例の中で積み重ねて共通で品川区の保育サービス水準として考えなきゃいけないものは、統一手順に入れ。","voiceIndex":222,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問・要望","question":"職員の思いと、それから保護者との思いがずれていたというところが一番大きな問題ではないかなというふうに私は思っていたんですが、その辺のずれの補正というのはどういうふうになっているのか、それから、これからも続けられるということをおっしゃっていましたけれども、これは確か東京都のほうからの考え方でおりてきたものの１つですけれども、その内容的に、ある程度の型にはまって。","respondent":"小林保育課長","answer":"それで、具体的には、利用者のアンケートが一定まとまりました中で、園内研修等でそのまとめ、資料を見ることによって、自分はこうやって思ってこうやっているという自己評価なんだけれども。","voiceIndex":224,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問・要望","question":"なかなかそれは気付かないところでありまして、それを気付かせてくれるというのがこの第三者評価の大きなメリットではないかなと私は考えますので、それのマッチングをどんどん推進して改善をしていただきたいというふうに思います。次に、児童センター運営費ですが、１１２ページの利用状況をみますと、利用状況が書いてありますが、これはどこから集めた数値になりますでしょうか。","respondent":"辻田児童課長","answer":"この数字は各２５館の児童センター、それの利用者を集めたものです。","voiceIndex":226,"id":"exchange-096"},{"speaker":"西本委員","kind":"質問","question":"この来館者数ですか、利用者というのはいろいろあると思うんですが、どういうカウントの仕方をしていますでしょうか。","respondent":"辻田児童課長","answer":"基本的に利用者です。ただ単に来たというだけではなく、その中で利用をした人数です。","voiceIndex":228,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問","question":"子どもたちも名前を書くんですね。当然なんですが、先ほど来、児童センターの役割というのが、今後大きく変わっていくよと、ティーンズプラザとか、それから乳児、幼児の施策ということの中心になっていくというふうなお話であるわけですけれども、じゃあ、小学生はどうなんだろうかと。すまいるスクールの中で解決してしまうことなのか、児童センターにおける小学生の考え方はいかがでしょうか。","respondent":"辻田児童課長","answer":"それから小学生につきましては、これは０歳から１８歳までの施設ですから、小学生も当然利用する施設です。ただ、すまいるスクールを本拠地としながらも、放課後は、ただすまいるスクールであきたらない高学年の子どもたちが、来ていることも確かです。","voiceIndex":230,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、今後の展開としては、これは要望になりますけれども、小学生、すまいるスクールはありますけれども、その中での位置づけを放課後だけではなくて、成長という中での位置づけで、ぜひ運営を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-099"},{"speaker":"石田委員","kind":"質問","question":"それで、これからこういうふうに増えていくんだという部分がありますが、その方々をどのように今していこうと、どういう予測を立てていらっしゃるのか、そこら辺の点をお聞きをしたいのと、あと、生活保護費の中の住宅扶助の部分で、もちろん最高限度額があると思うんですが、単身の方とあとは二人以上の方の金額をできましたら教えていただければありがたいと思います。","respondent":"蓼沼高齢事業課長、志村生活福祉課長","answer":"ソフトな施策の考え方ですけれども、先ほどもお答えいたしましたように、高齢者住宅、総合的な取り組みをしてまいりまして、この２２０戸のストックの運用。品川区の区域内ですと、単身の場合５万３,７００円、それから２人以上になりますと、６万９,８００円です。それから、７人以上になりますと、８万３,８００円以内、このような基準になってあります。","voiceIndex":234,"id":"exchange-100"},{"speaker":"石田委員","kind":"質問","question":"そういうところに行政側も政策的にお２人や３人で一緒にどうぞ、高齢者同士で仲のいい方もいいんだけれども、そういうのを募集すれば、必ず今そういうものもできる、グループができるわけで、そういう区民住宅の部分を利用して３名の方で住んでいただくとか、そういう政策的な転換をソフトの部分でやっていくことが私はこれからの時代に即したことで。","respondent":"蓼沼高齢事業課長","answer":"ひとり暮らしの方への不安感というようなものは家主がお持ちだというのは十分認識をしています。","voiceIndex":237,"id":"exchange-101"},{"speaker":"石田委員","kind":"質問","question":"ぜひ研究していただいて、よろしくお願いいたします。民生費のことだけ、ちょっとだけ触れます。こういう形のものを考えると、今後、非常にタックスペイヤーに対しての説明責任は必ずあるんだろう、私は思っております。ですから、ある程度、今厚生委員会では少し出てきましたけれども、受益と便益についてやり出しました。","respondent":"日下部企画財政課長","answer":"そういう形でここから直接その今おっしゃったような受益と便益というのが、即読み取れない面はありますけれども、こういう形で区のほうとしてもいろいろな努力をしていますので、その辺はご指摘の点も含めまして、今後また少し検討をさせていただきたいというふうに思います。","voiceIndex":239,"id":"exchange-102"},{"speaker":"石田委員","kind":"質問・要望","question":"今、それの話は知っておりますが、ぜひ１つの事業、こういう先ほど言いました高齢者等いろいろあるわけですけれども、１つのものが読み取れるような資料をぜひ私はつくるべきだと思いますので、これは要望でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-103"},{"speaker":"須藤委員","kind":"質問","question":"１０４ページの社会福祉費に関連して何点かお尋ねします。それから、福祉カレッジの、平成１６年度に何名ぐらいそこで研鑽されたのか、教えてください。","respondent":"早津高齢福祉課長","answer":"平成１６年度の福祉カレッジにおきましては、大きくケアマネジメントのコース、こちらは合計で６５名の修了者、主任ヘルパーのコースでは６９名、それから、今の２つが年間を通じたカリキュラムですが、特別講座として医療知識のコーナー。","voiceIndex":243,"id":"exchange-104"},{"speaker":"須藤委員","kind":"質問・要望","question":"１０９ページの心身障害者福祉会館費で、これは先ほど質問が出ましたけれども、指定管理者制度をとって１年になって、先ほどのお答えでは順調に移行していますというようなお話が出たんですけれども、先ほど来あったように、指定管理者制度をとって、サービス向上と効率的な運営ということが求められているので、そこがどうなっているかということを聞かせもらってこないと。","respondent":"早津高齢福祉課長、西島障害者福祉課長","answer":"一方で、この奨学金は成績の優秀なといいますか、優秀な卒業生を区内にできるだけ入れたいというような思いもありまして、そのために就学状況の中で難しいという人間も出てまいります。経費につきまして、直営との全体の比較ですけれども、単純な比較というのはなかなか支援費が入りますので難しいかと思いますが、９,０００万円ぐらい経費としては少なくなったのではないかというふうに判断しています。","voiceIndex":245,"id":"exchange-105"},{"speaker":"須藤委員","kind":"質問","question":"１０５ページのところで、各種助成金、それから１０４、１０６ページぐらいのところにある運営費について、お尋ねします。そういったような出し方というのがいろいろ出てきているんですけれども、その辺の根拠は何かあって、そういう形になっているのかどうか。そうすると、区と連携が今までどおりの形でいっちゃうことがいいことなのかどうなのか。","respondent":"早津高齢福祉課長","answer":"１０床ずつのベッドを確保しておりますので、７０床ということになりますが、いずれの法人も、そのベッド数にプラスして、品川区民を若干名受け入れていただいておりますので、７０名プラスアルファで、ちょっと数字があれですけれども。","voiceIndex":248,"id":"exchange-106"},{"speaker":"須藤委員","kind":"意見","question":"設立時の関係でこういう調整というのがなされてきている。その後で、また運営費で補助をされているというところがあるんだけれども、その辺はどういうふうに考えていけばいいのかと思うんです。","respondent":"早津高齢福祉課長","answer":"ところが、これは東京都は区立施設には行いませんので、区が都にかわって、区立施設の特養についても都と同様な観点からの補助を行っているというのが１つでございまして、そのほかにも例えば、戸越台特養ホームなんかの場合は、１０階建てになりますので。","voiceIndex":250,"id":"exchange-107"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、指定管理者制度等々になってきても、こういったものは、今までどおりの形で、変わらずにという状況になってくるというふうに考えてよろしいんでしょうか。今までは介護保険制度が入れば、老人保険のほうはいわゆる医療費がセーブされますよというような話で来たんだけれども、そのあたりはいかがですか。","respondent":"早津高齢福祉課長","answer":"先ほどの続きのご質問もありましたので、指定管理者制度になったからといって、今、ご説明したことについての考え方は基本的には変わらないものと考えています。それから、繰出金につきましてですけれども、介護と医療費とかというような相互に関連があります。","voiceIndex":252,"id":"exchange-108"},{"speaker":"須藤委員","kind":"意見","question":"というのは、ここで３つの繰り出しを出しているんですけれども、介護保険制度を導入することによって、医療費がある程度違ってきますよという考え方で介護保険制度をスタートしてきたと思うんですけれども、それも１つあったと思うんだけれども、そのあたりと、こういった全体を見ていけばいいんだけれども、ぱっと見たときに繰出金というのが、今度は老人医療費が改定になったんで。","respondent":"新美企画部長","answer":"全体に高齢者、高齢化が進みますので、医療費の全体の抑制は今国が検討しています高齢者医療費制度、あるいは国民健康保険、各健康保険制度の改革等で検討し、実行していく、そういうテーマかと思われます。","voiceIndex":254,"id":"exchange-109"},{"speaker":"南委員","kind":"質問","question":"１０７ページの心身障害者福祉費に関係してお尋ねをしたいと思います。そもそも障害者福祉の理念というのがどういうものなのか、ちょっと改めてお伺いして、まずそこから入っていきたいと思います。","respondent":"西島障害者福祉課長","answer":"なかなか難しい質問ですが、障害あるなしにかかわらず、いわゆるノーマライゼーション社会のということで、障害を持ちながらも自分らしく生きていけるために福祉というものがあるのだというふうに理解しています。","voiceIndex":257,"id":"exchange-110"},{"speaker":"南委員","kind":"質問","question":"それで、今、障害者自立支援法という法律整備が国会の中でまた上程されて議論が始まっておりますけれども、この法案の中身というのが非常に重大な問題を含んでいるというふうに私は認識しておりますけれども、特徴としてはいくつかありますけれども、一、二私が考えているところでは、施設の利用料を一律に１割負担とするということ、そして。","respondent":"西島障害者福祉課長","answer":"ただ、私どもに入ってきている情報は、いわゆる新聞情報以外に１０月１１日に全国課長会が行われて説明があるというふうに聞いてありますので詳しくはその中で入ってくるということで、今、軽々に中身について議論するのはいかがかというふうに思っておりますが。","voiceIndex":259,"id":"exchange-111"},{"speaker":"南委員","kind":"質問・要望","question":"そういう仕事による賃金は平均額でいいですから、どのくらいいただけているのか、月額、そのご紹介をまずいただきたいのと、あとは、知的障害者の通所施設というのがありますよね。西大井福祉園のケースでいいんですけれども、ここでもやはり賃金というか、工賃というんですか、それが大体平均額でどのくらいになっているのか、それをちょっと紹介していただきたいと思います。","respondent":"西島障害者福祉課長","answer":"知的障害者の授産施設ですが、これも施設のやる費目あるいは人員等によって違いますが、この金額も８,０００円から多いときは３万円程度というふうに私は理解しています。","voiceIndex":261,"id":"exchange-112"},{"speaker":"南委員","kind":"質問","question":"７,３００円ぐらいでしょうか。これは現場の声の紹介です。精神障害の方はとりわけ通っていってみんなでいろいろな活動をすることが生きていく意欲にも生きがいにもなっているということで、払えないことでいかなくなってしまったら、本当に生活そのものが今まで積み上げてきたものがめちゃめちゃになっちゃうというんですが、そういうところについては、どういうふうに認識を持っておられるでしょうか。","respondent":"西島障害者福祉課長","answer":"それで、こういう方の中には、一定の負担をしていただくという部分はどうなんだろうかというようなところもやはり議論になるところですので、その辺も含めて、トータルにものを見ていただければというふうに考えているところです。","voiceIndex":263,"id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"トータルでものを見ることは大事だと思います。しかし、私が今問題にしたかったのは、１８万５,０００円という例示を挙げられましたけれども、そういう方がどれだけおられるのか、それとあと、こういう金額、収入をいただけない方がどれだけいらっしゃるのか、ちょっと私もそこのところを何人ぐらいいらっしゃるのか、ちょっと伺いたいと思います。","respondent":"西島障害者福祉課長","answer":"その辺については、プライバシーにもかかわりますので、なかなか難しいところですが、現在手元に細かい資料というのは、持ち合わせてございません。","voiceIndex":265,"id":"exchange-114"},{"speaker":"南委員","kind":"質問・要望","question":"何人ぐらいおられるのかということだけですからね。それで、日弁連がこの問題だらけの障害者の自立支援法の修正を求めるという、この修正というのは、私たちはちょっと見解は違いますけれども、しかし、修正を求める要望を今年の６月２３日に出しているんですよね。そういう立場で、やっぱりきちんと必要な発言というのはしていくべきだと思いますけれども、いかがでしょうか。","respondent":"西島障害者福祉課長","answer":"最後ですが、障害者５団体が本法律について、早期成立を望むというメッセージを出してというふうに私どもは確認しています。","voiceIndex":267,"id":"exchange-115"},{"speaker":"南委員","kind":"質問・要望","question":"私は非常に残念な姿勢だと思います。もっともっと社会的な支援をしていける、そういう立場で担当していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-116"},{"speaker":"木下委員","kind":"意見","question":"その中ではセーフティネットというのは、全然政府のほうは考えられないと考えていますので、自治体のほうがそういう点では区民生活に密着したセーフティネットという部分である程度区民生活をある程度支える緩衝材になるべきじゃないかなと私なんかは思っているんですが、そういう考え方に対して品川区としては、ご意見としてどのように思っていらっしゃいますか、ちょっとお聞かせください。","respondent":"日下部企画財政課長","answer":"ただ一方で、いろんな面で、なかなか自立自助、そういうことがなかなか難しい方もいらっしゃるわけですから、それはそれで社会全体としてのセーフティネットの中で、支えていく、その辺のバランスをこれからどうとっていくか、その辺が非常に重要ではないか。","voiceIndex":271,"id":"exchange-117"},{"speaker":"木下委員","kind":"質問・要望","question":"よろしくお願いしたいと思います。その観点でもってもうちょっと私は質問をさせていただきたいと思うんですけれども、高齢者の方が総務省の敬老の日にあわせた推計値によりますと、５人に１人、２０％になっているということで、先ほどお話があったように、高齢化というのはかなり進んでいっている。７０歳から７４歳の現役並み所得者が２００６年度税制改正で約８０万人増える。","respondent":"蓼沼高齢事業課長","answer":"高齢者の医療のお話ですけれども、今委員がご指摘の高齢者医療の本人負担、窓口負担を３割にする、それから税制改正の関係で、今の２割負担対象者が増えるというのは、例えば、後段の２割負担の対象者が増えるというのは、これは税制改正の関係で、新聞報道ですけれども。","voiceIndex":273,"id":"exchange-118"},{"speaker":"木下委員","kind":"質問・要望","question":"そして他の委員の質問の中で、認知障害の方々の人数ですとかお聞きしておりますけれども、それだけ大勢の方々が認知症でいらっしゃるし、徘徊の状況もあられる方々もいらっしゃるということですから、品川区として近隣セキュリティーシステム、お子さんが移動するときに、それをそういう認知症の方々にも応用したシステムを対応できないかどうかというのはお話もあったかと記憶しているんですけれども。","respondent":"早津高齢福祉課長","answer":"それで、その電話が３ポイントぐらいから発信をいたしまして、言ってみればピンポイント的に関知をいたしまして、そこに駆けつけるというような形での対応をしています。","voiceIndex":275,"id":"exchange-119"},{"speaker":"木下委員","kind":"質問","question":"そういう受信機があるというのは知らなかったので、大体その受信機をおやりになっていらっしゃるということですから、何人ぐらいがご利用されていらっしゃるのか、いつごろからそういうのを導入されていらっしゃるのか、参考までにお聞かせいただければありがたいと思います。","respondent":"早津高齢福祉課長","answer":"この制度は平成１２年１０月ぐらいから導入したものです。現在、利用している方が、約２０名です。","voiceIndex":277,"id":"exchange-120"},{"speaker":"木下委員","kind":"質問","question":"ですから、もうちょっとそういういい機器があるのでしたら、逆に皆様方にＰＲして利用促進を図っていただければありがたいなと思います。よろしくお願いします。それから、品川だけではなしに、生活の建て直しですとか、就労支援ですとか、そっちのほうが自立をさせていくというのが、重要だと思うんですが、そちらのほうの区の取り組みですとか、ございましたら、そこら辺をお願いしたいと思います。","respondent":"志村生活福祉課長","answer":"お尋ねのホームレスの地域生活移行支援事業です。この事業は、２３区、東京都共同で行ってあります。現在、品川区にこの事業を利用されて品川区に居住されている方は１２人です。これは８月末現在です。ちなみに、東京都全体ではご利用されている方は６９１人です。","voiceIndex":279,"id":"exchange-121"},{"speaker":"三上委員","kind":"質問・要望","question":"公衆浴場が減ってきたという傾向はずっと続いてきておりまして、私が今持っている浴場マップを見ると４１件が経営しているですので、本当に４１件の方に頑張っていただきたいなと、こういう思いながら、この傾向というのは、減少傾向というのはまだちょっと続くようにあるのか、それとももうそれこそこの減少傾向というのはとまって。","respondent":"谷田部健康課長、蓼沼高齢事業課長","answer":"それぞれ公衆浴場をめぐる経営環境は非常に厳しいというふうに私ども思ってありますが、それぞれ浴場経営者は、廃業なり、また事業継続するなり、それぞれいろいろ事情がございまして、廃業するところにおきましては。そういったことで、区といたしましても、浴場組合とは毎年定例的に話し合いの場を設けていろいろ要望も聞いてありますので、今後とも連携を図りながら。","voiceIndex":282,"id":"exchange-122"},{"speaker":"三上委員","kind":"質問","question":"そういった今伺ったことについて、企画のほうとしては、それは支援していくという考え方でいいんでしょうか。","respondent":"日下部企画財政課長","answer":"ただ助成の問題につきましては、いろいろな諸般の状況等も十分やはり考慮に入れた対応が必要ではないか、このように考えております。","voiceIndex":285,"id":"exchange-123"},{"speaker":"三上委員","kind":"質問・要望","question":"本当に２６号線を境に北のほうを見てみますと、本当に空白が大きくなっているなと、実感するわけですよね。ですから、そういう考え方からいくと、やはり地理的な部分で、やはり満遍なくそういったものがあるということも大事なことだなということでありますから、せっかくこうやってやっている事業でありますので、しっかりと企画のほうも支えていただきたいし、支援のほうもやっていっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-124"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1248#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":108363,"voices":288}},{"id":"h17-20051011-4","meetingId":"h17-c-settlement","date":"2005年10月11日","dateIso":"2005-10-11","committee":"決算特別委員会","time":"午前１０時０４分～午後５時２８分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を142件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０４分開会 おはようございます。ただいまから、決算特別委員会を開会いたします。 それでは、平成１６年度品川区一般会計歳入歳出決算","agenda":"○午前１０時０４分開会 おはようございます。ただいまから、決算特別委員会を開会いたします。 それでは、平成１６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"おはようあります。私は、成果報告書の１１７ページの区民健康診査と１２１ページのフリーマーケット経費、それから１２３ページの消費者センター運営費に関連してお伺いしたいと思います。そういう動向と何か関係があるのかないのか、そういったところを教えていただきたいと思います。","respondent":"川口品川区保健センター保健サービス課長、谷田部健康課長","answer":"そういう意味で、我々はこれまでどおり４０歳以上の区民健診をただいまも申し上げましたけども推進していきたいと考えております。それで、私どもこういう健診の結果が、次の例えば生活習慣を各自が改めるですとか、例えば食生活ですとか、それからあと禁煙ですとか。","voiceIndex":4,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"この新聞記事と特に関係があるということじゃないと認識いたしました。こういった記事が出ていまして、私も区民健診を受けたことがないので何も言えないんですけども、ほんとうにちょっと効果が薄いというような記事が出ますと、果たしてこの事業自体がどうなっていくのかなとちょっと心配に思ったものですから、また今後の動向がもし何かわかりましたら、またご報告いただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"フリーマーケットは主に区が主催するエコフェスティバル等でやる場合と、今ご質問がありました地域型フリーマーケットの支援がありまして、回数的にはこの地域で開催するもののほうが平成１６年度の場合２８回ということで圧倒的に多くなってあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問","question":"品川区においてはそんなことはないと思うんですけど、何かそういうのに似た苦情とか、また違うような感じでも結構なんですけど、何か問題点なんかで区民から寄せられている声がありましたら教えてください。","respondent":"中山清掃リサイクル課長","answer":"主だった実施段階での苦情というのは寄せられてございませんが、私どもちょっと気にしておるのは、いわゆるフリーマーケットということで区民参加というんですが、中には準プロと申しますか、かなり新品に近いものを扱われているようなケースもあったりしますので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"今、主にはひどいケースはないということで安心しておるんですけど、やはり事務事業評価で見るとＣということで、今後どちらかというと行政主体よりも、そういったＮＰＯとか地域の方たち、消費者団体主体の形式に変えていきたいと事務事業評価に書いてありますので、それは方向性としては非常にいいことだと思うんですけど、都立公園みたいな大きい公園ではないので大丈夫だとは思うんですけど。","respondent":"長田区民課長","answer":"こういったものが２,２２５件ということで一番多うあります。その次は金融保険サービス、これが３１３件、それから３位が教養娯楽品ということで２５２件、こういった順序で続いているところです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"ご答弁いただいたとおり平成１５年、１６年と、どちらかというと２０代、３０代の方の相談がかなりパーセンテージを占めていまして、またご指摘いただいたとおり電話情報提供サービスとか、いろんなそうした若者がメールのものとか、インターネットとか、そういったものがどうも多いような感じなんですけど、最近の、この１７年度になりますと、上半期、特にリフォーム詐欺ですね。","respondent":"長田区民課長","answer":"そういったことの相談が最近持ち込まれるケースが大変多くなってございまして、私どもも、「地域緊急情報」というチラシをつくりまして、地域に周知を行ったところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"「地域緊急情報」ということでチラシを配って、そういった防止策をやられているということで、今初めて知ったんですけども、結構こうしたリフォーム詐欺の関係で、消費者センターで相談を受けた際に、そうした情報を公表するか公表しないかということで、消費者センターによって各地の、意見が分かれているという、個人情報保護の関係ということであるんですけど、その辺については。","respondent":"長田区民課長","answer":"ですから、内容が知りたいときにつきましては、東京都のホームページ、あるいは国民生活センターのホームページにアクセスをしていただけると、その辺の詳しい内容ですとか傾向、こういったものがご覧になれると、こういう状況になってあります。","voiceIndex":15,"id":"exchange-006"},{"speaker":"武内委員","kind":"質問・要望","question":"そうした連携ですね。例えば消費者センターにそういったリフォーム詐欺みたいなことで相談に来た場合、大体そういう方というのは多少認知症が入っているようなケースもあると思うんですね。そうした方が来た場合に、場合によっては後見センターのほうにつなぐというか、そうした連携というのはどういうふうにされているか教えていただきたいと思います。","respondent":"長田区民課長","answer":"自己で判断できないような方も数多くいらっしゃるということで被害になりやすいというようなことでの傾向はあろうかと思います。こういったお年寄りの特にそういった傾向のある方につきましては、社会福祉協議会のほうとも連携をとりまして、注意を呼びかけているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"武内委員","kind":"質問・要望","question":"これからどんどん増えてくると思いますので、ぜひその辺の連携をしっかり密にとっていただきながら、また未然に防いでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"大西委員","kind":"質問","question":"環境衛生費についてですが、犬の登録、予防注射および動物の愛護というものがありますが、これに関しては、新規登録頭数、おそらくこれは犬を新たに飼ったというのが１,０３５頭、注射頭数が６,００３頭ということになっているんですけど、本来狂犬病とかそういう予防接種というのは、毎年行っていくものじゃないかなと思うんですけども、これに関しては、年間に新しく飼う頭数が１,０００頭であって。","respondent":"島袋品川区保健所衛生課長、谷田部健康課長","answer":"それで、注射の件数ですけど、６,０００頭ということでございまして、実際問題、品川区に登録しているのは８,０００頭あります。接種率が、予防接種の接種率は大体７５％から８０％ちょっとになっています。平成１６年度決算の数字ですけども、こちらの１１２件につきましては、いわゆる飼猫の去勢・不妊手術の件数でございまして、１７年度からいわゆる地域猫といわれます飼い主が不明な猫についての去勢・不妊手術を実施する予定ですけども。","voiceIndex":21,"id":"exchange-009"},{"speaker":"大西委員","kind":"質問・要望","question":"それとあと、この飼猫、今度地域猫に関しましては、実施予定ですが、昨今あまり見かけないですが、野良犬、この表現からすると地域犬というんですか、この状態はあまり見かけないんですけども、おそらく保健所が確保して連れていって、ある一定の期間の後には処分しているんじゃないかと思うんですけど、猫の場合にはそれを行わないのか、またもし行っていないとすれば。","respondent":"島袋品川区保健所衛生課長、谷田部健康課長","answer":"それから督促のほうですけれど、ちょっと数字的には把握してございませんけれど、この督促状を送りますと、１,０００通以上送るんですけれど、そうしますと、かなり電話がかかってきますので、そういう意味からすると。ところが、猫につきましては、そういうような法律はございませんで、強いて挙げれば動物の愛護及び管理に関する法律で、「みだりに殺したりつかまえたり何かしてはいけない」という。","voiceIndex":24,"id":"exchange-010"},{"speaker":"大西委員","kind":"質問・要望","question":"今狂犬病というお話がありましたが、現実的にもしこの狂犬病自体が発生しているという状況であれば、この２０％程度の予防接種を受けていない犬に関しては、大変危険度が高いというふうに判断できるわけですけど、現状犬による伝染病的な事件の発生というのがあるのかどうなのか、危険性ですね、それを教えていただきたいのと、あと猫に関しては、今愛護ということでお答えがありましたけれども。","respondent":"島袋品川区保健所衛生課長、谷田部健康課長","answer":"ただ、諸外国につきましては、かなりまだ残っているということで、一応委員おっしゃるとおり狂犬病の予防注射は必ず受けるようにと、そういう啓発、それから通知等は続けていきたいなと考えているところです。捕獲して処分したらいいじゃないかというような考えも一方ですけども、先ほど言いました動物の愛護法の関係もありますので、それは何とか地域の中で、皆さんの管理のもとで数を減らしていくというような、いわゆる猫と共生できるような。","voiceIndex":27,"id":"exchange-011"},{"speaker":"大西委員","kind":"意見","question":"その辺に関して、カラス対策と猫の共生ということに関しては、ちょっとうまくいかない部分があるんじゃないかなと思うんですけど、その辺がどうなのかということと、先ほど申し上げた事務事業評価のカラス対策ということに関して、現状では変化としてはどういう形でカラスの数が減っているとか、被害が減っていると、そういう点に関してもちょっとお聞かせいただければと思います。","respondent":"中山清掃リサイクル課長","answer":"効果の度合いについてはちょっと現在検証中ですけれども、傾向としては下がってきている。しかし、まだまだ守られていない方について、より徹底を図りたいということで、今後具体的な施策のあり方について検討してまいりたいと考えています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"大西委員","kind":"質問・要望","question":"それとも、そういう中長期的な立場に立って、最初だけではなく、中途も、そして終わりごろに関しても面倒を見ていくという趣旨での緑化推進、こういう助成をおやりになっているのかをお聞かせいただきたいのと、先ほど他の委員からもありましたが、消費者対策ですけど、現実的に相談に来ている、私ちょっと数字が出ていなかったような気がするんですけど。","respondent":"藤田道路公園課長、長田区民課長","answer":"中長期的なものにつきましては、建物を建てる方、そういった中で進めていっていただきたいというふうに考えているところです。消費者相談の件数ですけれども、まず、一番多いのが３０代が一番多うあります。これはパーセントで言いますと２５％です。それから次に２０代、２１.２％、その次が４０代、１５.７％という数字になってあります。","voiceIndex":32,"id":"exchange-013"},{"speaker":"大西委員","kind":"質問","question":"それとあと、消費者対策につきまして、私は昨今の消費生活相談、おそらく財産を奪うということを大きな目的としてやっているという非常に生活を脅かすような犯罪が大変多くなってきている。だから、できるだけ具体的に、そして相談がやりやすいような形でより配慮していただき、区民の方々が安心して生活できるように、また一工夫二工夫していただくことをお願いして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"数字を調べていただいている間に、ベンチャー創業支援事業についてですけれども、今実際にオフィスを貸しているのは西大井と、それから今日は平成１６年度の決算ですので、天王洲は出てきませんけれども、天王洲と２カ所ありますけれども、入居させる企業の目標というんでしょうかね、この一つに区内の既存企業と連携をとって、区内経済の発展に寄与してもらうというような。","respondent":"金子産業振興課長","answer":"起業相談ですけれども、この起業、私ども相談の中での起業部分と、それから経営カレッジの中で創業啓発セミナー、それから融資等々もやっておりますが、さまざまなメニューを設けまして、創業支援を実施してきております。","voiceIndex":37,"id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"今私が前段でお聞きをした問題については、今何一つお答えが返ってきていないんですね。もう一点、じゃあお聞きしますけれども、なかなか区内の中小企業、商店街を含めて厳しい状況にあるという一方で、区内にある大型店ですけれども、イオンなんかですと、昨年の中間決算の営業利益が１６億円、それから同時期でイトーヨーカドーは営業利益が７１億円だと。この辺をお願いいたします。","respondent":"金子産業振興課長","answer":"大崎ビジネス支援図書館の中で工業系の創業支援というのもこれから始めるところですので、その意味ではお尋ねは商業系の話でしたけれども、今後ともこの点に関しては充実していきたいというふうに考えているところです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"菊地委員","kind":"質問・要望","question":"大型店はイオンなんかは地方都市で１０年から１５年ぐらいのサイクルで出店と撤退を繰り返している、こういう企業であることはご承知だというふうに思います。ですから、この辺でのこうした街の今の状況とかみ合わせて商店街支援を充実させる。とりわけ生活に必要な生鮮三品についてはしっかりとした調査のもとで支援をする、こういう体制づくりをぜひ進めていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"塚本委員","kind":"質問・要望","question":"１２４ページ、産業経済費、製造業活性化支援事業に関してお伺いします。品川区のものづくりです。その中で、私伺いたいのは、都立高専も一つの拠点であったと思います。どういうふうに変わるのか、首都大学東京ですか、その中に組み込まれていって、ものづくり系統の学校、大学院までできるということですけれども、この様態、概要をお知らせいただきたいです。","respondent":"金子産業振興課長","answer":"現在は文部科学省のほうに申請を出しているところで、まだ認可を受けたという報告はいただいておりません。予定によりますと、この中では、都立高専そのものが５年制になりますので、大学院に向けた専攻科２年分をつくり、なおかつその上に大学院を設置すると。","voiceIndex":43,"id":"exchange-018"},{"speaker":"塚本委員","kind":"質問","question":"来年ですか、すぐできるということですから、ある種の下話が進んでいかなければいけない、あるいは少なくとも区内の製造業者、新しい形の製造業者がどういうことを望んでいるかということを受けとめなければいけないと思うんです。そういう作業は既にやられているかということが１点。それから、インターンシップということで１００人、これは受け入れるということですが、いろんな要素があります。","respondent":"金子産業振興課長","answer":"技術専門校のほうも、やはり地元と連携あるいは還元をしたいという意向が強くありまして、私どもと連絡を密にしてこの連携の事業を、これ以外についても拡大していこうということで、今検討しています。","voiceIndex":45,"id":"exchange-019"},{"speaker":"塚本委員","kind":"質問・要望","question":"やはり、学校という拠点がその役割を果たすであろうと思いますので、そういう意味で地域社会との協働、あるいは自治体との協働ということを視点に入れて、どんどん物を言って、お互いに話し合いを強くしてほしいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"私は１１６ページ、結核予防費、そして１１７ページ、飼猫についてお伺いします。最初、猫についてですけれども、先ほど別の委員から話がありましたが、まず、最初にお伺いしたいのはホームレス猫で、先ほどの説明の中でホームレス猫の中で、地域猫とあと野良猫がいるということを先ほどちょっと伺いました。","respondent":"谷田部健康課長","answer":"苦情の件数として、数字としては私ども把握はしてございません。ただ、さまざま近隣関係の中でのそれぞれ迷惑を受ける方、それからえさをやるのはけしからん、さまざまな相談、苦情等があるです。","voiceIndex":49,"id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"私、過去の経験の中で、大体苦情として考えられるのは三つあると思うんですが、野良猫がたくさん繁殖して困っているということ、あと糞尿の臭いがひどいということ、あと定置ではない場所にえさやりをすることがあって非常に周りが困っているということ、大体３点に私は絞られてくると思うんですけれども、この苦情の対処する方法として、品川区では児童保健事業部のホームページを開くと。","respondent":"谷田部健康課長","answer":"先ほども大西委員の中での質問にお答えいたしました。","voiceIndex":51,"id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"そういう意味では、地域を挙げて取り組まなければいけないということであれば、まさに防災のワークショップ形式と似通うところが私はあると思います。別の近隣区におきましても、保健所における飼猫の最低限のガイドライン、ルールというものが小冊子になりまして配布をされております。こういう動きに関して、品川区はどのようにお考えになるか教えてください。","respondent":"谷田部健康課長","answer":"私ども、これは主として住民の皆さん方の主体的な活動ということで取り組まなければこういう問題は解決しないだろうというふうに思ってありますので、区といたしましては、いわゆる指針をつくったり、ガイドブックをつくったり、それで終わりというのではなくて。","voiceIndex":53,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問・要望","question":"次なんですが、先日結核のことでちょっと新聞に出ましたが、ホームレス、または独居の高齢者の方を結核の疑いがあるのではないかということで強制的に入院をさせたということ、これは厚生労働省、かつての厚生省が結核予防法というものを拡大解釈したということで、自治体もそれにならって強制入院をさせたという記事が載っておりましたけれども。","respondent":"鶴見品川区保健所保健サービス課長","answer":"国のほうはその通知を本年３月に廃止することによって、命令入所者の対象を少なくするといったことになっておりましたけれども、現実には高齢であって、独居の方であっても、介護の方が入られたり、あるいはお買物に出かけられたりということで。","voiceIndex":55,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"じゃあ、すみません。どちらかということで、非常に難しいかもしれないんですが、ちょっと時間も迫っているので行かせていただきます。感染拡大の防止や適切な医療の提供には有効として拡大解釈を適用して、本区においてはどうなのか、ほかの自治体はあるということを聞いておりますけれども、ある自治体の中に本区は含まれるのか、含まれないのか、そこの一つだけお伺いしたいと思います。","respondent":"鶴見品川区保健所保健サービス課長","answer":"本区も含まれるというふうに考えております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"私も１１７ページの環境衛生費の犬と飼猫についてと時間があれば１２４ページの商店街振興と、それと都市型観光事業についてお伺いしますが、まず初めに、区の所管として犬は保健所、猫は健康課になっていますが、なぜ二つの課でやっているのか、ご説明をください。","respondent":"谷田部健康課長","answer":"実は健康課も犬に多少かかわりがございまして、健康課は保健所、保健センター、大井保健相談所の３所との調整も行ってありますので、畜犬登録等につきましては、健康課のほうも窓口で受け付けしていますし。","voiceIndex":61,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"まず基本的なことなんですが、なぜこのようにいわゆる飼われていない猫、地域猫が増えていくんでしょうか。その原因を教えてください。","respondent":"島袋品川区保健所衛生課長、谷田部健康課長","answer":"そういうニシキヘビ等を飼う場合とか、あるいは輸入する業者とか、こういうのは東京都のほうで登録してやらなければならないという法律上の決まりがありまして、したがいまして、区でこれを扱うというよりも。増える原因はさまざまだろうというふうに思ってあります。","voiceIndex":63,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"ほんとうに無責任ですよね。ペットボトルを置いたけど、全然効果がなかったという話も来ているんですけれども、いわゆる猫を好きでえさをあげている人と、迷惑している方のトラブルというのは頻繁にあると思うんですけれども、その辺の対処というのは、意見が対立する場合に、区としてはその人たちに対しての対処をなさっているんでしょうか。","respondent":"谷田部健康課長","answer":"区といたしましても、そういう地域の猫を地域で管理して、例えば去勢や不妊手術を行うことによって、それ以上不幸な猫を増やさないと、今ある猫の寿命を全うするまで皆さんで。","voiceIndex":66,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長の今ご答弁で、不幸な猫という答弁が出ましたけれども、やっぱり幸せな猫を増やしていかないといけないと思うんですけれども、不幸な猫を増やすのは、やっぱり無責任な人間が増えることで、不幸な猫が増えていってしまうと思うんですけれども、猫に愛情を持ってえさをあげる方のモラルというのがこれから大切だと思うので、その辺のモラル。","respondent":"谷田部健康課長","answer":"これは猫に限らず、犬もそうですけども、やはり飼ったり、それからまた飼い主のいない猫等も、これはあくまでもルールを持ってやっぱり接するということが大事ですので、そういうことで。","voiceIndex":68,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"続きまして商店街振興事業で１点だけお伺いしますが、景気は回復したと言われつつ、商店街はまだ厳しいものがあるんですが、１点、空き店舗対策について、これから区としてどのように施策を打っていくんでしょうか。","respondent":"金子産業振興課長","answer":"やっぱり、単なる空き店舗、個店でありますと、なかなか効果が発揮できないというところから、先ほど申し上げた面的な活性化をしようということで、リフレッシュ推進事業を設けております。","voiceIndex":70,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"私は成果報告書１１７ページ、環境衛生費と区民健康診査についてお伺いします。まして、猫が人間の足、第一関節を人体から乾物のにおいがするというようなことだと思うんですけど、食いちぎっちゃったり、それからニシキヘビが人の民家の中に入ってきたりということは、皆さんのお宅には乳幼児もいるわけですから、ほんとうに心配だと思います。","respondent":"島袋品川区保健所衛生課長","answer":"この特定動物につきましては、先ほどの藤原委員の時にお答えしましたように、一応東京都のほうで定められているという形で条例になってありますけれど、区としても、こういうニシキヘビがあったということがありまして。","voiceIndex":73,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"今、都のほうで管理しているということなんですけど、区のほうでもそのまま資料というんですか、それはきちんと持ち主、それから場所ですか、どこに飼っているということで、それはすぐに特定できるんでしょうか。","respondent":"島袋品川区保健所衛生課長","answer":"今後、そういう意味で、そういう情報を集めるとか何かそういうことも検討していかなきゃならないと考えています。","voiceIndex":75,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"いや、私の言っているのは、都の条例でそういうふうに管理するというのはもちろんわかるんですね。でも、やはり区民の皆さんは、まず区のほうに第一報が来ると思います。それで、初動調査というんですか、それで動くのはやはり区でないのかなと思うんですが、またすぐ警察に通報する。でも、それができるだけ早い時間で、短時間でわかる。持ち主がどなただって特定できる。","respondent":"谷田部健康課長","answer":"そうではないんだという一定のルールがあって、やはり飼うべきだろうというふうに思ってありますので、今のところ、東京都のほうの条例がありますので、区としてはそういうことは考えてございません。","voiceIndex":79,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"だって、実際その方たちが、じゃあちょっと寝ていました。まさに危険な動物、それから爬虫類に対しては、やはり区のほうとしてもしっかり対策をとるべきじゃないかと思います。次に、区民健康診査についてお伺いいたします。これは前年と比べますと、約３,０００万円支出が減ということで、これだけ減っているのかなと思うんですけど、なぜこういうふうに減ったのか、何か調査等はしていますでしょうか。","respondent":"谷田部健康課長","answer":"区民健診の関係ですけども、金額的には３,０００万円弱減ってあります。受診者が約２,０００人弱減ってありますので、受診する人の数が減れば、その分の支出も減ると、そういう関係になってあります。","voiceIndex":81,"id":"exchange-034"},{"speaker":"須貝委員","kind":"質問","question":"それで、今これだけ健康管理等々を区のほうではいっぱい奨励しているわけですけど、なぜ減ったのか、５％ですか、金額ベースで、２,０００人ということなんですけど、これは結構大きな問題じゃないかと思うんですけど、その辺、何かつかんでおりますでしょうか。","respondent":"谷田部健康課長","answer":"４０歳以上の方の健診が区民健診の対象になりまして、いわゆる職場等で受けられない方もすべてこの対象になります。医療機関以外にも保健所・保健センターで健診をやっておりまして、そっちのほうの数字も減ってきてありますので、それで全体にこういうふうに減ってきているです。","voiceIndex":83,"id":"exchange-035"},{"speaker":"須貝委員","kind":"意見","question":"ほんとうにこれだけ減っているということは、かなり憂慮すべき状況かなと思いますけど、やはり区民の健康を考えたときに、よりそういう区民健診のほうをやっていただくとありがたいと思いますので、これからも努力してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":85,"id":"exchange-036"},{"speaker":"中島委員","kind":"質問","question":"私は１２１ページのリサイクル推進費に関連して生ごみ処理機普及事業、それからリサイクルショップ運営費、時間があれば１２５ページの製造業活性化情報発信事業についてお伺いいたします。これに関連しまして、区民の方からこれだけはぜひ区のほうにお伝えしてほしいということがありますので、お願いしたいと思います。ほんとうにそうだと思います。「タマからのお願いです。一言ご感想をお願いします。","respondent":"谷田部健康課長","answer":"なかなかほのぼのとした感じの看板だということで、そういったことも参考にしながら、今後取り組んでいきたいと思ってあります。","voiceIndex":87,"id":"exchange-037"},{"speaker":"中島委員","kind":"質問","question":"ちょっと家庭の生ごみ処理だけだったわけなんですが、もちろんそうなんですけど、今水分が非常に多いということを区民の方にどう伝えていくかということが大事ではないかと思うんですね。可燃分が３８％、水分が５８％、その他４％であるということを区民の方にしっかりと伝えているんですね。この辺のところのご見解、よろしくお願いします。","respondent":"中山清掃リサイクル課長","answer":"こういうふうなわかりやすいＰＲを今後少し強調していきたいというふうには考えてあります。","voiceIndex":91,"id":"exchange-038"},{"speaker":"中島委員","kind":"質問","question":"リサイクルショップの運営費なんですが、これは事務事業評価を見ますと、今回見直しということで、ＮＰＯ法人にいろいろ事業を行ってもらうというふうに決めたというふうに書いてあるんですが、相当歳入と歳出の費用を見ますと差額が非常に大きいものですから、これはどういったことが原因だったのか、それから今後どのように変わっていくのかお伝えください。","respondent":"中山清掃リサイクル課長","answer":"ただ、まだまだいわゆるほんとうのショップの採算ベースということを考えますと、さらに改善を進めていかなければいけませんので、ＮＰＯのフットワーク、区民の力というものを借りてよりよくしていきたいというふうに考えてあります。","voiceIndex":93,"id":"exchange-039"},{"speaker":"中島委員","kind":"質問","question":"わかりました。続きまして、時間があまりないんですが、１２５ページの製造業活性化情報発信事業とあります。この事業はどういうものか教えてください。","respondent":"金子産業振興課長","answer":"製造業活性化情報発信事業についてのお尋ねですけれども、こちらは区内の製造業の情報をインターネットを活用しまして広く国内のみならず国外にも発信して、区内産業はもともと高度な技術があるということがありますが。","voiceIndex":95,"id":"exchange-040"},{"speaker":"中島委員","kind":"質問・要望","question":"当然中小企業の方の力になるのかなと思いますが、先ほど塚本委員の質問の中からも少しつかみとったわけですが、品川区内、中小企業は非常に逼迫した状況というのもあると思います。都立高専に出た方でも就職できないでいる方もいらっしゃいます。そういった方々のために、やはり品川区のこうした中小企業の力をもっと大きく発揮できるように努力をしていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは１１６ページから始まります保健事業費の中で、主に区民健康診査について伺いたいと思います。生活習慣病予防の一環として、現在４０歳から無料の区民健康診査が行われておりますけれども、国民の中で重大な健康問題といわれている糖尿病ですか、私も調べてみまして驚きましたけれども、２００２年の調査で、全国で７４０万人、予備軍を含めると１,６２０万人といわれております。","respondent":"川口品川区保健センター保健サービス課長","answer":"区民健康診査の大きな目的といたしましては、区としましては、先ほどからお答えしていますけども、４０歳以上をターゲットとして一部女性健診も実施していますけども、区民の健康を守っていくです。","voiceIndex":99,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのストレスの部分が長時間労働だったり、心の悩みだったり、薬のとりすぎだったり、冷房による冷えなど、ストレスが原因になっているとおっしゃっていましたけれども、最近では生活習慣病の低年齢化が進んでいると社会問題化されていますけれども、今の生活習慣病の低年齢化の実態や背景についてお考えを教えていただきたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"１点目のストレスですけれども、確かにいろんな疾患等にストレスは悪影響を及ぼしているかと考えています。特に昨今の調査では、いわゆる５０歳以下の方々、いわゆる若年という方にそのストレスの状況が高うございました。","voiceIndex":103,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり、なかなか自覚症状が出ないので早期発見、早期治療、また予防のための保健指導、こうした４０歳以下でも定期的な健康診断というのは大変有効ではないかと思うんですけれども、ぜひ現在４０歳から行われております区民健康審査を予防のためにも思い切って２０代に対象を拡大していただきたいと思いますけれども、いかがでしょうか。","respondent":"谷田部健康課長","answer":"この制度を運用していくためには、やはりそれなりの理由があってしているわけでございまして、区民健診は先ほど来申し上げていますけども、老人保健事業の一環として健診が行われ、また健康教育や健康相談とか。","voiceIndex":105,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問","question":"その方はやっぱり高校に行きたいと思って、今夜間の高校に通っていますけれども、学校で久しぶりに健康診断を受けて、本人もほっとしたと話しておりましたけれども、私は区民健診を受けていない状況が広がっている中、また生活習慣病の低年齢化が言われている中で、現在やっぱり４０歳の区民健診を２０歳に引き下げることが予防につながる、区民の健康を守ることにつながっていくんではないか。","respondent":"谷田部健康課長","answer":"そのための私ども啓発に努めてまいりますけれども、それを２０歳代まで引き下げて、区で公費で行う考えは持ってございません。","voiceIndex":107,"id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、今４０歳以上の区民健康審査ですけれども、例えば勤務等で受診の機会がない者は受けれるわけですよね。一昔前でしたら、会社に入れば診断の内容が十分とは言えなくても、年に１回会社が健康診断を受けさせてくれたと思いますけど、非常勤化が進む中で、その率が年々下がってきているんではないかと思うんですけれども、何かつかんでいることがありましたら教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"先ほど答弁で女性健診につきましては１６歳から受診できますので、中塚委員のご質問は男性の健診ということで限らせて答弁をさせていただければ、今のところ２０歳代に引き下げて健診をやる考えはございません。","voiceIndex":109,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどの答弁の中になかったのは、２０代、３０代の健康診断を受けている率、年々私実感としてですけど、下がってきているかと思うので、そこについてもう一回お伺いしたいのと、私は状況をまずきちんとつかんでいただきたい。もう一点伺いたいのは、２３区の中で、対象を広げて若年層からも健康診断をやっている区があるかと思いますけれども、幾つか紹介していただきたいと思います。","respondent":"谷田部健康課長","answer":"そういうデータを入手するすべもございませんのでお答えできません。それから、若年層の健康診断をやっているところは幾つかございまして、千代田区、中央区等がたしか対象を引き下げてやっているというふうに聞いてあります。","voiceIndex":111,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"他区の様子ですけれども、今紹介ありました千代田区では、平成１５年度から２０歳まで対象を引き下げました。私は最後にフリーターなどを問題にしましたけど、ニートの問題一つとっても、健康診断の実施が何か社会に前向きになれたり、動機付けの一つになるのではないかと思いますので、ぜひ２０代からの実施をご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は衛生費の中から２項の環境費、１２０ページ、低公害車導入促進助成事業、それから資源回収事業、産業経済費の中から第１項の商工費の中の１２４ページ、商店街振興事業、ベンチャー創業支援事業、時間が短いので端的に質問だけしていきたいと思っています。新規のまま、全部は厳しいよというのか、商店街に対しての考え方をちょっと教えていただきたいと思います。","respondent":"中山清掃リサイクル課長、金子産業振興課長","answer":"国や都のいろいろ廃プラスチックのサーマルリサイクルの検討、あるいは基本方針ということを踏まえて、２３区でも、要は不燃ごみとして埋めていていいのかということで検討を現在行っている状況です。商店街の共同装飾灯のお尋ねですけれども、私ども新設あるいは建て替えに関しまして、委員ご指摘のとおり東京都とあわせて助成をしているところでありますが、あくまでもこれは商店街のものですし、商店街が責任を持つということから。","voiceIndex":116,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"意見","question":"全部今品川区も埋めていらっしゃるんでしたか。その辺を後でもう一回お答えをお願いしたい。じゃあ何かそれを補修するなり何なりということを考えたときに、その補修に対しての補助みたいなものが考えられないかと、それが自己負担も当然必要にはなってくるでしょうけど、新規でつくるよりは少しもつんじゃないかなという考え方なんですけど、お答えのほうをお願いしたいと思います。","respondent":"中山清掃リサイクル課長、金子産業振興課長","answer":"城南以外の１８区については中央防波堤にそのまま埋めていっている、これが主な検討の要因になっておりますけども、ただ、２３区全体の分別の見直しということでの検討を行っている、こういう状況です。共同装飾灯の補修ということについてのお尋ねですけれども、私ども確かに今まで助成してきて、中にはかなりさびついた等々、危険というものはすぐ対応しますけれど、危険に近いものも出てきつつあるということは認識しています。","voiceIndex":119,"id":"exchange-050"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"不燃ごみのほうなんですけど、不燃で収集して、相当それを可燃にするために分けているのかな。そこで東品川で分けてやるわけですか。その日に持ち込みしたいけど、その処理ができないということも聞いているんで、そこら辺、今後粗大ごみの考え方をお聞きしたいというのが１点。そこら辺を考えていただきたい。これは要望にしておきます。","respondent":"中山清掃リサイクル課長","answer":"コスト面につきましては、収集をトータルで考えなければいけない部分があるんですけれども、例えば清掃工場の別プラントをつくって不燃ごみの処理をしているコストを考えると、トータルの積算で言えば。","voiceIndex":122,"id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう一点、簡単に。低公害車導入促進についてですけど、今度も前年度に比べて減っていますよね。だけど、これで大分効果が上がっていると思うんですが、これからもっと厳しくなってきたときに、この制度自体を、特に入れかえをやらなきゃいけないところが大分出てくると思うので、この事業自体、これから継続していかれるのかどうかということだけお答えいただきたいと思います。","respondent":"田中環境課長","answer":"自動車のＮＯｘ・ＰＭ法の本格的な適用ということになりますと、ＰＭを減少させる酸化触媒ですとか、ＤＰＦ等については、基本的にこれがＰＭ規制の部分が無効になりますので、効果のない施策になるということで、買いかえなくてはいけなくなるということになります。","voiceIndex":124,"id":"exchange-052"},{"speaker":"本間委員","kind":"質問","question":"最初に、予防接種費の件ですが、定期予防接種三種混合ほか５万８,７１０件というような形で中身が出ておりまして、その金額が出されておりますが、この件で人数ではなくして、例えば区民健診のような形で、人数ではなくして件数で表現されている部分はどのように理解したらよろしいのでしょうか。","respondent":"鶴見品川区保健所保健サービス課長","answer":"予防接種の実施状況ということでよろしいでしょうか。平成１６年度の三種混合の１期初回７,２２０件でございまして、１期追加が２,１３３件、それからジフテリア、破傷風、混合８４３件、ポリオ……。","voiceIndex":127,"id":"exchange-053"},{"speaker":"本間委員","kind":"質問・要望","question":"ごめんなさい。大変すみません。この区民健診等を４０歳以上の件で午前中も出されておりましたけれども、人数で表現されておりますが、この件は三種混合ほかが５万８,７１０件というふうな表現になっておりますが、この含まれる、数字の持つ意味合いを教えていただきたい。例えば、１人の人が複数で利用することがあるとかというふうなことがあるかもわかりませんが、その辺の件で簡単に。","respondent":"鶴見品川区保健所保健サービス課長","answer":"ポリオは２回式でございまして、風疹、麻しんにつきましては１回式、日本脳炎につきましては、初回が２回式で、１期追加、２期追加、３期となっておりましたけれども、３期のほうは本年中止となっております。","voiceIndex":129,"id":"exchange-054"},{"speaker":"本間委員","kind":"質問","question":"なかなか勘定しづらいんだろうというふうに思います。特にこれからまた時期ですので、年末から年始にかけてのインフルエンザの予防接種の件が出てくると思いますが、この高齢者に対する補助の内容等について、収入制限等々があろうかと思いますが、そのやり方、手順について状況を教えてください。簡単で結構です。","respondent":"谷田部健康課長","answer":"高齢者のインフルエンザにつきましては、低所得者といいますか、生活保護世帯ですとか、それから住民税非課税世帯だと思いますけども、そちらのほうが公費で負担するというようなものになっております。","voiceIndex":131,"id":"exchange-055"},{"speaker":"本間委員","kind":"質問","question":"私どももこの件につきましては、実際に利用されるわけですけども、お医者さんのほうでは年内に１回よりも必ず年明けてからもう１回ということで、２回やったほうが非常に効き目がある、効果があるということの中で、利用費がたしか３,０００円前後だと思いますけども、お金がかかるというような部分でのお話を聞いたことがありましたものですから、その件をお尋ねしました。","respondent":"谷田部健康課長","answer":"自己負担部分が２,２００円、これはいただきますが、予防接種料はそれ以上に私どもお支払いしますから、予防接種にかかる費用の一部を自己負担していただく、それが２,２００円部分であるです。","voiceIndex":135,"id":"exchange-056"},{"speaker":"本間委員","kind":"質問・要望","question":"私の記憶では何かあったような気もしないではないんですが、どうも今その辺のお答えがちょっと、また後で調べていただきたいと思います。１１７ページ、精神保健費、この件につきましては、グループホーム運営委託、訪問介護員派遣となっておりますが、グループホーム運営委託につきましては、何カ所で何人、内容はどうなのか、これも簡単で結構ですから教えていただきたい。","respondent":"西島障害者福祉課長","answer":"目的ですけれども、在宅での精神障害者の生活を援助するために日常生活の援助等を実施しているものでございまして、この訪問介護員を派遣することで一定安定した生活、さらにそれが自立した生活につながるものだというふうに考えているところです。","voiceIndex":137,"id":"exchange-057"},{"speaker":"本間委員","kind":"質問","question":"そのグループホーム運営１カ所、５名ということでございましたね。わかりました。精神保健費の中の部分ですから、待機だとかいうふうな部分があるのかどうかというのもお聞きしたかったんですけども、次に行きたいと思いますが、訪問介護員派遣について、利用者側と受け手側、いわゆる事業者側と利用者との行き違いですね。サービスの行き違いなど何かありますでしょうか、一般的にで結構です。","respondent":"西島障害者福祉課長","answer":"訪問介護員を派遣するときには、派遣のためのケア会議を実施いたしまして、その中でこの方にはこういうサービスが必要だと、自立していくためにはこういうサービスが必要だということで派遣をするわけです。","voiceIndex":139,"id":"exchange-058"},{"speaker":"本間委員","kind":"質問・要望","question":"環境相談費には苦情・陳情受付件数２２７件というふうな中身がありますが、地域における苦情といたしまして、例えば深夜から早朝にかけての苦情の処理対策について、なかなか行政の手が届かないような部分があるのではないかというふうなことをお聞きしておりますが、そのような深夜から早朝にかける臭気対策、騒音対策等々についての対応の仕方についてご意見をお伺いしたいと思います。","respondent":"田中環境課長","answer":"工場指導費、それから環境相談費ですが、特に深夜、それから早朝ですとか、こういうところにつきまして、騒音等がある場合、苦情等がある場合に、現場確認に職員が行ったり、もしくは騒音計等を貸し出して記録してもらうというような形の対応をとっております。","voiceIndex":141,"id":"exchange-059"},{"speaker":"本間委員","kind":"質問","question":"実はここの環境相談費の中に苦情・陳情受付件数２２７件というふうなことがありますが、特にこの中には公害認定患者の認定はどのような手続でなされているのかとか、あるいは更新や見直しなどはどのようになされているのかということを簡単に聞きたいと思います。これは大変な部分での大きなことだと思いますが、とりあえずまずその件だけ先に簡単にお聞きしたいと思います。","respondent":"谷田部健康課長","answer":"公害健康被害に関しての認定のことですけど、見直しは３年に１回等級のほうの見直しをしている。認定審査会におきまして、等級のほうの審査をしているという状況です。","voiceIndex":143,"id":"exchange-060"},{"speaker":"本間委員","kind":"意見","question":"公害認定患者の認定云々ということではなくして、町場でもかなり泣き寝入りといいますか、どこに何を言っていいのかわからない、ましてや深夜にわたる部分、早朝にわたる部分、聞きましたら、近所にごあいさつをしているという部分もありますし、していないという部分もありまして、実態がつかめない部分でのやりとりなんですけれども、その苦情、相談については例えば深夜とか早朝の部分ですね。","respondent":"田中環境課長","answer":"先ほどちょっと答弁させていただきましたように、いろいろ相談がありましたら、相談者のところにお伺いして、どういう時期にどういう騒音があるのかというのを確認した上で、発生しているところにもお聞きして、深夜等あれば、騒音規制の基準がありますので。","voiceIndex":145,"id":"exchange-061"},{"speaker":"本間委員","kind":"質問","question":"騒音対策については、今お話を聞きました。その件では、かなり前向きな対応をされているやに聞いております。その部分での騒音ですが、そうではなくして、消されない臭い、臭いの部分をどのようにとらまえて対策を立てていくのかという部分につきましては、なかなか手が下せないような状況にあると思いますが、この件について、どのようにご苦労されているのか教えてください。","respondent":"田中環境課長","answer":"この点については、人によって非常に臭気から受けるストレスが違うものですから、一応人間の鼻による測定方法がありますが、基本的には近隣の方と調整しながらうまく落ち着くように職員が現場で立ち会ってやっているというのが実態です。","voiceIndex":147,"id":"exchange-062"},{"speaker":"本間委員","kind":"質問","question":"１２２ページの廃棄物対策費に入りますが、この件はこれまでも何回かにわたって質問しておりますけども、壊れかけている自転車あるいは放置されたままずっと何カ月も置きっ放しになっている自転車、またはオートバイ等々の対策についてお伺いします。","respondent":"藤田道路公園課長","answer":"通常の道路の上に放置され、そのまま廃棄されたであろうと思われる自転車、バイク等につきましては、通常の駅前の放置禁止区域等とは違いまして、札をつけて１週間そのまま置いておいて、そのときに所有者が自らの持ち物だということで引き取りがない場合については。","voiceIndex":149,"id":"exchange-063"},{"speaker":"本間委員","kind":"質問","question":"今お聞きしましたけども、札をつけるのはどなたがつけるんですか。そして、どういうようなことに基づいて札を区なり行政がおつけになるんでしょうか。","respondent":"藤田道路公園課長","answer":"これは自転車の条例等にもありますし、また、私どもの管理している道路の道路法等にもそういったものを不法に投棄してはいけないということで、それに基づいて管理を行っているものです。","voiceIndex":151,"id":"exchange-064"},{"speaker":"本間委員","kind":"質問","question":"最後に商工相談、消費者対策費なんですけれども、この件につきましては、先ほどもありましたように、たくさんの方が被害に遭われまして、昨今では生活圏を脅かされるような相談が多くなっているということも午前中の話に出ておりましたけれども、この傾向と対策について、これまでと大分急激に増えている部分があると思いますし、また消費者生活相談員を増やしたりなんかして。","respondent":"長田区民課長","answer":"こういったことに対応するために、私ども平成１６年度は相談時間の１時間の延長、それから平成１７年度に入りましてからは、相談員の１名を増員いたしまして、この対応に当たっているところです。","voiceIndex":153,"id":"exchange-065"},{"speaker":"山路委員","kind":"質問","question":"訪問介護員派遣ですが、この主要施策の成果報告書を見ますと、約６９７万円計上されておりますけど、これは精神障害者の地域における地域での生活を支える事業だと思いますけど、この事業の実績と特徴的な内容についてお伺いをいたします。","respondent":"西島障害者福祉課長","answer":"訪問介護員事業の実績ですけれども、平成１４年度からこの事業を実施いたしまして、平成１４年度が１９人、平成１５年度が３３人、平成１６年度が３４人です。","voiceIndex":157,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問","question":"ヘルパー派遣についてですけれども、このヘルパー派遣はどこからされているのか、また精神障害者の方に対する理解が大変必要だと思いますけど、その辺の対策についてはどのようにしているかお伺いいたします。","respondent":"西島障害者福祉課長","answer":"そのヘルパー派遣に当たって、精神障害者に対する理解が大変必要だということを私ども十分認識してございまして、先ほどの質問にございましたように、行き違いのないようにということで、区単独でヘルパー養成研修を平成１３年度から実施しています。","voiceIndex":159,"id":"exchange-067"},{"speaker":"山路委員","kind":"質問・要望","question":"この精神障害者の方につきましては、厚生委員会での報告では区内に約４,０００人いらっしゃるとお伺いをしているわけですけど、この方たちが地域で安心して日常生活が送っていけるための中心となる施設として家族会の強い要望を受け、また、区長の英断により区が改修費用を持って国の施設整備費がつかない法外施設ということで、１０月に地域生活支援センターとしてオープンいたしましたが。","respondent":"西島障害者福祉課長","answer":"二つ目が障害者同士の交流機能、いわゆるたまり場機能ということで、オープンスペースを提供しています。三つ目が生活支援機能ということで、食事サービス、入浴サービス、あるいは生活情報の提供というものを実施する予定です。","voiceIndex":161,"id":"exchange-068"},{"speaker":"山路委員","kind":"質問","question":"精神障害者の方の親御さんたちがとっても明るい顔をされているのが私はとても印象的で、こういう施設は地域の方の理解が非常に必要で、理解のある地域に設置されてよかったなということを感じたわけですけど、都内にも地域生活支援センターは幾つかあると伺っているわけですけど、品川区の地域生活支援センターの特色は今後どのように出されていくのかお伺いいたします。","respondent":"西島障害者福祉課長","answer":"三つ目ですが、地域で活動していらっしゃいますボランティアグループ、あるいは地域の大学の研究グループと連携をいたしまして、土曜日ですけども、グループカンファレンス等の事業を実施するというふうに考えているところです。","voiceIndex":163,"id":"exchange-069"},{"speaker":"山路委員","kind":"質問・要望","question":"保健指導費について関連してですけど、健康増進センターの利用実態についてどういうふうになっているかお伺いをします。もう一点は、ふれあい健康塾ですが、平成１６年度で５地区、また本年１地区ぐらいが増えたんでしょうか。高齢者の転倒、骨折予防と運動機能訓練、いろんなものを盛り込んでいるということなんですけど、現在の状況についてちょっとお知らせをいただきたいと思います。","respondent":"谷田部健康課長","answer":"ふれあい健康塾の関係です。これは６０歳以上の方で足腰が虚弱な方を対象にして実施していますが、現在６地区で実施しておりまして、今年度１地区増やすという状況で今現在準備をしています。","voiceIndex":165,"id":"exchange-070"},{"speaker":"山路委員","kind":"質問・要望","question":"小さいお子さんが入っているのかどうかお伺いしたいのと、ふれあいサポート計画では、今現在月に１回ということですが、昨年の決算で２回以上欲しいという利用者からの要望もございまして、また免許を持った指導員の数もこれから増やさなきゃいけないでしょうし、あとスポーツ関係の方にお手伝いもお願いしたいということで、体育指導員とかスポーツ協会とのリンクもお願いしたわけなんですけど。","respondent":"谷田部健康課長","answer":"ふれあい健康塾の関係ですけども、現在月１回実施しております。","voiceIndex":167,"id":"exchange-071"},{"speaker":"松澤委員","kind":"質問","question":"２点お聞きしたいと思います。２点目は４款でしょうか、衛生費の中からカラス対策費についてお聞きしたいと思います。産業経済費のほうですけども、成果報告書の１２４ページ、商店街振興事業の中の講師謝礼等４６万９,７３１円、商店街ステップアップ支援事業、核店舗支援事業助成１５０万円、商業地リフレッシュ推進支援事業２,１６０万２,０００円、その事業内容についてお知らせ願いたいと思います。","respondent":"金子産業振興課長","answer":"商業地リフレッシュ推進支援事業ですけれども、これにつきましては、空き店舗対策の面的な展開ということで、北品川本通り商店街等々での空き店舗の２店舗を展開するということで、２店舗助成をしたものです。","voiceIndex":171,"id":"exchange-072"},{"speaker":"松澤委員","kind":"質問","question":"よくひところありました中小企業診断士等による派遣事業とか、そういうものは今行われているのでしょうか、いないんでしょうか。その点、ちょっとお聞きしたいと思います。","respondent":"金子産業振興課長","answer":"私どもの中小企業診断士の商店街等への派遣につきましては、商店街から依頼があれば、予算の範囲内で実施しています。","voiceIndex":177,"id":"exchange-073"},{"speaker":"松澤委員","kind":"質問・要望","question":"あるいはまた、戸越銀座商店街、あるいは遠く平和坂通り、三ツ木通りのほうの商店街はますますだめになるんじゃないかとやはり心配する中で、いろいろ講師等を派遣しながら勉強会をしたいという思いがあるんですが、このような中で、この地域に対する要望が出ていると思うんですが、産業振興課としての対策、どのような対策、今までのイベント、イベント、イベントというんじゃなくて。","respondent":"金子産業振興課長","answer":"私どもとしましては、従来からこの商店街に対してはさまざま支援しておりましたけれども、この大規模店舗対策、地元のほうから、商店街のほうから要望がありましたら、講師派遣等、私どもででき得る支援策を実施していきたいという考えは持ってあります。","voiceIndex":179,"id":"exchange-074"},{"speaker":"松澤委員","kind":"質問","question":"区商連のほうでは、近々中小企業診断士を招いて、街が変わると、中型店ができることに対する街の対策、商店街の対策ということで行うという話を聞いているんですが、今産業振興課のほうですと、まだそういう話は来ていないということですが、逆に言うと、区と区商連の関係、私は不即不離だと思っているんですが、こういうようなものが来た場合には、両方常に情報交換して。","respondent":"金子産業振興課長","answer":"委員ご指摘のとおり私どもと商店街連合会の事務局に関しては、非常に連携を密にしなければならないと考えておりまして、先ほど正式な届出は来ていないというふうにお話ししましたが、ライフのことですね、これについても届出の前の情報提供というものは来ておりまして。","voiceIndex":181,"id":"exchange-075"},{"speaker":"松澤委員","kind":"質問・要望","question":"一つは過疎的な商店街の中にできてくる、あるいはもう一つは商店街立地じゃないところにできるということで、これを取り巻く商店街は相当数地域的に大きな影響を受けると思いますので、この辺の対策、イベント事業も大事ですけど、これがほんとうに商店街対策の本質かなというふうに思いますので、一生懸命やっていただきたいという要望をしておきたいと思います。それと２点目に入ります。","respondent":"田中環境課長","answer":"ということで、決算上は環境相談費ということになります。なお、平成１７年度からカラス対策の総合窓口の設置、それからカラスの巣ですとか、落下びなに対する撤去の補助金制度を創設しまして実施しております。","voiceIndex":183,"id":"exchange-076"},{"speaker":"松澤委員","kind":"質問","question":"清掃リサイクル課のほうで８月から区内６カ所で３カ月間かけてカラスの実証試験を行っているというようなお話を聞いています。カラシ成分入りの袋とか防鳥ネット、黄色い半透明のごみ袋、３カ月という中で、８月、９月、２カ月は過ぎたわけですけど、どのような結果が出ているんでしょうか。その辺、お聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"実はカラスの実験というのは二つありまして、５月からの廃棄物減量等推進委員という約５００人の地域からの代表の方にまず実験をやっていただくというのを５月から行いました。","voiceIndex":185,"id":"exchange-077"},{"speaker":"松澤委員","kind":"質問・要望","question":"いろいろ街の話、いろんな本なんかを見ますと、黄色い袋が有効だなんていう話が出て、今度の中でもおそらく１０月に終われば実証できるかなというふうに思っているんですけれども、黄色いごみ袋は高いんだよなんていう話がありますけども、いろいろ品川区はカラス対策でも先進的なところと聞いておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-078"},{"speaker":"石田委員","kind":"質問・要望","question":"ちょっとお聞きをしたいのは、まず初めに、非常に不勉強でわからないので教えていただきたいと思いますが、協議会の部分なんですが、覚書の見直し、あとは各区への移行等が行われていって、その処理が済んだら協議会は解散をしていくというような方向性が助役会のほうから出されてきたと思いますが、これは最終的に解散するというのはどこで議論をして、どこで判断をしてというのは。","respondent":"中山清掃リサイクル課長","answer":"実は、各区が処理するというもう一点の中に、いわゆる清掃車両の請負契約、いわゆる雇上契約、これについては移管時に一定の覚書の約束等がありまして、これとセットで、この見直しとセットで協議会のありようを考えるという状況になっておりまして。","voiceIndex":189,"id":"exchange-079"},{"speaker":"石田委員","kind":"質問","question":"内容はわかるんだけど、私の聞き方が悪かった。今の終わりにするというのは、どこで議論をして、どこで判断をするのか。例えば区長会なのか、助役会なのか、例えば一部事務組合の中なのか、どこでやるのかな、その場所を教えてください。","respondent":"中山清掃リサイクル課長","answer":"区長会の下命事項ということになりますので、このありようの最終的な結果というか判断は区長会という形になります。","voiceIndex":191,"id":"exchange-080"},{"speaker":"石田委員","kind":"意見","question":"内容は読んでわかっておりますが、経営委員会の権限と区長会の権限、いつも何か最後になると区長会でいろいろされているという話になってしまうような気がしているんですが、今も区長会だということですと、この権限、経営委員会もある、それは区長会の役員の方が入ったりいろいろしていると思うんだけれども、ここら辺の整理というか。","respondent":"濱野助役","answer":"この一部事務組合の存廃につきましては、やはりこれは普通地方公共団体が共同して設置しているわけですから、区長会等で議論するということになろうと思います。あくまで経営委員会は一部事務組合の運営について協議をするという場というふうに考えております。","voiceIndex":193,"id":"exchange-081"},{"speaker":"石田委員","kind":"提案","question":"今後の一部事務組合の中でその部分をとらえるんであれば、これは区長会なのか、今言った下命された助役会からもう一回提案するのか、さまざまそこら辺がすごく見づらくてよくわからないんですが、そういう考え方というのはどうやって我々が整理を、議会としてもというか、議員としてもというか、議会側が入っていくところがなかなかないなと思いながら、ただいつも報告を伺っているわけですが。","respondent":"濱野助役","answer":"そしてまた財調の算定もその数字を基礎として配分をしようということでやっております。ただ、非常に技術的に難しい問題がありまして、今財担部長会、課長会でも積極的に議論しておりますけれども、いまだまとまらないというのが今の時点です。","voiceIndex":195,"id":"exchange-082"},{"speaker":"石田委員","kind":"質問・要望","question":"時間もあれなんですが、ぜひその点を助役会のほうに下命をされて、最終的には自治権拡充のために今財調算定の話は今後の話で、まずそこが一番出てくる話でしょうが、一部事務組合全体の中で地域処理がいいのか、何がいいのかほんとうに東京都とその部分でよく言われるのは東京都、それじゃあいいじゃないか、各県みたいに最終処分をやっている部分は２３区はないんだから恵まれているみたいな話があると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-083"},{"speaker":"三村委員","kind":"質問","question":"私のほうから１２３ページの消費者団体助成金につきまして、あと１１９ページの大気汚染対策費についてお伺いいたします。そうであれば、なぜ一つの団体にだけ助成金が支給されているのか、理由をお伺いしたいと思います。","respondent":"長田区民課長","answer":"この中でもずっと事業を継続して続けてきておりますし、団体の中では一番大きな団体です。当初は３００名ぐらいの会員がいたわけですけれども、現在は１３０名です。その団体の実施をする事業に対して一部助成を行っているところです。","voiceIndex":199,"id":"exchange-084"},{"speaker":"三村委員","kind":"質問・要望","question":"いろいろ詳しいご説明ありがとうございました。社会状況の変化によって区民の求める税金の使い方というのも変わってくるかと思いますけれども、産業経済費に限らず、各種団体への助成金でありますとか、補助金についてどのような形で見直しを今まで実施してきているのか、手順でありますとか、基準でありますとか、そういったものがあれば教えていただければと思います。","respondent":"日下部企画財政課長","answer":"助成金、補助金全体についてのお尋ねですけれども、区のほうといたしましては、ただいまご質問にございました消費者の会をはじめとして、いろんな形で助成をする、これが一つはやはりいろいろ地域レベルでの活動の促進でありますとか、区だけではなくて、いろいろ公益性。","voiceIndex":201,"id":"exchange-085"},{"speaker":"三村委員","kind":"質問","question":"ぜひ、区民にもわかるように説明を、また区民のほうからのそういった税金の使い方ができるような、そういった仕組みづくりもぜひ検討していただければと思うんですけれども、お考えのほうをお伺いいたします。","respondent":"日下部企画財政課長","answer":"今最後にご質問ございました一種の税金の使途を住民の皆さん方の意向をある程度受けて、特定の人に活用すると、これは最近幾つかの自治体で施行していますけれども、ただ、これにつきましては、果たして一部の納税者の方の意向を税金の使途として限定をしていくと。","voiceIndex":205,"id":"exchange-086"},{"speaker":"三村委員","kind":"質問","question":"１１９ページの大気汚染対策費についてお伺いいたしますけれども、こちらの内容のほうをお伺いしようかと思っていたんですけど、時間がないのでちょっと、この大気汚染対策ということは基本的には住民の方の健康を守るという視点で行われているかと思うんですけれども、先日教育委員会のほうのぜんそく児童の調査、どういった形で教育委員会の方が把握されているのかお伺いしたところ。","respondent":"谷田部健康課長","answer":"したがいまして、全体の数字は私どもでは把握してございません。","voiceIndex":207,"id":"exchange-087"},{"speaker":"三村委員","kind":"意見","question":"中央環状品川線のことで、東京都のほうではぜんそくの児童数は品川区のほうにはほとんどいないみたいな資料が出たと聞いているんですね。実際にぜんそくの発作や何かが起こるのは６歳以下ということで、その辺についてきちんと状況を把握していかないと、実際の子どもたちの健康状況というのは守れないのではないかと思いますので、ぜひそういった点でも把握のほうをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":209,"id":"exchange-088"},{"speaker":"堺委員","kind":"質問・要望","question":"私のほうからは成果報告書の１１７ページ、先ほど来から出ておりましたが、私のほうからもちょっとお尋ねをさせていただきたいと思いますが、犬の登録・予防注射および動物の愛護に関連してです。","respondent":"島袋品川区保健所衛生課長","answer":"保健所・保健センター関係で品川区獣医師会と共同しまして、年３回ほど犬のしつけ教室を実施しております。中身につきましては、区民の方を対象に募集しておりまして、特に犬をどうやってリードしていくか。","voiceIndex":211,"id":"exchange-089"},{"speaker":"堺委員","kind":"質問","question":"わかりました。そうしますと、年３回ですから、「広報しながわ」によりますと、先着順に６０名ということですから、３回実施したとすると１８０人ですね。そのいわゆる役所のほうでよく言われます費用対効果という面から見た場合に、果たして効果が上がっているのかどうかです。９月２１日付のこれも同じく「広報しながわ」には、動物は責任と愛情を持って飼いましょう。","respondent":"島袋品川区保健所衛生課長","answer":"その後の予防接種していない方の督促状にも同じようなことを入れております。そういうさまざまな広報紙等で注意を喚起していますので、いろんな機会をとらえて周知していきたいなと考えているところです。","voiceIndex":213,"id":"exchange-090"},{"speaker":"堺委員","kind":"質問","question":"いろいろと守られているようなお話のようですが、もう一度先ほどの「広報しながわ」でいきますと、犬のふん・尿の後始末について、こう書いてありますね。犬のふん・尿の後始末は飼い主の責任です。飼い主が責任を持ってきちんと始末しましょう」となっているんですが、果たして１００％というのは非常に無理があるんだろうと思うんですが、大体どの程度守られているというふうな感想をお持ちですか。","respondent":"島袋品川区保健所衛生課長","answer":"実際問題、保健所・保健センターの畜犬担当にそのふんとか臭いとか放して飼っているとか、こういう苦情はかなり来ます。そのたびごとに畜犬担当の職員が注意していますけれども、率としてはちょっと不明ですけど、さまざまなトラブルは減ってはいないと考えております。","voiceIndex":215,"id":"exchange-091"},{"speaker":"堺委員","kind":"質問","question":"これはあくまでもやっぱり飼い主のマナーによるものだとは思いますが、だから、その辺のところもしっかりこういういろいろな犬のしつけ教室でありますとか、そんなところを利用してやっておられるわけですから、ぜひそういう目に見えた効果があらわれるように努力をさらにお願いしたいなと思うんですが、ここに一つこういうところが新たに出てまいりました。犬の公衆トイレ登場と。","respondent":"島袋品川区保健所衛生課長","answer":"先ほどの久慈市の例ですけど、非常におもしろいなとは思うんですけど、それのちょっと詳細がわからないものですから、飼い主をどうするのか、公共の施設としてどうするのかとか、ちょっと詳細がわからないものですから、参考にはさせていただきたいと思いますし。","voiceIndex":217,"id":"exchange-092"},{"speaker":"堺委員","kind":"質問・要望","question":"まだ若干時間があるようなので申しわけないんですが、ぜひこの久慈市の犬の公衆トイレについても資料を取り寄せるなどして検討していただければと思うんです。確かに最近はペットブームですから、いろんな人たちがたくさん飼っておられることはある面ではいいことだとは思うんです。それで、関連して先ほどから爬虫類の話が出ておりました。","respondent":"島袋品川区保健所衛生課長","answer":"ホームページ等を活用しまして、こういう特定動物につきましても注意してくださるようにと。そして、なお登録をしてくださいと、その辺をちょっと強く訴えていきたいなと思っています。","voiceIndex":219,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１７ページの成人歯科健診とアスベスト検診についてお聞きしたいと思います。この歯科健診に対しての区の考え方をひとつお聞かせいただきたいと思います。厚生労働省のほうで８０２０運動ということで、８０歳で自分の歯を２０本残すという運動を進めていますけれども、これに対しては品川区としては取り組んでいるのかどうか、このことについてもお聞かせください。","respondent":"谷田部健康課長","answer":"成人歯科健康審査につきましては、実施期間を定めまして、６月から翌年の３月３１日までの１０カ月間、その期間中に４０から７０歳の５歳刻みの区民の方を対象に区内の契約医療機関、いわゆる歯科医院ですけれども、そちらのほうで問診、歯の状況を調べたり、疾病の異常の有無。","voiceIndex":222,"id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういう状況に対して、やっぱり受診率をもっとアップさせて、早期発見・早期治療ということで取り組むということが必要だと思うんですけれども、受診率をアップさせるということでは、区としてはどういうふうに取り組んでいるかということをひとつお伺いしたいのと、それから厚生労働省のほうでは、「健康日本２１」ということで、２０１０年度までに歯をどれだけ。","respondent":"谷田部健康課長","answer":"その課題に取り組むために区としてどのようなことがご支援できるのかどうか、これは総合的な健康の事業の中で考えていくというふうに思ってあります。","voiceIndex":224,"id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この「８０２０推進財団」というところで出しているパンフレットを見たんですけど、ここでは「食べることは生きることだ。そういうところで、ぜひこの歯科健診を充実させていただきたい。そういうところでぜひ区民健診をやったら歯科健診というふうにセットで考えられるように、毎年歯科健診をできるような、そういう歯科健診に充実をしていただきたいと思うんですけれども、いかがでしょうか。","respondent":"谷田部健康課長","answer":"成人歯科健康診査ですけれども、昭和６１年度に４０歳を対象に創設をいたしまして、その間、８年後の平成５年度には対象者に５０歳を追加いたしまして、その４年後には４５歳、５５歳、平成１３年度、ですからその４年後ですね、また６０歳を追加して、年々拡大しまして。","voiceIndex":226,"id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やっぱりもちろん健康は自分で守るのが基本ですけれども、それの動機付けというのが必要だと思うんですよね。やっぱり早期発見・早期治療、予防は医療費を抑えるという効果のほうにつながってきますので、ぜひこれは今までも年齢拡大をずっと取り組んできていただいている品川区ですから、ぜひこれは毎年ということでご検討を要望して、次の質問に移りたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"それともう一点、最後だと思いますけど、区民健診での胸部レントゲンで診断ができるかですけれども、生活歴、それからいろんな症状、それに加えてレントゲンを読影して、通常は難しいというふうに我々理解していますけども、その状況次第ということになると思います。","voiceIndex":228,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点でぜひ品川区でも学習会、講習会、区民向けの講習会などに取り組んでいただきたいというふうに思うんですけれども、いかがでしょうか。そういう点では、手遅れにならないための早期発見とやっぱり区民の不安にどう答えるかということがすごく大事だと思うんですけれども、そういう取組みについてはいかがでしょうか。","respondent":"青山品川区保健所長","answer":"学習会等の件ですが、アスベストにつきましては、工場があったり、そしてその周辺であったりというような非常に可能性の高いところについては、これらのことについて重点的にやっていく必要がありますが、むしろ品川区の場合にはそのような工場もなく。","voiceIndex":230,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民健診はいろいろ医師会のどこの医院でもできるというふうな状況になっていますので、改めて私は自治体独自に取り組んでいただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-099"},{"speaker":"本多委員","kind":"質問・要望","question":"主だったところは、「最小の経費で最大の効果を上げるために、可能な限り民間で対応できるものは民間にゆだねていく必要がある」という基本原則があるんですけれども、この基本原則を生かして今後の経営委員会に動いていっていただきたいと思うんですが、その辺の大原則、基本原則がしっかり生きていけるものか、ちょっと確認をしたいと思います。","respondent":"中山清掃リサイクル課長、田中環境課長","answer":"この経営計画、現在詰めの段階ですけども、その柱の中に効果的でスリムな経営を行う一部事務組合を目指すということで、効率的な組織づくりという中での組織の簡素化、定数の見直し、それとあわてアウトソーシングの推進ということで。光化学スモッグの状況ですが、平成１６年度光化学スモッグ注意報が、これは基準値以上、都内では０.２１２ppm以上、基準値以上の場合、光化学スモッグ注意報を出すわけですが、平成１６年度は１３件なっています。","voiceIndex":234,"id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"清掃のほうは当然アウトソーシングは進めていくということなんで、それで当然進めていただきたいんですけど、安定的な運営をしていくには、例えば予算がかかりますよとか、そういうことを経営委員会が言ってきた場合とか、当然そういったことはないようにしっかりとした対応をしていただきたいと思うんですけども、それと人事上の体制整備についてお聞きしますけれども。","respondent":"中山清掃リサイクル課長","answer":"２１年度以降の扱いという長期的な部分についてはまだこれはこういうものを実あるものにしながら検討していくですので、これ以降の扱いについてはまだありますけれども、むしろ暫定的期間の扱いについても具体的にどうするのか。","voiceIndex":237,"id":"exchange-101"},{"speaker":"本多委員","kind":"質問・要望","question":"工場のほうのことに移りますけども、清掃工場のアウトソーシング、技術があれば民間でもできると私は思っているんですけれども、例えば電池のリサイクルなんですけども、平成１３年に資源有効利用促進法に伴いまして、自主回収、リサイクルの義務づけというのができておりますけれども、例えばこういったものも技術があれば当然民間で義務づけられているわけですから。","respondent":"中山清掃リサイクル課長、田中環境課長","answer":"これについて運転業務の委託を開始するということになっておりまして、このように安定的、事故のない運営を当然としながらも、こういう民間企業の熟成を見ながら、部門部門の委託が進んでいくものというふうに考えております。その点で区別にそれぞれ光化学スモッグの注意報を出す、その値を出すというのはなかなか難しいところというふうに、いわば空気が流れて広域的にしていますので。","voiceIndex":239,"id":"exchange-102"},{"speaker":"本多委員","kind":"質問","question":"それで、清掃のほうなんですけれども、最終処分場の延命というところでお聞きしたいんですけど、先ほども廃プラスチックのサーマルリサイクルというところで、燃えないごみの扱いは１８区と５区で取り扱いが違うというところだったんですけれども、処分場の延命についてはどこを中心にどのように協議をしていくかお伺いします。","respondent":"中山清掃リサイクル課長","answer":"清掃工場の灰について、灰溶融という形でスラグになって出てきます。したがって、これはいかに有効に公共工事等に使い、埋め立てにさせないかというのがポイントになってくるかと思います。そのほか、廃プラスチックの扱いについても検討している、こういう状況です。","voiceIndex":242,"id":"exchange-103"},{"speaker":"西本委員","kind":"確認","question":"私からは１１５ページの衛生統計調査費、１１８ページ、母子保健指導費、同じページの健康教育事業、１２４ページの都市型観光、時間がありましたら１２４ページの製造業活性化支援事業についてお伺いいたします。これらはどういうものなのか、目的、それからその他調査というのもありますし、どういう目的で何に使われているのか、品川区においての位置づけをお答え願いたいと思います。","respondent":"谷田部健康課長","answer":"今委員ご指摘の国民生活基礎調査ですけども、平成１６年度は７地区で、その前年の１５年度が３地区で、いわゆる地区数が増えているということと、対象世帯数が増えているということで、国民生活基礎調査につきましては、４年に１度大規模な調査を実施しています。","voiceIndex":246,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"国の流れのものだということはわかったんですが、これは統計的にとっているというものだと思いますけれども、品川区にとって何かこれの調査によってフィードバックされて、具体的な行動とか事業に転化したものがあるのかどうか。それから、新しい項目では、医療関係者調査というのが入ってきております。これはどういうものなのかを教えていただきたいと思います。","respondent":"谷田部健康課長","answer":"これは平成１６年度実施いたしましたけども、２年に１回実施する調査です。これは医療というサービス供給面からの調査を国のほうとしては行うと、そういうものになってあります。","voiceIndex":248,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問","question":"ですから、品川区がどうであったのか、品川区の場合には、率先していろんな事業を展開しているという観点を考えますと、そのデータをもとにさまざまな事業が展開されるんではないかなというふうに思いますので、有効活用をぜひお願いしたいと思います。","respondent":"川口品川区保健センター保健サービス課長","answer":"健診に未受診の方たちをどう把握しているかですけれども、ご案内のように、乳幼児健診は九十数パーセントの受診率で、３歳児、１歳半が八十数パーセント、これが受診率ですけれども、その後に未受診者に関しては電話等で把握しています。","voiceIndex":250,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問","question":"もう一つお答えしてほしかったんですが、児童相談所との関係ですね、虐待防止等々も含めてかなり役割が変わってこようかと思います。それから、先ほど１歳６カ月、３歳児健診のほうも、ほとんど診断をしていない方への実態把握もされているという認識でよろしいんでしょうか。","respondent":"川口品川区保健センター保健サービス課長","answer":"最後のご質問ですけれども、３歳児健診の把握ですけども、八十数パーセント、先ほども申し上げましたけれども、受診率が八十数パーセントで、その後に健診の未受診者に関しても把握してございまして、数値はちょっとすぐには出てまいりませんけども、その概要としましては。","voiceIndex":252,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"当然３歳児、４歳児になってきますと、保育園、幼稚園という形になりますので、そこでほかの機関が状況把握ということはできようかと思いますので、その辺の連帯というのも重要かと思いますが、関連機関との協力体制がどのようになっているのか、それともそこに行かないまでも、実態調査という意味でのものがほんとうに聞いただけでいいのか。","respondent":"川口品川区保健センター保健サービス課長","answer":"それと、虐待および虐待を疑われた後どうするかというお尋ねだと考えていますけども、我々のほうの事後処理および対応としましては、保健所の健診、その他の健診もあります。","voiceIndex":254,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問・要望","question":"なかなか親御さんに会う、子どもに会わせないという場合もありますので、非常に難しい部分に入りますけれども、どうしてもそこに踏み込んでいただいて、早期に対処いただけるような仕組みづくりを、それから近隣のいろんな方への協力を求められるようにシステムをつくっていただきたいと思います。","respondent":"谷田部健康課長","answer":"健康センターにつきましては、現在業務委託ということで民間の会社のほうに委託をしているところでございまして、今回指定管理者につきましては、平成１９年度に指定管理者の導入に向けて今後検討していくというスケジュールになってあります。","voiceIndex":256,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問・要望","question":"このインストラクターですけれども、実は委託しているところも委託をしているんですよね。外部委託という形なんですね。品川区としてはどういう考えになるんでしょうか。例えば私たちは業務委託をするときに、委託先が直接関与してほしいと。それはどこまで品川区が関与すべきことなのか、全くしないという考えなのか、それはいかがでしょうか。","respondent":"谷田部健康課長","answer":"例えば水中散歩教室みたいな、そういうものにつきましては、区内のスポーツ協会のほうの指導員をお願いしてやっていただくとか、そういうそれぞれの得意分野を生かしながら区民の健康づくりをお願いしているわけですけれども。","voiceIndex":258,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと時間がなくなってきていますので、考えを教えてほしいと思うんですが、確かに委託をして区とそれから委託業者のほうの契約の中で、そこの中の契約ですから、その委託先がどういう形をとろうが、区としてはちゃんと事業を展開すればいいというふうになるかと思います。ですから、同じことをやっても、私たちは関係ないと言えるのかどうかというのは、やはり難しいところがあると思います。","respondent":"金子産業振興課長","answer":"それ以外に観光のネットワーク結成支援、それから観光のタウンコーディネーター配置、さらに観光資源台帳の調査研究、こういったものをすべて品川観光協会のほうに委託しているものです。","voiceIndex":260,"id":"exchange-111"},{"speaker":"西本委員","kind":"意見","question":"実際やるための基盤づくりというふうに予算をかけたというふうに認識したわけですけれども、やはり、具体的に目に見えないと、１,０００万円がどういう形で活用されているのかというのが見えませんので、今後具体的な目で見えるような活動として報告していただくよう期待をして終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":262,"id":"exchange-112"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、急な夜間の受診では、今親御さんとの二世代住宅とか、そういう世帯で住んでいる方たちも少ないですから、働き方によっては母親一人が子どもを連れていく場合とか、あと兄弟がある場合には、その子どもたちをみんな連れていくことが夜間に大変不自由な状況とか、そういったさまざまな状況がある中で、やはり区民の方の要望としても地域バランスを考えて、品川寄りのエリア。","respondent":"谷田部健康課長、田中環境課長","answer":"私ども、確かに小児科を標榜する医院が減っている中では、小児科の夜間の問題とか、そういうのが非常に重大な問題だという認識は持ってございまして、今後とも品川地区においてそのような小児平日夜間の開設が可能かどうか。それで、エコスポット事業では２,４００万円程度の事業費というところが大きな中身になっています。","voiceIndex":264,"id":"exchange-113"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、一般的に女性の小児科医の方々が多くて、自分の子育てをしながら、そういった過剰な労働によって少しお休みをされる方ということもあるというようなお話を伺っていますので、そういう方たちの登録制度、いっとき仕事を休んだ場合に、医療にすぐ復帰できるかというのは非常に問題があるかと思いますけれども。","respondent":"田中環境課長","answer":"ノーレジ袋運動をやることによって、実際に買物袋を持っていくとか、レジ袋を断るという人が増えているということで商店のほうからは聞いております。ということで、大量消費、大量廃棄みたいな、ライフスタイルを見直すいい意識変革の事業になったというふうに評価しております。","voiceIndex":267,"id":"exchange-114"},{"speaker":"井上委員","kind":"質問","question":"事務事業概要のほうで平成１６年度の実績として、ノーレジ袋運動の参加状況というこで、４３商店街、５７７店舗という実績があるわけですが、５７７店舗というのは、品川区の店舗の何割が参加をしているということになるのでしょうか。","respondent":"金子産業振興課長","answer":"店舗が私ども手持ちの数字では約４,０００店舗という数字ですので、４,０００分の５７７ということですから、２０％弱です。","voiceIndex":269,"id":"exchange-115"},{"speaker":"井上委員","kind":"質問","question":"先ほどレジ袋を断る人が増えているという印象があるという中で、参加をしている店舗が２０％しか今いないという、こういった状況の中で、私たちもこの運動が区民に浸透しているというような感覚にはないんです。ここのところで昨年も決算特別委員会で質問させていただきましたけれども、事務事業評価がＣでした。どのように昨年度具体的に見直したのかお答えください。","respondent":"田中環境課長","answer":"レジ袋ですが、商店の業種によって、例えば飲食店であればレジ袋は出しませんので、単純に２０％しか普及していないということにはならないんではないかというふうに考えています。","voiceIndex":271,"id":"exchange-116"},{"speaker":"川西委員","kind":"質問","question":"ただいまの質問の中の小児科医の件で一つ伺います。私も小児科医が減少しているということでは日々痛切に悩んでいる一人でありますけれども、区としては何でこんなに小児科医の成り手が少なくなったかという行政分析、今後の改善策は、区の問題ではありませんが、どう把握していらっしゃるか伺います。","respondent":"鶴見品川区保健所保健サービス課長","answer":"診療報酬等の問題で、一般病院の小児科がどんどん閉鎖されてきておりまして、中堅の病院がないといったところがありますので、また小児医の場合は一次救急、二次救急、三次救急の区別が非常に難しいといったところがありますので。","voiceIndex":274,"id":"exchange-117"},{"speaker":"川西委員","kind":"質問","question":"ほんとうにありがとうございました。それと同時に５日間勤務すると、大学病院に勤めている事務長の話なんですけれども、そういう点では５日間勤務するとほんとうに心身ともに疲れるというようなこと、診療報酬とそれから疲労の問題、今おっしゃったとおりだと思うんですけれども、解決策について、関係機関への進言というのは区の機関ではできないんでしょうか、伺います。","respondent":"谷田部健康課長","answer":"これは国全体の大きな問題だというふうに思ってございまして、区としてできるものは地域の医師会等と協力しながら医療サービスをどのように提供していくかというようなことは区としても考えるわけですけれども、これは国を挙げての話というふうになれば。","voiceIndex":276,"id":"exchange-118"},{"speaker":"藤田委員","kind":"質問・要望","question":"時間の関係で端的に質問をします。その際、非常に印象を受けましたのは、狭い、老朽化が進んでいる、また、駐車場等も狭くて使い勝手が悪いということと、あと２６号線と第二京浜ですか、ここからずっと入ってくるわけですが、道路が狭くて地域性からいってもあまり区が一番大事なこれからの仕事を支えるだけの荏原清掃事務所なのかなというふうなことを私最近感じているんです。","respondent":"中山清掃リサイクル課長、齋藤荏原清掃事務所長","answer":"そういう体制からいうと、日曜の勤務というものが現在できておらんわけですが、平成１８年以降、例えば車両の契約方法も各区の自由度が高まってくるという部分もありまして。荏原清掃事務所には平塚に４０人ほどの現業の職員と西小山に３０人ほどの職員がおりまして、狭いというふうに感じられますけれども、職員の休憩ですとか作業については十分対応できているものと考えております。","voiceIndex":279,"id":"exchange-119"},{"speaker":"藤田委員","kind":"質問","question":"清掃事務所につきましてはよくわかりました。一般的に地域住民の人たちも、こんな狭いところに事務所が、いいのかなというようなことを皆さんおっしゃっておりましたので質問させていただきました。粗大ごみの関係ですが、例えば私今日電話しますね。利用者に立った立場というのをやはり日曜日の先ほどおっしゃったこれとあわせて検討ができないかということなんですが、いかがでしょうか。","respondent":"中山清掃リサイクル課長","answer":"いずれにいたしましても、速やかにできる限りご希望に沿った収集に近づけるというのが本来ですので、曜日のありようもありますけれども、まず基本の中でできる限り速やかに受け付けから収集まで行っていくような体制、工夫。","voiceIndex":282,"id":"exchange-120"},{"speaker":"藤田委員","kind":"質問・要望","question":"家に帰ってきますとまだ置いてあるということで、やはり時間帯ですね、何時ごろにとりに行きますというぐらいの親切さがあっても私はいいのではないかなというふうに思うんですけれども、年末年始等の混雑した中で、それをやれという、非常にこれは酷だと思いますけれども、日常的にそうした利用者に対するサービスというのをぜひこれは検討していただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-121"},{"speaker":"林（宏）委員","kind":"提案","question":"何点かお聞きします。何人ぐらいの人で、何日間かけて、どういう結果が出て、それが平成１７年度にどう生かされているか、端的に答えてください。ゆっくりまとめて後で聞きます。それから、１２４ページぐらいからある産業振興の中の製造業の支援ですけど、去年品川見本市を開催という提案をしたんですけど、検討しますという今企画財政課長をやられている方からお話がありました。なぜこういうことが必要か。","respondent":"藤田道路公園課長、金子産業振興課長、中山清掃リサイクル課長","answer":"今回の実態調査ですけれども、あくまでも実態調査ということで、この次のステップの話ですけれども、実態調査までという調査なので。委員のご質問は今年の予算特別委員会でご提案のありました産業見本市ができないかというお尋ねだと思いますが、そのときも答弁申し上げておりますが。廃プラスチックのサーマルリサイクル、これはプラスチックの持つ熱エネルギーを有効利用する、焼却という形をとって有効利用するということですから。","voiceIndex":286,"id":"exchange-122"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"産業見本市については、後で資料を渡します。強く要望しておきます。循環型社会をつくっていく上でのサーマルはどんな効果があるのか。要するに、山の手のほうに大きい公園ばかりつくって、いわゆる海岸のほうの繁華街に緑が少なかったというような反省もそのときにされていたわけですから、やっぱりせっかく８００万円かけてした調査ですから、いろんなところに生かして使っていただきたい。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-123"},{"speaker":"須藤委員","kind":"質問・要望","question":"１１６ページ、衛生費でがん対策費、１１８ページ、健康づくり事業費、１２４ページ、商店街活性化推進事業についてお尋ねします。それから健康課でやっているのと、いわゆる小学校、中学校、幼稚園とかと、そういうところとの連携は健康づくり、食だけじゃなくて、もちろん運動もあったり、休養もあったりいろいろあるわけですけども、その辺の連携がどうなっているのかお聞かせ願いたいと思います。","respondent":"谷田部健康課長","answer":"１点目の前立腺がんのことですけども、たしか今年の予算特別委員会におきまして、前向きに検討していきたいというような答弁をしたというふうに記憶しています。","voiceIndex":292,"id":"exchange-124"},{"speaker":"須藤委員","kind":"意見","question":"そのときに、学校とも連携をとってというようなお話をされてきたと思うんですけども、いわゆるお子さんたちが小学校に入る、中学校に行く、そういったとき、いわゆる幼児のときから考え方、同じような考え方で持っていくべきだろうと思うんですが、その食というものも今栄養士といろいろ検討されているということなんですが、基本的にはどういったものが我々人間というか。","respondent":"川口品川区保健センター保健サービス課長","answer":"その考え方ですけども、これはただいま申し上げましたように、それぞれの年代によってその食および栄養素、それがもともと違いますので、それに沿って我々保健所・保健センター、栄養士、それから品川区栄養士会、それから学校等の連携を進めてまいりたいと考えています。","voiceIndex":294,"id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"健康であるために、さっきから歯というものが大切だよと。人間は３２本歯があります。食べ物で健康体になるというのは何だろうかなと思うんですが、いわゆる免疫力を高めるんだというようなお話がありますけれども、その辺についてはいかがでしょうか。","respondent":"青山品川区保健所長","answer":"特に免疫力の問題、アレルギーの問題やいわゆる体力というようなものをつけていくに当たっては、そうしたどういった食物をどのようにどういった方に対して、お薦めしていったらいいのか、あるいはここは控えていくというようなことをきめ細かくやっていく必要がありますので。","voiceIndex":296,"id":"exchange-126"},{"speaker":"須藤委員","kind":"質問・要望","question":"３分の２が公的機関ですよ、３分の１が商店街ですよ。ですから、そういった意味である程度商店街の活性化の基金のようなものをつくっておいていただいて、そういったつなぎのときにもお金が入りますよというのが都なり国なんかでわかっているわけですから、それを回しておいてあげて、入ったら区のほうに基金を戻してもらう、そういったシステムをつくられたらいかがかと思うんですが、どうでしょうか。","respondent":"金子産業振興課長","answer":"私どもとしましては、商店街連合会の事務局等とよく連絡を取り合いまして、実情を調査した上で支援策が可能かどうかと、これについては検討しているところであります。","voiceIndex":298,"id":"exchange-127"},{"speaker":"須藤委員","kind":"質問・要望","question":"いわゆる役員になかなか成り手がないけども、ボランティアの方々にお願いをしたりとか、あるいはいろんなイベントで街の人たちにお願いして、学校だとかそういったお子さんたちにご協力いただいて、その人たちにある程度ボランティア的なものでお支払いをさせたりというような、いろんな意味で商店街の基盤整備の費用というのが有効に使われてきている状況なんで、これについてはいかがでしょうか。","respondent":"金子産業振興課長","answer":"商店街の基盤整備ということでのお尋ねですけれども、確かに私ども商店街の中でのさまざまな活動、研修会等々の支援によって中でのレベルを上げていく、あるいは外からのアイデア、あるいは力、例えばボランティアなどによってイベント等あるいは販促事業等を新たに展開していく。","voiceIndex":300,"id":"exchange-128"},{"speaker":"須藤委員","kind":"質問","question":"今お話のように商店街のイベントに近くの学校の方々にご協力いただいたりというようなことが、ほんとうにそれが町会とはまた違った形での地域のコミュニティの場面になってこようかと思うので、そういった意味で広く、もちろん産業振興ということをベースにするんですけども、ただそれだけで終わるんじゃなくて、いわゆる地域のコミュニティという面から見ても支援をしてきて。","respondent":"山田区民生活事業部長","answer":"そうした重層的な部分の活動がいわゆるコミュニティの活性化につながっていくというふうに私どもも考えてございまして、たしか平成１７年度からその学生たちの活動についてのご支援ということで。","voiceIndex":302,"id":"exchange-129"},{"speaker":"南委員","kind":"質問・要望","question":"二つ目にはリサイクルの問題でありますけれども、かなり種類を多くしてリサイクル対策をとっておられますけれども、拠点回収とか、店頭回収とか、資源回収とか、いろいろな形でやっておりますが、対象となるペットボトルも随分増やしてきておりますが、ペットボトルについては最近資源回収としては始まったわけですが、平成１５年度と１６年度の比較を見たところでは。","respondent":"田中環境課長、中山清掃リサイクル課長","answer":"車も新しい排出基準に沿った形で買いかえられてきますので、中期的に改善していくものと考えています。そのまま継続いたしまして、１６年の１０月から全域回収を開始したということで、ここで一気にエリアが人口規模で言っても１０倍ぐらいに広がりました結果として回収量がこのように大きく伸びたです。","voiceIndex":305,"id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"それで、大気汚染のほうなんですが、これだけの数字が出ているということについてのちょっと認識も伺いたかったんですが、改めて教えてください。したがって、この大気汚染の状況がもっとこれを改善させていかなければいけないというふうに思っておりますので、改善する必要があるかないか、こういう現状に対しての認識をどういうふうに思っておられるのかを改めて伺いたいと思います。","respondent":"田中環境課長、中山清掃リサイクル課長","answer":"八潮の状況については、自動車の状況等についてはよく認識しております。それで、事実的なところを若干説明します。拡大生産者責任と区の収集との関係ですが、いわゆる容器包装リサイクル法の改正に向けての論議というのが国レベルで行われておりますけれども、これに向けて区としても一つは東京都の自治体のリサイクル連絡会。","voiceIndex":308,"id":"exchange-131"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひこの見解もお願いします。ですから、品川区一つの小さな自治体だけでできることでは到底ないということは承知なんですが、そういう方向に早く進むように、品川区からも大いに求めていただきたいというふうに思っているわけです。どの程度までその研究が進んだのか、ちょっとお知らせいただきたいと思います。","respondent":"田中環境課長、中山清掃リサイクル課長","answer":"そういう意味で、今の時点で健康診断云々と私が言及すべきものではありませんので、基本的に今、日本中、世界中が排気ガスの問題については。したがって、例えば、今国レベルでもバイオマスの研究ということでガス化の研究等ありますけれども、都市型の中で十分生かせるものが、これはまたコストもしかり、それから収集の経費。","voiceIndex":311,"id":"exchange-132"},{"speaker":"南委員","kind":"質問・要望","question":"それはそれとしてわかるんですが、私はやっぱり健康調査をぜひするべきだというふうに思うので、担当課長からご答弁をお願いします。それと、その元凶になる車をこれ以上増やさないためには道路をつくらないという、こういう角度からも中央環状品川線のところはぜひ中止を求めていきたいというふうに思っております。","respondent":"谷田部健康課長","answer":"大気汚染の関係ですけれども、私ども所管しております公害健康被害の補償事業では、既に大気が改善されているということで品川区は指定が解除されておりまして、昭和６３年からいわゆる新たな認定はないというような実態です。","voiceIndex":314,"id":"exchange-133"},{"speaker":"土井委員","kind":"質問・要望","question":"それはおかしいのはおかしいとしてこちらに置いといて、だれが、いつ分別の方式を改めるんですか。要するに初めから燃えないごみとして燃やしたくないごみを集めてくるときに、始めからコンクリートだとかセメントだとか、瀬戸物だとかガラスだとか、金属だとかというものはちゃんとこっちにやっておいてくださいよ、プラスチックのものは燃えるんですから、こっち側に入れてください。特に収集運搬。","respondent":"中山清掃リサイクル課長、冨岡品川清掃事務所長","answer":"現在の一部事務組合による運営と考えますと、そこで先ほど来申し上げた２３区での検討調整というのを行っている、これはいろいろと焼却というものに対するいろんなご意見も踏まえての論議をやっているところですけども。１５年度と比較いたしますとプレス車につきましては４台少なくなっております。それで、車両の種類につきましては、両方とも低公害車、２台とも低公害車のＣＮＧ車です。","voiceIndex":317,"id":"exchange-134"},{"speaker":"土井委員","kind":"質問・要望","question":"要するに、三位一体、こんないい話だといって自慢をしているんですけれども、中小企業につくってもらって、皆さんのコミュニティができて、子どもの安全が守れるという、こんな立派な話はないといって一生懸命宣伝をして歩いているわけですけれども、そんなようなことが言えるように我々なりたいものですから、我々も宣伝マンにしていただきたいと、こういう意味も含めてちょっとお聞かせをいただきたい。","respondent":"中山清掃リサイクル課長、金子産業振興課長","answer":"先に車両の対応ですけれども、軽自動車の車両、大体積載量が２００キロぐらいです。最近の状況ということですけれども、そのグループ内での受発注等々もやっておりますが、先ほど都立高専の質問が出たときにもご答弁申し上げましたが。","voiceIndex":320,"id":"exchange-135"},{"speaker":"土井委員","kind":"質問","question":"一つ、そのものづくり大賞、せっかくもらったやつ、何だったのか、宣伝しようにも大賞をもらっただけじゃ宣伝にならないので教えてください。ぜひみんなで宣伝しましょう。それで、そういうことだと思います。若干感想等も含めて、先ほどの最後の質問も含めてお答えいただいて終わります。","respondent":"金子産業振興課長","answer":"これは荏原のほうにあります新興セルビックという会社がプラスチックの成形機という機械は大体縦が３メートル、幅が１メートルの機械でごくごく小さいものをつくるというものだったんですが、この会社がつくりました新しい機械は卓上におけるほんとうに３０センチぐらいのもので。","voiceIndex":323,"id":"exchange-136"},{"speaker":"土井委員","kind":"質問・要望","question":"ぜひあそこに飾ってあったんじゃなかったかなと思ったんだけど、もし何だったら、中小企業センターにそういうものを飾ってあげていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":325,"id":"exchange-137"},{"speaker":"三上委員","kind":"質問・要望","question":"私は１１５ページ、公衆浴場、それから１１７ページ、飼猫の去勢・不妊手術の助成、それから同じくアレルギー等居住環境調査指導事業に関係するのかどうかちょっと、適当な項目がここなのかどうかということはちょっとわかりませんが、お伺いしたいと思います。そこで、現在の助成を受けられる時期というのは、以前は１０月か１１月ぐらいということであったと思うんですが、今はどうなっているんでしょうか。","respondent":"谷田部健康課長、島袋品川区保健所衛生課長","answer":"いわゆる飼猫の去勢・不妊手術の関係ですけれども、平成１６年度まで９月に募集をかけまして、大体手術は１１月ごろに行うということで。シックハウス関係ですけれども、このアレルギー等居住環境調査指導事業で担当しております。一つは公衆浴場の設備等の整備補助金ということで、これはろ過器とか釜とか温水器とか、そういったものを限度額１００万円まで。","voiceIndex":327,"id":"exchange-138"},{"speaker":"三上委員","kind":"質問","question":"飼猫の去勢・不妊手術について、年に２回募集し、そして手術を行うということは前進だなと思います。しかしながら、この地域猫のたぐいというものは非常に幅広いですよね。それから、シックハウス症候群について、区内施設について空気汚染等の相談とか調査依頼といいますか、これは一般の調査の相談とかということもあると同時に、区の施設の調査についてはどうなっているでしょうか、まずお伺いします。","respondent":"谷田部健康課長、島袋品川区保健所衛生課長、宍戸施設担当課長","answer":"今年度から新たな事業といたしまして、いわゆる飼い主がはっきりしていない、いわゆる地域猫と言われている猫の去勢・不妊手術を初めて行いますので。保健所・保健センターで行っていますアレルギー居住相談ですけど、これは住民だけで対応していまして。区有施設のシックハウスに関する調査ですけれども、まず新築時、工事の完成したときに厚生労働省の指定の調査をいたしまして。","voiceIndex":331,"id":"exchange-139"},{"speaker":"三上委員","kind":"質問・要望","question":"公衆浴場の件でありますが、先日高齢事業課長の答弁の中で、しっかりと公衆浴場の件に関しては取り組んでいきますと企画財政課長もあわせておっしゃっておりましたが、そういった点で、これについて、そのときのちょっと答弁の中で出てきた東京都の平成１７年度健康増進型公衆浴場改築支援補助という、この話をされたんじゃないかなと思ったんですけど。","respondent":"宍戸施設担当課長、谷田部健康課長","answer":"先ほどちょっと言葉足らずでしたけれども、新築時だけではなくて、改修時も調査はしております。それから、家具等の備品類を入れてからも調査をしているです。公衆浴場に関しての所管ですけども、いわゆる公衆浴場につきましては、住民の生活に欠くことができない、公衆衛生を保つための施設だというふうに私どもは思ってございまして、ひいては区民の健康増進につながっている部分があります。","voiceIndex":335,"id":"exchange-140"},{"speaker":"三上委員","kind":"意見","question":"時間がありませんので、先ほどの東京都の要綱についてどういうふうになっているのかと。東京都の要綱については、品川区が事業計画を持っていて、品川区を通さない限り、東京都のほうじゃ受けられないというふうになっていますけれども、これについて今年の３月３１日付で発令されている要綱について、品川区はそれに対応する要綱なり、取り決めということができているのかどうか、簡単にお願いします。","respondent":"谷田部健康課長","answer":"３月３１日付の要綱ですけれども、私ども手元についたのは５月１９日ということで、東京都のほうの健康増進型公衆浴場改築支援事業というものですが、従来の多機能型公衆浴場改築支援事業と補助額も倍に引き上げ、それから健康増進につながるような事業展開について。","voiceIndex":338,"id":"exchange-141"},{"speaker":"三上委員","kind":"質問","question":"ということは、まだそれは決めてないと、検討もしていないと、こういうことでよろしいんでしょうか。東京都は各区市から上がってきたら、お金を出しますよという制度になっているわけ。私はそう思いますけども、それについての要綱なり何なりをきちっと決めて、それで窓口はこうで、ちゃんと受けますよと、どうぞ公衆浴場の関係者は出してくださいと、こういうものがあっていいんじゃないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":340,"id":"exchange-142"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1250#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":111614,"voices":341}},{"id":"h17-20051012-4","meetingId":"h17-c-settlement","date":"2005年10月12日","dateIso":"2005-10-12","committee":"決算特別委員会","time":"午前１０時０３分～午後５時３４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を151件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０３分開会 おはようございます。連日、お疲れさまでございます。ただいまより、決算特別委員会を開会いたします。 それでは","agenda":"○午前１０時０３分開会 おはようございます。連日、お疲れさまでございます。ただいまより、決算特別委員会を開会いたします。 それでは","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"おはようあります。初めに１２６ページの道路維持費ですけれども、いろいろな舗装工事をやられておりますけれども、平成１７年度になってしまって恐縮なんですが、特にヒートアイランド対策で、保水性舗装と、また遮熱性舗装を、今、実験されて、状況を見ているというふうに、平成１７年度の予算のところで伺っているんですけれども、今現在のその状況等を教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"調査は１１月まで続ける予定です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問・要望","question":"１１月まで続くということですけれども、夏ぐらいから始められたんじゃないかと思うんですけれども、現状の効果というか、そういった面がありましたら、教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"そのほかにも、保水性舗装等も、いろいろと今、細かいデータが出てきております。こういったものを１１月まで続けまして、最終的に、さまざまな観点から検証を行いたいと考えているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"水害対策で透水性舗装というのもやっていらっしゃると思うんです。関連して、これからヒートアイランド対策で、こういう形で遮熱性とか保水性舗装を進めていく中で、透水性舗装とまた違う目的になるんですけれども、その辺の縦分けをどういうふうに、区内でここは保水性、ここは遮熱性、ここは透水性と、分け方の基準みたいなものがありましたら、その辺を教えていただきたいと思います。","respondent":"松代管理工事課長","answer":"ただ、遮熱性舗装とは若干違う面がありますので、これからは、それぞれの効果を出すものを目的別に、今後、地域等もよく検証しながら、実際の施工面で実施していきたいと考えているところです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"続きまして、１３０ページの密集住宅市街地整備促進事業と木造住宅耐震診断支援事業とあわせてお聞きしたいと思うんですが、成果報告書４１ページに平成１６年度の密集住宅の取り組みが載っておりまして、これで大体わかるんですけれども、ここに、平成１６年度新規予定３地区として、「二葉３・４丁目、西大井６丁目地区」、「東中延１・２丁目、中延２・３丁目地区」、「豊町４・５・６丁目地区」と。","respondent":"伊勢住環境整備担当課長","answer":"東中延１・２丁目、中延２・３地区も、同じくワークショップ等を行ってあります。それから、豊町４・５・６丁目地区は、ようやく協議会ができ上がったです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"武内委員","kind":"質問・要望","question":"そういった中で、この間行われた都議会で、都知事の所信表明で、木造耐震の改修について、こういった密集地域、また地震で電柱等の倒壊が予想されるような、避難、消火活動に支障をきたすような地域においては、耐震改修、木造支援を考えるということで、来年度の予算に向けて、今、何か考えていると聞いているんですけれども、その辺の状況を何かおつかみでしたら教えていただきたいと思います。","respondent":"片田建築課長","answer":"特に担当レベルの中では、今、予算編成に向けて検討しているということで、区の支援策にさらに補助をしていこうといいましょうか、さらにそれをバックアップしていこうといったような方向で、検討が進んでいると聞いてあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"本間委員","kind":"質問","question":"１２８ページの補助１６３号線について、この３点を中心として質問したいと思います。先に補助１６３号線の件についてお尋ねしたいと思います。当初予定の年度に向かって、かなり急ピッチに進展があるようですけれども、その進捗状況について、お尋ねしたいということが１点。その辺の対応、あるいはその他、どのような形で、１００％事業完結に向けて進められているのか、お尋ねします。","respondent":"中島街路事業担当課長","answer":"今、鋭意、買収交渉が進んでおります。今現在は、生活の再建、あるいは営業の継続という視点で、代替地につきまして、いろいろご相談させていただいているです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"本間委員","kind":"質問・要望","question":"私どもが考えているほど簡単ではなくて、現地の人々は、その土地に生まれ、育ったという愛着があったり、特に小さな商店街ですから、その土地で昔なじみの人たちとの人間関係によって小さな商店を営んできた人々もいるわけですので、居住権と同時に生活権、あるいは営業権の保障等々についても、きちっとお話し合いを進めていただきたいと思っています。よろしくお願いします。次にいきます。","respondent":"山口交通安全担当課長","answer":"今後もまた、計画的に撤去を実施し、整理に努めたいと考えております。なお、東急目黒線の地下化に伴い、東急側に駐輪場の設置を要請していますので、東急側の協力を得られれば良好な状態になるのではないかと、今のところ、考えております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"本間委員","kind":"意見","question":"今、お話を聞きまして、将来的には東急の協力を得てということですが、この状態はいつまで続くのかという部分で、いつごろまでにどうだというのを、目途で結構ですから、お願いします。","respondent":"山口交通安全担当課長、中島街路事業担当課長","answer":"撤去してもまたすぐとめるような状況なので、２４時間とはいきませんので、その都度、対応していきたいと思いますので、ご理解のほど、よろしくお願いいたします。ただいまの西小山駅前の駐輪場の関係ですけれども、時期ですが、来年夏ごろ、目黒線が地下切りかえいたします。それをもって上部の整備に入っていきますので、時期といたしましては、平成１８年度以降と考えていただければと思います。","voiceIndex":20,"id":"exchange-008"},{"speaker":"本間委員","kind":"質問","question":"その時期が知りたくて質問したわけで、イタチごっこの部分は、毎回繰り返されるので、平成１８年夏ごろには、今の状態がなくなるというふうに理解します。この辺の部分は放置自転車区域を外れる部分で、なかなか手が下せないけれども、付近の人が困っているような部分があろうかと思いますけれども、その件の対策について、どのようにされているのか、お尋ねします。","respondent":"山口交通安全担当課長","answer":"委員ご承知のとおり、区域内は即撤去という形をとっておりますが、放置自転車禁止区域外につきましては、札をつけまして、おおむね１週間様子を見て、その後、そのまま放置の状態があれば撤去している状況です。","voiceIndex":23,"id":"exchange-009"},{"speaker":"本間委員","kind":"意見","question":"そういう法律といいますか、決まりの網の目をくぐるような部分が固まりとしてあると、それが既成の事実のような形でいく場合がある。そのことによって通路をふさがれたり、近隣の迷惑になっているという現実が見受けられますので、ひとつよろしくお願いします。次に、高潮護岸管理費等々の部分かもわかりませんが、花街道との関連についてお尋ねします。花街道との、管理上のすみ分けについてお尋ねします。","respondent":"藤田道路公園課長","answer":"こうした中で、花街道ということで、地元の皆さんにお花を植えていただく、イベント等を繰り返し行っております。そうした中で、区のほうとしては、清掃等、あるいは樹木の消毒、剪定といったことを担当しながら行っているものです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"本間委員","kind":"質問","question":"区としての担当は、樹木の剪定等ですが、例えば、春先の桜が散り終わった後のケムシの駆除、それから、犬の後始末がまだできていないような部分が路上に見かけられます。それから、夏などは、特に夜、子どもたちが花火を打ち上げたりする、近所での騒音の話も苦情としてあるようですが、その散乱した後始末等々についての管理の部分は、どこがどのようにやられているのでしょうか。","respondent":"藤田道路公園課長","answer":"ただ、その中で、地域の方々が、お花のことでいろいろ来られることもあろうかと思いますので、そういった場合には、少しでもご協力いただければと考えています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"本間委員","kind":"質問・要望","question":"花街道をお手伝いする部分で、もしこういうことがあればという要望になるんですけれども、水やりの時期、特に夏の散水について、最近では、好意ある方々がいらっしゃいまして、散水の給水栓みたいなものをプレゼントしていただいて、１カ所ありますが、その他の部分はどうでしょうか。それから、これも前から話しているんですが、車いすの乗り入れは可能なのか、どうなのか。この２点をお願いします。","respondent":"藤田道路公園課長","answer":"この辺は車いす等で行けるような形になってありますので、その辺とあわせながら、ご利用いただきたい。水がある、あるいは手すり等を設けると、また逆に親水性の問題がどうなのかと、いろいろな課題もありますので、そうした中でご利用いただければなと考えています。","voiceIndex":29,"id":"exchange-012"},{"speaker":"本間委員","kind":"質問・要望","question":"さまざまな要望がある中で、最近では幾つかのイベントがなされて、大変まちの人々でにぎわって、それぞれボランティアの皆さんがお花を植えているということが続いているようで、大変盛り上がっているように見受けられます。その中で、品川区も一部入っているようですが、規制緩和をされた中身、どこまで何がやれるのかという部分でのお尋ねをしたいと思います。","respondent":"上野都市開発課長","answer":"この規制緩和の中身ですけれども、今まで、公有水面上につきましては、例えば水上レストランなどを設置することはできませんでしたが、そういったものの設置について、都のほうで規制緩和をして、建てられるようになる制度です。","voiceIndex":31,"id":"exchange-013"},{"speaker":"本間委員","kind":"意見","question":"人々が水辺で楽しめるような新しい運河沿いの魅力的なスポットができるように思いますけれども、水上レストランのほかに考えられるのは、どのようなものでございましょうか。いろいろな規制緩和の中で、これは今までできなかったということができるようになったというものを、一、二挙げていただければ結構です。","respondent":"上野都市開発課長","answer":"考え方としては、水上レストランとか、台船などを設置いたしまして、それを活用して、例えば防災船着場に利用するとか、可能性としては、そこから定期船を就航させるとか、あるいは、台船を活用して何かイベントを行うとか、そういったような活用がいろいろできるかと思います。","voiceIndex":33,"id":"exchange-014"},{"speaker":"本間委員","kind":"質問","question":"おそらく単なる水上の利用だけではなくて、運河と運河、こちらからだと、勝島のほうから天王洲等々の運河のほうにつらなる散歩道がありますが、この辺の整備等は、あわせて行われるのでしょうか。","respondent":"藤田道路公園課長","answer":"私どもといたしましても、水辺を感じながらお散歩いただけるといったネットワークづくりは重要だと考えておりますので、そういった面で、これからも進めていければと考えています。","voiceIndex":35,"id":"exchange-015"},{"speaker":"本間委員","kind":"意見","question":"それと同時に、勝島の運河はその部分ではないとは思いますけれども、勝島運河の使い勝手に係わる規制緩和は、どのようになっておりましょうか。","respondent":"藤田道路公園課長","answer":"こうした中で、港湾局と連携を図ることで、さまざまなイベントができるような形になってくると考えておりますので、ぜひ、そういうような形で、地域の皆さんでまとまれればと考えております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"本間委員","kind":"質問・要望","question":"この部分は、一応、品川浦・天王洲と芝浦の２地区と書いてありますが、それはもちろん新しい規制緩和の流れの中でよしとしますけれども、近くにあります、私たちのところであります勝島運河という、もっと手近なところとの連携をしながら、水辺を豊かな区民の楽しめる場所にしていただきたいと思いますので、どうぞ、これからもよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私からは、１３０ページの都市開発費と、１３１ページ、都心共同住宅供給事業についてお伺いします。密集事業など、まちの安全を求める地域のところでは、まちづくり協議会等を立ち上げて、住み続けられる安心のまちづくり、論議がされていることと思います。質問なんですが、区内、いろいろな手法で地区計画がつくられていますけれども、まず、まちづくりの主役は一体だれなのか。","respondent":"伊勢住環境整備担当課長、阿部都市計画課長","answer":"しゃれた街並みづくりの関係ですけれども、これにつきましては、最初におっしゃった、いわゆる密集事業とは若干趣が違いまして、基本的には再開発促進区を定める都市計画が予定されております。あるいはまた、武蔵小山駅を中心にした交通の拠点でもあるという意味で、地域生活の拠点という形で、市街地整備基本方針では位置づけているという認識です。","voiceIndex":41,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面では、行政としては、調整的な役割を大いに果たしていただきたいと思っています。しゃれた街並みづくりのところなんですが、どうしてここが選ばれたのかというのが、もう一つちょっとしっくりしないので、その辺を聞かせていただきたいと思います。品川区内で、このような狭い道路に、６０ｍの高さの建物が建っているところがあるのかどうか、まず聞かせていただきたい。","respondent":"伊勢住環境整備担当課長","answer":"策定に当たっての住民意向調査ですが、ヒアリングという形式をとりまして、実は、地元協議会では、十分な蓄積がございまして、ブロック代表者への説明、平成１４年１１月の基本構想を踏まえた素案について説明をした中で、それらの代表者へ説明をすることによって。","voiceIndex":44,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、高い建物を望んでいないと、私は、この点から思うんですが、この点を一つお伺いしたい。それから、超高層の建築に対して、地域で反対の運動が起きているんです。合意形成を求めている、この声が上がっています。再度聞きたいんですが、周辺の町会と商店街はいっぱいあるんですが、意見をどこまで聞いたのか、この点を、再度お伺いしたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"今、Ｄ地区で近隣説明会等をやっているわけですけれども、そういう中でも、地域の声を聞くということです。それからもし、相談事があれば区のほうにということで、それも、まちづくり協議会、あるいは、都心共同住宅供給事業をやっているＤ地区にもお話をしています。","voiceIndex":46,"id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ここは容積率５５０％なんです。周りに広い公園があるところで、高い建物があるのはまだ許せますが、８ｍしかない道路に、両側に６０ｍの建物がそびえ立ったら一体どうなるのか、私はこの点をしっかりと認識をしていただきたいと思います。そして特に、武蔵小山東地区の開発は白紙に戻して、住民の参加のもとでやり直す必要があると思いますが、いかがでしょうか。","respondent":"岩田まちづくり事業部次長","answer":"建て直すにしても、敷地面積が小さなお宅が多いですから、そういうところでは、なかなか事業採算が成り立たないので、商売をされている方は非常にご苦労をなさっていた地区なんです。正確な日時は忘れましたけれども……。","voiceIndex":48,"id":"exchange-021"},{"speaker":"築舘委員","kind":"質問・要望","question":"１２９ページの公園新設改良費と、１３２ページの分譲マンションの管理支援を質問させてください。今後、新設するための基準と、どういう形で計画をしているかということをお聞かせいただきたいと思います。","respondent":"松代管理工事課長","answer":"密集市街地整備促進事業等々で、今、積極的にやってありますけれども、やはりそういった防災の観点というところから、そこに積極的に公園、道路の拡幅をしていくということが効果のあるものだと考えていますので、そういったことを勘案しながら。","voiceIndex":51,"id":"exchange-022"},{"speaker":"築舘委員","kind":"質問・要望","question":"例えば、今後、そういった形で、個人のお屋敷というか、緑があるところを売るという段階で、高層マンションができてしまうというようなことになった場合に、例えば荏原地区とか、品川地区、大崎地区ですと、まだまだ緑被率も、大崎は１１.１％、品川は９.８％、荏原が９.５％ということですし、防災上も、密集市街地ですと。","respondent":"松代管理工事課長","answer":"そういったところで、そういう要望等があれば、私ども、その辺を把握をしまして、所管としてまずそこに必要性があるのか、それをどういうふうに取り込んでいくのかということを判断しまして、その土地をどうするかという用地会議というのが庁内にございまして。","voiceIndex":53,"id":"exchange-023"},{"speaker":"築舘委員","kind":"意見","question":"その辺の判断というのは、やっぱりこれから、緑ということに関して、公のところと民間とそれぞれ総合して、もちろん屋上緑化も含めての緑ということなんでしょうけれども、うまく住民が快適に過ごせるような協力をいただければということだと思います。そういった部分もあるので、その辺のお考え、今後どういうふうに生かしていけるかというところで、ご意見をお聞かせください。","respondent":"藤田道路公園課長","answer":"これらの中で、地域のコミュニティといったものを形成されてきていると思いますので、今後も、みどりと花のボランティア、こうしたことを中心に進めていければと考えているところです。","voiceIndex":55,"id":"exchange-024"},{"speaker":"築舘委員","kind":"意見","question":"清掃は、今、シルバー人材センターをはじめふれあい作業所の皆さん、それから、かもめ工房の皆さん、民間委託は大きな公園だと思いますけれども、小さな公園の場合は、ボランティアプラス直営というような形になっていますが、その形でうまくいっている公園があるかどうか、聞かせてください。","respondent":"藤田道路公園課長","answer":"委員ご指摘のとおり、さまざまな形で民間委託、あるいは福祉団体への委託をして、公園の清掃を実施しています。","voiceIndex":57,"id":"exchange-025"},{"speaker":"築舘委員","kind":"質問・要望","question":"１３２ページの分譲マンションの管理支援ということなんですが、私のところもそうなんですけれども、新しい分譲マンションは町会に入っていない、入らないというか、そういうところがあるんです。行政の責任ではないかもしれませんけれども、でも一応、何かあった場合には行政がやらなきゃいけないわけですから、その辺を聞かせていただきたいと思います。","respondent":"浜脇住宅課長","answer":"一方、近隣説明の中で、町会長や商店会長にご説明して、そういうような接触を持つようにというようなことも、日ごろから指導しています。","voiceIndex":59,"id":"exchange-026"},{"speaker":"大沢委員","kind":"質問・要望","question":"私は、１２６ページ、駅周辺等放置自転車対策事業、それから１２８ページ、東急目黒線連続立体交差事業について、２点、お伺いします。","respondent":"山口交通安全担当課長","answer":"委員お尋ねの駐輪場の運営費が増加した理由につきましては、平成１６年度に、大井町西口等の６駐輪場を、自転車整備センター等から移管を受けて、増加しています関係で増加しているです。","voiceIndex":62,"id":"exchange-027"},{"speaker":"大沢委員","kind":"質問・要望","question":"６駐輪場増えたということで理解をいたします。２４時間体制で駐輪の管理をしているということですが、無人の駐輪場、そして人が常駐している駐輪場があるんですが、その中のスタッフについては、委託をされている会社が雇い上げているのか、それとも別の形で雇い上げているのか、ちょっと教えていただきたいと思います。","respondent":"山口交通安全担当課長","answer":"他については、業務委託している会社の社員が、随時巡回をして管理をしております。防犯カメラ等も設置しておりますので、そのような管理の万全を期しています。","voiceIndex":64,"id":"exchange-028"},{"speaker":"大沢委員","kind":"質問","question":"今、管理の委託ということでお話をいただいたんですけれども、来年４月から指定管理者制度が始まり、施設管理が開始をされるようになりますが、施設管理の上において、管理を委託している部分で、駐輪場の整備に関する条例によりますと、放置自転車の駐輪場の整備に関する条例ということになっておるんですけれども、指定管理者制度の最大のメリットはサービスの向上にあると理解をしておりますけれども。","respondent":"山口交通安全担当課長","answer":"指定管理者の件でお尋ねですが、１点確認させていただきたいのは、撤去のほうと解してよろしいでしょうか。","voiceIndex":66,"id":"exchange-029"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど、私が申し上げました、品川区自転車等の放置防止および自転車等駐車場の整備に関する条例には、先ほど、放置区域以外の場所では、おおむね１週間様子を見て撤去をするというようなご答弁をいただいたんですけれども、この条例には、撤去に関する項目がないと心得ておるんですが、そこのところ、どのようなのか教えていただきたい。","respondent":"山口交通安全担当課長","answer":"先ほど、ご答弁申し上げた１週間につきましては、遺失物法等、また道路管理者としての対応として、撤去、移動している状況です。","voiceIndex":70,"id":"exchange-030"},{"speaker":"大沢委員","kind":"質問・要望","question":"武蔵小山駅の件と絡むんですけれども、駐輪場が設置されるということで伺いましたけれども、先ほどもご答弁にありましたように、武蔵小山駅というのは、目黒区と品川区の区境にありまして、東急が設置をして、管理はまた東急がすることだろうと思いますが、駐輪場の管理はまた同形態でされるのかどうか、ちょっと教えていただきたいと思います。","respondent":"山口交通安全担当課長","answer":"参考ですが、ちょっとお話は逸れますけれども、先日、武蔵小山駅周辺の駐輪駐車対策協議会を開催いたしまして、駐輪に対しては有料で実施すべきだということで、地元の方のさまざまな意見を頂戴していますので、今後の駐輪場運営等の参考にしたいと、現在、考えております。","voiceIndex":72,"id":"exchange-031"},{"speaker":"大沢委員","kind":"質問","question":"今の駐輪の場所なんですけれども、東急で設置をするということでは心得ておるんですが、ほかのところで、今、管理委託をしている会社がありますね。目黒区のほうがかなり駐輪場を使ってくると思うんですが、そういった場合、品川区と目黒区はどういうような連携を取られて、税の公平性から、ちょっと問題はないかもしれないですけれども、疑問が残るんですが、その点は、どういうふうにお考えでしょうか。","respondent":"山口交通安全担当課長","answer":"行政範囲を含めますと、接点等、かなり難しい問題が発生すると思いますので、先ほど、お話ししました武蔵小山駐輪駐車対策協議会につきましては、目黒区の職員にも出席いただきまして、このような状況を説明して、その中で、今後は撤去、またキャペーン等を合同で実施するとか。","voiceIndex":74,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"１２９ページの河川費、同じページの公園整備のねむの木の庭整備と、１３０ページ、公園整備費で、ここはみどりと花のボランティアについてお伺いします。時間があれば、都市景観形成事業をお伺いします。しかし、ああいう天災だけは、どうしても避けられないという観点から、まずお伺いします。これは、やっぱり品川区の今までの施策の効果であるのかというのが１点。心構えも含めて、お知らせください。","respondent":"原田下水道河川課長","answer":"心構えですが、１００mmを超える降雨というのは、いつ発生するかわからないということが、最近言われておりますので、とにかく油断しないということ、常に注意深く水防体制を考えていくということが重要であると考えております。","voiceIndex":77,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"ねむの木の庭についてお伺いしますが、ようやく完成をしました。完成するまでに、またこれを公園にしようか、するまいかという議論もいろいろありました。私個人的なことになりますが、たしか平成１５年に、ちょうど住民から請願が出て、そのときに紹介議員にさせていただいたことから、総務委員会にも紹介議員ということで出席をさせていただきました。ほんとうに感無量でございました。","respondent":"藤田道路公園課長","answer":"ねむの木の庭ですけれども、平成１６年８月２６日にオープンいたしまして、その後、ちょうどプリンセスミチコというバラの花が今年の５月ぐらいに咲きました。その時期にあわせて、天皇、皇后両陛下が５月２４日にこられました。","voiceIndex":79,"id":"exchange-034"},{"speaker":"藤原委員","kind":"意見","question":"そこで公園管理という流れになるんですけれども、みどりと花のボランティアがあります。これが３７団体で３３１人ということですが、この団体は、具体的にどのような団体かということを、まずお知らせください。","respondent":"藤田道路公園課長","answer":"みどりと花のボランティアの関係ですけれども、基本的には、地域の３名以上の団体の方で登録をしていただいております。高齢者クラブ等の団体の方もいらっしゃいますし、あるいは、場所によっては、学校単位、あるいは町会全体で参加をしているというような形でもあります。","voiceIndex":81,"id":"exchange-035"},{"speaker":"藤原委員","kind":"質問","question":"軌道に乗っていると思うんですけれども、この方々から何か問題点とかは出ているのかということ。それから、事業の目的の中に、愛着という言葉が何回か出てくる。この事業をやったことによって、どれだけ花に対する、また道路に対する愛が深まったか、その辺について、２点、お伺いします。","respondent":"藤田道路公園課長","answer":"近所の方がお花を植えている、お掃除をしてくれているということを、周りの方がまた感じてくれて、地域の公園はやはりきれいしていこうというような気持ちにつながっていると考えています。","voiceIndex":83,"id":"exchange-036"},{"speaker":"藤原委員","kind":"質問","question":"１点、伺います。今後、この事業は積極的に進めていくんでしょうか。","respondent":"藤田道路公園課長","answer":"ぜひ、皆さんのご協力を得て進めていきたいと考えています。","voiceIndex":85,"id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"私は、成果報告書１２６から１２７ページ、道路維持費について、お伺いいたします。その中の交通安全施設整備事業、そして、路面維持管理費について質問します。交通安全施設整備事業のほうですが、現在、品川区内で、毎年約１,８００から１,９００件の交通事故があるということで、死傷者も大体２,１００人になっております。","respondent":"山口交通安全担当課長","answer":"第一京浜については、いわゆる真ん中を仕切って中央分離帯をつくって事故防止対策として進めていますが、中原街道については、先ほどお話ししたように２件も発生していますので、荏原警察署ともども、道路管理者、都第二建設事務所のほうに。","voiceIndex":88,"id":"exchange-038"},{"speaker":"須貝委員","kind":"質問・要望","question":"運転する身になりますと、突然出て来られて、対処しようがないんですね。確かに要請があれば、陳情があれば、どんどん区のほうで積極的にキララ舗装をやっていると思うんですけれども、例えば事故が多い地点、また比較的何回かあるというところに対して、陳情を受けたからというのではなくて、もう少し積極的に踏み込んで、区のほうで予算化して進めていくというわけにはいかないでしょうか。","respondent":"松代管理工事課長","answer":"そういったところは、情報をいただいて、私ども、いち早くそういった安全対策ができるような対応をしています。","voiceIndex":90,"id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"区道の路面維持管理費についてお伺いいたします。我々も、各地、視察等に行っておりますが、品川区の道路というのはほんとうにきれいなんですね。ただ、昨年、２億３,０００万円かかっておりますが、改修工事というのは何年ぐらいの周期で進められているんでしょうか。それとも、何年ぐらいの周期でやらなきゃいけないというようなことになっているんでしょうか。その辺、ちょっとお答えください。","respondent":"松代管理工事課長","answer":"路面改修です。おおむねですけれども、２５年から３０年ぐらいを目安に、路線をずっと職員が歩きまして、選定をいたします。ただ、当然のことながら、幅員構成だとか、交通量によって、道路の状況というのは変わってまいります。","voiceIndex":92,"id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"先ほど、ほんとうに道路維持、管理がしっかりしているということだったんですけれども、地方を見ますと、もっと悪くなってから再舗装したり云々しているところが結構多いと思うんです。我々も自転車で通っていて、いや、そんなにひどい道路ではなかったなと。もう少し長い期間見てもいいんじゃないかなというところも、ちょっと見受けられたんですけれども、その辺やはり、何か理由があるんでしょうか。","respondent":"松代管理工事課長","answer":"そういった意味では、これを計画的に進める中で、やはり歩行者が歩きやすいようなものといったときに、少し広く路面改修等もしなきゃいけないといったところでやっているところです。","voiceIndex":94,"id":"exchange-041"},{"speaker":"須貝委員","kind":"意見","question":"住民の皆さんからすると、何でやらなきゃいけないんだろうというような感覚を持たれている方も結構多いので、今言った維持管理をできるだけ安くやるためには、早めの修理というのはやむを得えないことなのかもしれないけれども、ちょっとその辺が、地元の方からすると納得できないということがありましたので、何でここをやらなきゃいけないんだと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":96,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、道路のキララ舗装のことが出ましたので、ちょっと関連でお伺いしたいんですが、見通しの悪いところで、自転車同士がぶつかったりとか、自転車と車がぶつかったりとかで、救急車で運ばれるというような事故は、結構地域にもあります。キララ舗装が、年間何カ所ぐらいつけられるのか、そういう予算がどうなっているのか、ちょっとお聞きしたいんです。","respondent":"松代管理工事課長","answer":"平成１５年度は２９カ所ということで、若干その辺のところは、年間で違ってまいります。それも、それぞれに手法を変えた安全対策というのを、適宜、必要に応じてやっているというような状況です。","voiceIndex":98,"id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほんとうに、これは地域の方にも有効だということで喜ばれていますので、ぜひ、この予算を増やしていただきたいということでお願いしたいと思うんです。やっぱり事故があったところは、なるべく早くつけていただきたいというのがありまして、ぜひ、ここら辺のところは、予算を増やしていただいて、なるべく早くつけていただけるようにお願いしたいと思うんですが、いかがでしょうか。","respondent":"松代管理工事課長","answer":"私ども、年間予算、約５,０００万円から６,０００万円ほどいただいております。そういう中で、今、委員ご指摘のとおり、事故等があった場合は速やかに対応するように心がけております。","voiceIndex":100,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ほんとうに、見晴らしの悪いところって、両方から坂になっていて、すごくブロックの高いところがあったりということで、よく交通事故が起こりやすいところってあると思うんです。先ほどもありましたけれども、ぜひ、そういうところは積極的に設置していただいて、事故がなくなるように取り組んでいただきたいと思います、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-045"},{"speaker":"中島委員","kind":"質問","question":"私は、１２８ページの道路新設改良費、補助１６３号線用地買収費に関連して、それから１２９ページ、河川総務費に関連して、それから、１３０ページの都市開発費、大井町駅周辺地区再開発事業、この３点に絞ってご質問いたします。初めに補助１６３号線、先ほども質問が出ておりますが、３月末で７８％の土地が獲得できたということで、非常にものすごいスピードだなと考えています。","respondent":"中島街路事業担当課長","answer":"移転補償の関係ですけれども、こちらにつきましては、補償基準に基づきまして算定していますので、それぞれの状況、商売をやっている方、あるいはアパート経営をしている方、あるいは、住まいの方、それぞれ基準によって算定していますので、一概にどこが高い。","voiceIndex":104,"id":"exchange-046"},{"speaker":"中島委員","kind":"質問・要望","question":"これは要望です。それから、１２９ページの河川総務費に関連してですが、立会川、先ほども溢水の話が出ておりましたが、私も２年ぐらい前だったでしょうか、あそこのかさ上げ鉄板がついてない場所があったということで、要望いたしまして、つけていただいて、上流の方は、そのことで喜んでいただいているわけですが、その分、雨がたくさん降りますと、下流に流れる水の勢いというのは非常に強くなります。","respondent":"原田下水道河川課長","answer":"これについては、かなり古い時期に工事が行われていたときのものではないかと推測しております。管理の面につきましては、とにかく、我々としては、今後、しっかりと徹底していくということで考えております。","voiceIndex":106,"id":"exchange-047"},{"speaker":"中島委員","kind":"質問・要望","question":"１３０ページの都市開発費の大井町駅周辺地区再開発事業ですが、これは広町地域の開発とありますが、昨年もこのような話が出ていたと思うんですが、これはかなり進んでいるのでしょうか。","respondent":"上野都市開発課長","answer":"広町地区の開発の点ですけれども、これにつきましては、平成１６年度、広町地区の開発構想に向けた検討という調査を行ってまいりました。","voiceIndex":108,"id":"exchange-048"},{"speaker":"中島委員","kind":"質問","question":"ここで９５０万円の歳出があるわけですから、それなりに着々と進んでいるんだと思いますが、ここで再開発検討委託とありますが、地元の方の声とか、そういったものは、ここでは吸い上がってこないのでしょうか。","respondent":"上野都市開発課長","answer":"ＪＲともよく協議をいたしまして、内容を十分に精査いたしまして、いつか地元の方にお示しする機会かできるように一生懸命頑張りたいと考えています。","voiceIndex":110,"id":"exchange-049"},{"speaker":"中島委員","kind":"意見","question":"ここの再開発が進めば、当然、ほかのところへの影響も考えられると思います。一部では、三又の商店街のほうでも、人の流れが全部こっち来てしまうのではないか、自分のほうに流れてこないのではないかという声も聞かれております。サンピア商店街の方も、つくりによっては大きく影響を受けるのではないかと思いますので、その辺のご配慮はどのようにしていくのか。お考えをお聞かせください。","respondent":"上野都市開発課長","answer":"広町地区の開発は、大井町駅周辺全体の発展に寄与する方向で検討すべきだと考えてございまして、特に、委員ご指摘がございました、サンピアなど、既存の商店街との共存共栄が図れるような機能の導入などについて、十分、検討してまいりたいと考えています。","voiceIndex":112,"id":"exchange-050"},{"speaker":"中島委員","kind":"質問・要望","question":"サンピアは当然のことだと思います。ただ、三又のほうは大分離れておりますけれども、向こう側の人の流れも考えてほしいという、地元の方からの要請もあります。あわせて、その辺のご検討も、区としてお考えいただけたらと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-051"},{"speaker":"菊地委員","kind":"質問","question":"私のほうから、２点お伺いをしたいと思います。それからもう１点でありますけれども、１３１ページの中高層建築物開発指導費に当たると思いますけれども、開発環境指導要綱について、お聞きしたいと思います。それから、第１４条についてですけれども、２０戸以上の集合住宅に課せられている自動車駐車場の付置義務、この目的は何なのかを教えていただければと思います。","respondent":"上野都市開発課長、浜脇住宅課長","answer":"そういったものを引き継いだ上で、目的といたしましては、品川区の中心核にふさわしい大井町の活性化に寄与できるような開発を進めていきたいと考えています。自動車駐車場ですけれども、今までですと、必要な駐車場の台数がないことによって、近隣に対する影響があるですので、基準を決めて、必要台数をお願いしているというものです。","voiceIndex":116,"id":"exchange-052"},{"speaker":"菊地委員","kind":"意見","question":"今、中心核というお話がありましたけれども、品川区の中心核として位置づけていくというのはわかるんですけれども、大井プレイス構想について言いますと、居住地も設けていくとか、四つの点についていろいろなことを書かれていますけれども、従来の高度利用とか、都市機能の更新という考え方、再開発でよく出てきますけれども、こういう考え方に基づいているものなのかどうか。","respondent":"上野都市開発課長、浜脇住宅課長","answer":"事業手法になどについては、まだ今後、検討していきますので、基本的な方向としては、そういう方向でいくんであろうという考え方でおります。今回の場合、ワンルームマンションですけれども、要綱上は１１台の義務が発生するんですが、いろいろな周辺等の環境を考えて、１１台というのが２台になって、９台については、隔地ということですけれども、飛ばして置くということで。","voiceIndex":119,"id":"exchange-053"},{"speaker":"菊地委員","kind":"質問","question":"ちょっとこの辺の考え方、どこに基本を置いているのか、お聞かせを願いたいと思います。本来、要綱でこういう形で設定しているというのは、青空駐車みたいな形態を押さえていくとか、あるいは緊急車両の問題とか、こういったことを考えてやっているわけですから、付置義務としてある必要な台数をその中に設けるというのが、本来、基本的な考え方ではないのかなと思うんですけれども、いかがですか。","respondent":"上野都市開発課長、浜脇住宅課長","answer":"事業として成り立つかどうかということにつきましては、需要動向ですとか、市場関係、マーケットの関係から判断することが多いわけですから、広町地区につきましては、そういった点につきましても、十分。しかし、現実問題として、いろいろな道路環境や周辺環境から見て、やむを得ないと認めることもございまして、そういった中で、今回の場合は道路との関係が一番なんですけれども、それらから見て、協議の上、当地になくても。","voiceIndex":122,"id":"exchange-054"},{"speaker":"菊地委員","kind":"意見","question":"これからの問題として、やっぱりしっかりとその辺を見ていくべきだと思うんです。安心して品川区に住み続けられるかどうかという問題というのは、特に、中心核として位置づける以上は、お年寄りですとか、障害者、こういった目線でまちづくりとして位置づけるべき、考えるべきものだと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":125,"id":"exchange-055"},{"speaker":"本多委員","kind":"質問","question":"初めに建設リサイクル法なんですが、平成１４年５月に完全施行ということです。昭和６０年にも、東京都内でコンポストのセンターができたり、いろいろな時代を経て、今日の建設リサイクル法があるわけですけれども、事務的な処理をするだけでいいのか、その辺、どうとらえていらっしゃるのか、まずお聞かせください。","respondent":"片田建築課長","answer":"これは、やはり国の法律ですので、全国一斉のパトロール等を、５月末、あるいは１０月末、年に２回ほど行いまして、きちっとした届出業者が適正な形で指導しているか、どうかということで、私どものほうも十分に監視しているという状況です。","voiceIndex":128,"id":"exchange-056"},{"speaker":"本多委員","kind":"質問・要望","question":"年に２回、パトロールをされているということなんですけれども、取り扱う事業者も、ＩＳＯ取得なんかでも積極的に取り組みをしている事業者、そうでないところ、若干差があるかもしれないんですけれども、届出の助言ですとか、勧告の実情について、どのような状況になっているのかお知らせいただきたいと思うんです。再資源化の実施状況についても、もう少し教えていただきたいと思います。","respondent":"片田建築課長","answer":"それを特定の処理施設のほうにきちっと届出の報告がなされているか、どうかという状況ですけれども、法律の中では、現状のどの程度それが有効利用されたかというところまでは、制度の中ではつかむことができない状況になってあります。","voiceIndex":130,"id":"exchange-057"},{"speaker":"本多委員","kind":"質問・要望","question":"法に基づいた届出の事務ということですから、そういった部分ではしっかりやられているんだろうと思うんですけれども、その後の再資源化というところまでいきましたら、把握、または押し進めるように考えていただきたいと思います。それから最後に、対応していく中で、民間と公共と、もし現状を把握されていたら、お聞かせいただきたいと思います。","respondent":"片田建築課長","answer":"確かに、法制度の中で、最終報告の数字といいますか、それがなかなか難しいところがありますので、その辺は、今後ちょっと研究させていただければと考えています。","voiceIndex":132,"id":"exchange-058"},{"speaker":"本多委員","kind":"質問・要望","question":"次の、同じく１３１ページ、建築行政費の建築指導費についてお聞かせいただきます。建築確認申請時の件名、仮称になっていると思うんですけれども、申請を出されたときの仮称と、でき上がったときの名称などの流れについて、現状をお聞かせいただきたいと思います。","respondent":"片田建築課長","answer":"ただ、その番号につきましては、案内図、建物の配置図によって、図面上に落とすと、１５ｍ間隔で番号がある程度決まってございまして、その番号があるところに出入口の位置が来るということで、自動的に住居表示の番号が決まるといったようなシステムになっております。","voiceIndex":134,"id":"exchange-059"},{"speaker":"本多委員","kind":"質問・要望","question":"ビル名とか、マンションの名称なんですけれども、建築行政として、住居表示の管理事務とのかかわりについてどうなっているのかなと思って、ちょっとお聞かせいただきたいと思うんです。その辺、逆に申請時の調整が必要なんじゃないかと思って、その住居表示のかかわり、建築行政としてどういうふうにとらえているか、ちょっとお聞かせいただきたいと思います。","respondent":"片田建築課長","answer":"ただ、住居表示の中で、アラビア数字とかいう形での登録がなかなか難しい部分というのはありますけれども、マンションの名称を含めて、その地域に合致したような名前ということは、これは営業上のこともありますでしょうけれども、行政のほうとしても。","voiceIndex":136,"id":"exchange-060"},{"speaker":"本多委員","kind":"質問","question":"最後に１点お聞きします、１２６ページの道路維持費に関連してなんですが、東五反田二丁目のオーバルコートから、キャッツが公演しているソニー通りのあたりなんですけれども、五反田駅と大崎駅との中間点に、通行者の利便を考えて、大崎駅、五反田駅への標識を設置できないか、お聞かせください。","respondent":"松代管理工事課長","answer":"十分調査しまして、検討いたします。","voiceIndex":138,"id":"exchange-061"},{"speaker":"川西委員","kind":"質問","question":"細かいことを少し並べさせていただいて、実績と成果、今後という順序に教えていただければと思います。２番目は細街路のことです。これについて、どういう内容なのか。３番目、商店街電線地中化事業。４番目、道路緑化対策費、これも実績、効果、今後の内容でお願いします。これの中身。それから次は従前居住者用住居、これはこの年度にどのぐらい入って、どのぐらい出たのか、これだけで結構です。","respondent":"松代管理工事課長、片田建築課長、藤田道路公園課長、伊勢住環境整備担当課長","answer":"民間申請による境界確定というところで申し上げますと、件数でいきますと、平成１６年度が２８件、確定延長で申しますと。これにつきましては、細街路事業そのものが、昭和６３年から実施してきた中で、１７年間行ってきたということで、ご案内のとおり。事業評価のＣですけれども、こうした花の植え替え等については、みどりと花のボランティアといったような活動も十分に考えながら。期間はまちまちですが、入居率でいきますと４４.１７％です。","voiceIndex":141,"id":"exchange-062"},{"speaker":"川西委員","kind":"質問","question":"再質問いたします。境界確定というのは、公民確定を進めている事業だと認識しているんですけれども、毎年、計画的にやられていると思います。平成１６年度末で、どのぐらい進んだかということだけ伺えばよろしいのです。それから、公共溝渠のところがＣになっていると、私申し上げたんです。これは何ゆえか、ずっと公共溝渠をやってまいりました。","respondent":"松代管理工事課長","answer":"河川維持管理の公共溝渠、払い下げの評価がＣとなっていますけれども、国有財産等の譲与事務が、平成１６年度ですべて終わってあります。私ども、払い下げ等も含めまして、順次、適正な管理、またはそういった事務をすべく、今、細かく見ながら進めていっているところです。","voiceIndex":147,"id":"exchange-063"},{"speaker":"川西委員","kind":"質問","question":"公共溝渠については、何か少し速度が緩んだんじゃないか。より積極的に、やはりまちづくりの一環として今後も進めてほしいと思います。商店街の電線地中化、これを質問したのですが、設計委託費ですからいいんですけれども、これからも、区内のこういう地中化をどのように進めていくかというのを、ちょっと知っておきたかったものですから、実績と同時に質問をいたしました。","respondent":"松代管理工事課長","answer":"これは、現在、２カ所進めてあります。一つは北品川地区、３商店街です。今年度から、既に企業者の工事に入ってあります。おおむね６年の工事期間をとりまして、完成は平成２２年を目途に進めております。もう１地区は戸越地区、３商店街を含んだ路線です。","voiceIndex":149,"id":"exchange-064"},{"speaker":"川西委員","kind":"質問・要望","question":"そうしますと、６年かかるということになりますと、これがワンサイクル、２路線終わらないと次の計画は立たないという認識を持っているべきでしょうかということだけ、確認をします。それは簡単なことですので、ご答弁だけで、あとは、区営住宅のことで質問をいたします。それから、関連はないんですけれども、開発指導要綱について、ちょっと要望も含めて質問をいたします。区は何をしているんだと。","respondent":"松代管理工事課長、浜脇住宅課長","answer":"商店街の電線地中化事業の今後の予定はあるかというご質問ですけれども、この２路線を選定するに当たりましては、平成１５年に区内の１０４商店街を対象としまして、地中化可能な５０商店街の中で意向調査を実施しました。今平成１７年ですから、あと七、八年ぐらいの余裕があって、その中で、２０年後をどうするかということを考える。基本的には、この方々との契約は２０年という契約できているのは事実です。","voiceIndex":151,"id":"exchange-065"},{"speaker":"川西委員","kind":"質問","question":"ワンルームマンションについては、地元のための生活しやすい環境を考えていただいて、少しご答弁が緩いような気がします。より積極的な、前向きな区政運営をよろしくお願いいたします。それから、今の借上型のほうなんですけれども、評価のところに空き家対策を引き続き検討するとあります。今、そんなに空き家があるのか、現状を伺いたいのと、なぜここにこういう文章が登場するのか伺います。","respondent":"浜脇住宅課長","answer":"２０年間で設定家賃に近づくんですが、古いものになりますと、その設定家賃が上がってまいりまして、補助のメリット感が少なくなっているというところがあります。その辺のところが、今、１５戸ぐらいなんですけれども、空き家になっている。","voiceIndex":154,"id":"exchange-066"},{"speaker":"川西委員","kind":"質問","question":"最後に一つ残りましたが、午前中に出ておりましたが、公園維持管理費の問題で、午前中と重ならないように１点だけお願いしたいんですが、例えば区民公園とか大型公園、せいぜい中型といいまして、子どもの森公園程度の規模で、今後、前面的に管理委託の方向かどうか、その方向性を伺いたい。","respondent":"藤田道路公園課長","answer":"現在、一括管理しているところについては、プロポーザルということで、民意を反映した形での運営をしておりますので、そうした中で、今後も公園管理を進めていきたいと考えております。","voiceIndex":156,"id":"exchange-067"},{"speaker":"山路委員","kind":"質問","question":"私のほうからは、３点ほどお伺いします。１点目は１２６ページ、駅周辺等放置自転車対策事業、交通安全対策費の信号設置について、２点目は１３０ページ、都市景観形成事業、区民の自主的なまちづくりへの支援について、３点目は１３２ページ、区営住宅費について、お伺いをいたします。","respondent":"阿部都市計画課長","answer":"今の状況ですけれども、まず、策定を受けまして、町会長の皆様に説明ということで、９月の時点で、全町会長に対して景観ガイドプランをつくったという説明をいたしました。","voiceIndex":159,"id":"exchange-068"},{"speaker":"山路委員","kind":"質問","question":"検討中ですが、景観形成事業のイメージ、平成１６年度、仮称ということで載っておりますけれども、施策の中に、平成１８年度以降ということで、建築物、または工作物の形態、または色彩、その他意匠等の制限とかありますけれども、この件に関しまして、今、地域住民と制限方法についてはどのような検討が行われているか、お伺いいたします。","respondent":"阿部都市計画課長","answer":"制限の話ですけれども、例えば、地区の中に入りまして、計画を立てたとしても、すぐに制限までに入るかということはなかなか難しいと思います。","voiceIndex":161,"id":"exchange-069"},{"speaker":"山路委員","kind":"質問","question":"確かに、都市計画課長が言われるみたいに、地元住民の納得のいく形で、これから景観を保守していく時代に入っていくかと思うんです。私もちょっと調べてみましたら、新宿区では、いろいろ高さ制限をしたり、中野区でも、問題が起こりましたよね。そういうことが、今後、制限ということとの絡みでどのように検討されていくか、お伺いをしたいと思います。","respondent":"阿部都市計画課長","answer":"例えば高さ制限とか、皆さんの合意があれば可能でしょうけれども、今、委員がおっしゃったマンションの高さの問題だろうかと思いますが、まずそういう合意をつくっていくということが大事ではないかなと考えています。","voiceIndex":163,"id":"exchange-070"},{"speaker":"山路委員","kind":"質問","question":"その制限の合意も含めまして、どうぞよろしくお願いいたします。次にまいります。北品川駅北口の駐輪場の計画と、あるいは、その周辺、放置自転車対策について、数年前に、いろいろな地域住民の陳情とかがありまして、その後、状況はどのように進んでいるでしょうか、お伺いをいたします。","respondent":"山口交通安全担当課長","answer":"委員ご指摘の場所は新馬場の駅と思われますが、以前、ここについては、放置自転車があったことから、京浜急行側のほうに、駐輪場の設置を検討した経緯があります。","voiceIndex":165,"id":"exchange-071"},{"speaker":"山路委員","kind":"質問・要望","question":"積極的に進めていただきたいと思いますので、よろしくお願いいたします。３点目の区営住宅費、東京都からの移管だと思いますが、現在、４３９戸計上されておりますけれども、今後、東京都からの移管はあと幾つぐらいあるか、お聞かせいただきたいと思います。","respondent":"浜脇住宅課長","answer":"都からは、原則的には、１００戸未満のものについては移管の協議をしたいということで来ておりますが、私どもとすれば、都移管については１件やって、それにつきましては、居室の増があったり、他のものとの併存があったりしてよかったんですが、ほかのものについては。","voiceIndex":167,"id":"exchange-072"},{"speaker":"山路委員","kind":"質問","question":"区営住宅は、ファミリーの方もいらっしゃいますけれども、高齢者も多いんです。都営住宅は、３人以上子どもがいたら優遇抽選と変えたということを聞いているんです。２０歳代前半の方で、子どもが２人、３人いらっしゃる方は条件に入るんですね。その辺もこれから考慮して、若い人も入れるような体制を考えてみてはと思いますが、どのようにお考えでしょうか。","respondent":"浜脇住宅課長","answer":"区営住宅はなかなか入退去がないものですから、そういった意味では、高齢の方がいらっしゃいますが、区営住宅につきましては、法令に従ってやっているですので、その辺につきまして、今後、そういった法律に基づいてやるということが先決だと考えています。","voiceIndex":169,"id":"exchange-073"},{"speaker":"須藤委員","kind":"意見","question":"１２６ページの道路維持費、同じく１２６ページの駅周辺等の放置自転車、１３０ページの大崎駅周辺地区の都市開発、１３１ページ、建築行政費についてお尋ねいたします。最初に、駅周辺の放置自転車、これはきょう、何回かお話があったんですけれども、一番住民の方から言われてくるのは、駅の近くの私道に自転車をとめられちゃうと、行政側も対応できない、警察も対応できない。","respondent":"山口交通安全担当課長","answer":"しかしながら、依然としてこういう現状がありますので、私道であっても、一般の交通の用に供している道路については、今後、撤去について改正自転車法との関連を調べまして、前向きに検討してまいりたいと考えていますので、よろしくお願いいたします。","voiceIndex":172,"id":"exchange-074"},{"speaker":"須藤委員","kind":"質問・要望","question":"開発のほうでは、これも新聞に出ていたんですけれども、目黒川を利用して、大崎駅の開発、特に風の道をつくるんだというようなお話が書いてあったんだけれども、今言った道路の塗装、それから緑化、そういったものを全部含めながら考えていって、温暖化を下げるような風の道をつくったり、そうった考え方というのかできないか、どうか聞かせてください。","respondent":"松代管理工事課長、上野都市開発課長","answer":"そういったものを、まず道路から公園といろいろと広げられると、それは今後の研究課題だと思うんですけれども、いろいろとそういったことには取り組んでまいりたいと考えているところです。道路の舗装の改善につきましても、本格実施は、八潮の実験結果を見てからやるんですけれども、大崎駅の第３地区では、既に御成橋の際にありますテックスの道路で、一部保水性舗装の実験的な施工をやってありますし、第３地区でも。","voiceIndex":174,"id":"exchange-075"},{"speaker":"須藤委員","kind":"質問・要望","question":"そのあたりが何か連携がとれるような、極端に言えば、いろいろと問題があるような民間業者が建築確認をおろしたとか、何かあるというようなことがあった場合に、どういうチェックができるんだろうか。そのあたりで、考え方があったらお聞かせ願いたいと思います。ですから、社会の情勢がいろいろ変化してきたことに合わせて、指導要綱なり、何なりも考えていただきたいと思いますが、いかがでしょうか。","respondent":"片田建築課長、浜脇住宅課長","answer":"ただ私どもの認識としては、当然、民間が責任を持って判断したものであれば、民間が最後まで責任を持つべきだといったような考え方を、これまでも行政のほうとしては持ってきてあります。開発指導等の見直しといいますか、情勢の変化に基づいて見直すべきだというお話ですけれども、これまでも、私どもとすれば、社会の変化に応じてそれなりに改正した部分もありますので、今後とも、いろいろな区民からのご要望。","voiceIndex":177,"id":"exchange-076"},{"speaker":"須藤委員","kind":"確認","question":"建築確認を民間がどんどんやって、区のほうの数がだんだん減ってきているということは、今までの質問で何点かしたんですけれども、相談事項はどんどん多くなってきているとような形で、やはりまちの人たちは、そのものが確認許可になっていると、何かほんとうにおかしいというので、一生懸命調べ出して、図面を取ったりして専門的に調査をしていったら、これはおかしいんじゃないか。","respondent":"片田建築課長","answer":"そういう情報交換の機会の中で、私どものほうとしても、民間がどういうような体制の中で行ったのかということも十分に確認しながら、指導に努めてまいりたいと考えております。","voiceIndex":180,"id":"exchange-077"},{"speaker":"沢田委員","kind":"質問","question":"１３０ページの都市開発費に関連して、二つの質問をしたいと思います。１番目は、五反田駅の池上線との通路、それから、都営地下鉄の駅とのつながりを、バリアフリーにするという問題が、昨年中に供用開始という話がのびのびになっているようですけれども、現実はどうなっているのか、説明をお願いいたしたいと思います。","respondent":"上野都市開発課長","answer":"これにつきましては、今、ＪＲと東急のほうでそれぞれ現時点の日程を組んですけれども、今のところ、今の駅前の施設で解体とか行ってございまして、地元関係の説明などの協議が整い次第、建築確認などの手続を進めて、工事着工に向けて作業を進めていきたいと。","voiceIndex":184,"id":"exchange-078"},{"speaker":"沢田委員","kind":"質問","question":"今年の６月４日に、私ども、ＪＲ東日本と交渉したときに、何でこういうふうにおくれているんだと言ったら、地元のまちづくり協議会が、駅ビル開発に関連して、それまでエレベーター、エスカレーターをつけるのを待ったと言われているだと。今の話ですと、地元の協議がほぼ整う方向で、詳細設計にもう入れるという段階だというふうに考えてよろしいんでしょうか。","respondent":"上野都市開発課長","answer":"都営地下鉄のほうは、今具体的な日程は聞いてございませんけれども、ＪＲのほうにつきましては、地元のほうで、調整がいつの段階で終わるかという見通しは、具体的にはまだ立っていないようですけれども、ＪＲといたしましては。","voiceIndex":186,"id":"exchange-079"},{"speaker":"沢田委員","kind":"質問","question":"駅ビルは、あそこまで伸びるはずがないわけですから。私は、ぜひお願いしたいと思うんですが、ＪＲもそういうふうに言っているし、地元との交渉で、一日も早くあそこを安全、快適なバリアフリーとするために、区として積極的に働きかけてほしい。それから、２番目の質問をあわせてやりたいと思います。それから、住民合意に対する努力は、計画前と計画後、どんな努力がなされたのか説明をお願いいたします。","respondent":"上野都市開発課長","answer":"今、東五反田二丁目第２地区の開発に伴うご質問が、何点かございましたけれども、今までの経緯といたしましては、都市計画決定をするときに、事業者のほうから高さ２Ｈの範囲内で、日影に関しての影響についてもご説明して、都市計画の手続に乗せて計画決定したものです。","voiceIndex":188,"id":"exchange-080"},{"speaker":"沢田委員","kind":"意見","question":"１回というふうに言われたと思うんですけれども、あれだけの被害、私、日影図を改めて見たんですけれども、１６０ｍが８時の時点で落とす影は、大崎のあそこから大崎第一地域センター、目黒川の近くまでだあっと伸びていくんですよ。９時の段階でも、五反田駅の桜田通りを越えるほどの巨大な影が広がっているのに、住民に事前に、計画をつくる段階にどんな説明したのかと聞いたんです。","respondent":"上野都市開発課長","answer":"話し合いにつきましては、計画決定の手続の際に、事業者から２Ｈの範囲内の方を対象とした説明をしているということと、区といたしましても、地権者に対する説明会を開催したです。","voiceIndex":190,"id":"exchange-081"},{"speaker":"沢田委員","kind":"質問","question":"普通、日照権の話し合いが行われると、立面日影図は、まず、平面日影図と一緒になって出てくるぐらいの問題を、出そうとしないんですね。これだけの開発で、７４億円の税金を投入するのに、同じ納税者の区民に対して何にも説明されていないというのはいかがなものでしょうか。これは区の義務ですよ。ところが、これをやっていない。私、この基準を全然守っていないと思いますけれども、いかがでしょうか。","respondent":"上野都市開発課長","answer":"近隣関係の日影に関する説明につきましては、先ほど、当事者同士での話し合いは継続されているというふうにお話申し上げましたけれども、具体的にどういう日影図を出してほしいとかいう要望が、事業者サイドに出されてございまして、事業者のほうとしても。","voiceIndex":192,"id":"exchange-082"},{"speaker":"沢田委員","kind":"意見","question":"品川区がやるべきこと、法令で、これは望ましいというふうにはなっているんですけれども、東京都は、再開発促進区を決める運用基準は原則的な考え方を示したものであり、これによりなさいと、冒頭に書いてあるんです。品川区が住民の意見を聞かないでいいなんて、どこにも書いてない。私ここで改めて、では長期計画では、こうしたまちづくりのためにどうすべきだと書いてあるか、説明願いたいと思います。","respondent":"阿部都市計画課長","answer":"委員ご指摘の件ですけれども、市街地整備基本方針の中で、きちっと地区別の方針と、骨格の構造を示しています。今回の開発についても、この前の歳入のご答弁でも申し上げましたけれども、市街地整備基本方針にのっとった整備をしていると認識しています。","voiceIndex":194,"id":"exchange-083"},{"speaker":"沢田委員","kind":"意見","question":"私、今そのことを聞いたんじゃなくて、長期計画では、こうした問題を進めるときに、どう書いてあるかと聞いたんです。","respondent":"阿部都市計画課長","answer":"それぞれが役割を果たしてやっていくというのがまちづくりでございまして、先ほど申し上げましたとおり、その３者が一体となって進めていくというのが市街地整備基本方針で、当然、これは長期計画の下にありますので、その方針です。","voiceIndex":196,"id":"exchange-084"},{"speaker":"沢田委員","kind":"質問・要望","question":"まちづくりのところでも、同じことが書いてある。その意味で、都市計画というのは区民全体のものですから、改めて、今後、都市計画をする際、近隣住民、利害関係に係わる住民にも、早い段階で情報提供をすべきだ。合意を前提とするというと進まなくなっちゃうから、そこまで私は言わないけれども、少なくとも情報を提供し、意見を言う場、聞く場をつくるべきだということについては、いかがでしょうか。","respondent":"上野都市開発課長","answer":"それについて、区の方針に合っているものについて、区として支援していくというのが基本です。","voiceIndex":198,"id":"exchange-085"},{"speaker":"沢田委員","kind":"質問","question":"それを強弁して、それを守ってきたと言うのは、いかがなものでしょうか。都市計画法第３条、先ほど読みましたけれども、住民というのは地権者だけじゃないんですよ、事業者だけじゃないですよ、住民広く一般に情報を提供しなさい、これが国と地方公共団体の任務だというふうに言っているじゃないですか。今の答弁を聞きまして、結局、急いでやれやれと言っているのは、開発推進企業なんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":200,"id":"exchange-086"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"まちづくり、道路、いろいろ出ましたので、道路行政について、確認をさせていただきたいと思います。まちづくりの基本的なものは道路からだと、僕は思っています。まちづくり事業部の中で、品川区全体の道路を考えている人はいらっしゃるんでしょうか。だけれども、鳥瞰図じゃないけれども、全体的に品川区をこういうふうに見て、品川区の道路はこうあるべきだと考えられる人はいらっしゃるんですか。","respondent":"松代管理工事課長","answer":"それは当然、国、東京都と連携をしながら、広域的な部分の中に品川区があって、その中の道路網というのをきちんと考えて、我々は常に身近な区民に、生活の中で安心していただけるような視点で、道路の築造、また維持管理といったものをしていく立場かなと。","voiceIndex":202,"id":"exchange-087"},{"speaker":"林（宏）委員","kind":"質問","question":"それは、部分、部分でしっかりとした計画を立てて、つくっていかなきゃいけない道路もあるだろうけれども、全体が見えていることが必要だと思うんですけれども、やっぱり、区長、助役、まちづくり事業部長あたりまでは、全体に、こっちは細街路が多い、こっちは大きい国道が多いとおおよそはわかっていらっしゃるだろうけれども、全体的に把握していることが必要だと思うんですけれども、いかがですか。","respondent":"福田まちづくり事業部長","answer":"これは事実ですが、私どもやはり、一つのまちづくり事業部ですので、まちづくり事業部長というよりも、一つのまちづくり事業部として、道路のあるべき姿、今後の様相ということについて、十分に考えていきたいと考えています。","voiceIndex":204,"id":"exchange-088"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、ここの道路の中で、街路樹の整備だとか、そういうことをされていて、やっぱり上から撮った写真というのは貴重で、それを生かすべきだと、僕は思いますよ。今度、一番細かいところになるのかもわからないけれども、１２６ページの上のほうに、監察事務費というのが五十何万円出ている。６,２７３件の調査をしたのか、監察をしたのか、言葉で言うと、監察事務費だから監察をしたんでしょう。","respondent":"山口交通安全担当課長","answer":"道路監察の事務費についてですが、本件につきましては、道路等の放置自転車対策撤去等に関連して、その費用を処分費用等に充てているものです。","voiceIndex":206,"id":"exchange-089"},{"speaker":"林（宏）委員","kind":"質問","question":"急に話が飛んじゃったので申しわけないとは思うけれども、いろいろな自転車の話は別の項で、全部自転車として入っているはずですよ。だから、６,０００件以上を監察して、私たちがふだんまちの中を歩いていると、ほとんど改善されていないというふうに受けとるんだけれども、これはどういう仕事をされたのかなとお聞きしたんですけれども。","respondent":"山口交通安全担当課長","answer":"先ほど、説明不足でございました。自転車、バイクは一部ですが、委員おっしゃるとおり、商品せり出し、放置屋台、いわゆる路上生活者等の指導等の関係で、その件数になっているです。","voiceIndex":208,"id":"exchange-090"},{"speaker":"堺委員","kind":"質問・要望","question":"今、申し上げました１２６ページ、交通安全対策費に関連してでは、平成１７年秋の全国交通安全運動が、９月２１日から３０日の期間行われたわけですが、確認をする意味で、今回の運動の重点項目、何点か出ているかと思いますが、その辺をお聞かせいただきたいと思います。","respondent":"山口交通安全担当課長","answer":"先般行われました、秋の全国交通安全運動の重点項目につきましてのお尋ねですが、１点目は高齢者の事故防止、２点目は二輪車の交通事故防止、３点目が夕暮れどきの歩行中と自転車乗用中の交通事故防止、４点目がシートベルトとチャイルドシートの正しい着用の徹底。","voiceIndex":211,"id":"exchange-091"},{"speaker":"堺委員","kind":"意見","question":"１０月６日、これは東京新聞の夕刊でございましょうか、都内交通事故死２００人目、横断中の７８歳、はねられ死亡と。このようなことが報道されておりました。こういう数字が出ております。そこで、お尋ねしたいのは、今、高齢者の交通事故防止についてさまざまな事業が展開されておりますが、この辺についても、どういう事業が行われているのか、参考までにひとつお知らせいただきましょうか。","respondent":"山口交通安全担当課長","answer":"秋については、明日開催する予定ですが、参加体験型交通安全教室を開催して、高齢者の事故防止を呼びかけているところです。","voiceIndex":213,"id":"exchange-092"},{"speaker":"堺委員","kind":"意見","question":"そういう中で、やはり先ほども申し上げましたように、高齢者が交通事故に巻き込まれるケースや、あるいは高齢者が交通事故の加害者になるケースが増えているという中から、安全、快適な高齢社会を迎える、あるいは迎えられるという視点からの高齢者の交通事故防止対策について、さらに強化、拡充していく必要があるかなと思っておるんですが、その辺についてのご見解を、ひとつお聞かせいただきましょうか。","respondent":"山口交通安全担当課長","answer":"今後における高齢者の交通事故防止対策ですが、現在、検討している段階ではありますが、シルバーリーダーの養成ということで、いつでも、どこでもできるような交通安全の地域のリーダーを養成したいと、現在のところ、考えているところです。","voiceIndex":215,"id":"exchange-093"},{"speaker":"堺委員","kind":"質問・要望","question":"そういう意味で、今、お話がありましたような、例えばシルバーリーダーの養成でありますとか、いろいろなその時点で必要な方策を、ぜひひとつ講じていただいて、こういう事故が軽減されるように取り組んでいただきたいと思います。これは要望で結構です。それから、２点目です。これの目的と、内容と、効果といいましょうか、これについて、簡単で結構です、教えていただければと思います。","respondent":"藤田道路公園課長","answer":"この間、３回ほど継続して行ってまいりましたけれども、マナーの向上も大分見られてきたということで、参加者の皆さんからは、講習会に参加している方々が、実際に公園を使っている飼い主の方々に注意をするようになった、あるいは。","voiceIndex":217,"id":"exchange-094"},{"speaker":"堺委員","kind":"質問","question":"きょうも同じようになってしまうかもしれませんが、公園の中に条件を、要するにマナーを守れば、公園の中に犬を入れてもいいという方が６割いらっしゃるとおっしゃっておられましたが、では、例えば戸越公園の正門、あるいは下のほうの、ちょっと門の名前は忘れたんですが、そこを入ったところ、薬医門ですか、それから、しながわ中央公園、あるいは西大井の駅に西大井広場公園というんですか。","respondent":"藤田道路公園課長","answer":"通常、一般的な公園等につきましては、「公園内に犬を入れないでください」というような表記をさせていただいているところです。","voiceIndex":219,"id":"exchange-095"},{"speaker":"堺委員","kind":"確認","question":"昨晩、時間にして７時４０分ごろです。３匹、公園の中におりましたが、うち２匹はリードを放していました。ですから、今申し上げましたように、公園によって取り組み方が違う、あるいは掲示されている中身が違う。そこで、確認したいのは、例えば、品川区立公園条例、あるいは品川区立児童遊園の設置および管理に関する条例の中では、行為の禁止について、どのようにうたわれていますか。","respondent":"藤田道路公園課長","answer":"これは、各公園、基本的には同じような項目については、当然、条例上の中で明記をして行っているわけですけれども、例えば、公園の大きさ、あるいは、つくり方といったもので、犬等の関係については、本来は異なるべきだと考えています。","voiceIndex":221,"id":"exchange-096"},{"speaker":"堺委員","kind":"質問","question":"ですから、条例を見る範囲の中では、公園に連れて行ってもいい、あるいは、放してもいいんだというふうに、ペット愛好家は思ってしまいますよね。ただし、今申し上げたように、公園によっては、放してはいけないとか、入れてはいけないとか書いてある。したがって、その辺のところも含めまして、今後の区の対応について、ひとつご見解をお伺いしておきたいと思います。","respondent":"藤田道路公園課長","answer":"今の条例の後段に、散歩させるときも必ずリードをつけなさいというのがあります。その辺も含めまして、今後、西大井広場、戸越公園、あるいは東品川海上公園についても、マナー教室を開き、さらに拡大して、区民の皆さんにマナー向上を訴えかけていきたいと考えているところです。","voiceIndex":223,"id":"exchange-097"},{"speaker":"井上委員","kind":"提案","question":"私からは、１２６ページの放置自転車対策と、１２９ページの公園新設改良費、１３０ページ、都市計画審議会についてお伺いをいたします。１２６ページの放置自転車対策では、駅周辺放置自転車対策事業費として、昨年も、今年も、４億円余の経費が使われているわけですけれども、これに対して、品川区はどのように認識をされているのか、お伺いしたいと思います。","respondent":"松代管理工事課長、山口交通安全担当課長、阿部都市計画課長","answer":"長期計画、または実施計画上の考え方ですけれども、これにつきましては、公園、児童遊園の整備を行うということにとどめまして、その都度。放置自転車対策事業に４億円をかけて、どのように考えているのかというお尋ねですが、区としては、自転車が放置されるという厳然たる事実がありますので。そのほかに、関係行政機関、ここで言いますと消防署と警察の関係ですけれども、これは任命することができるという規定になってありますけれども。","voiceIndex":227,"id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"公園に関してですが、地元の方々の要望で、随時、改修を行われていくということでしたが、公園改修のときに住民説明会を行いますけれども、近隣だけではなく、そこを利用している方々の声も聞くべきだと思うんです。利用者が近隣住民ではないということも考えられるわけですが、その方たちへの説明の周知をどうされているのか、ということをお伺いしたいと思います。","respondent":"松代管理工事課長、阿部都市計画課長","answer":"その目安といいますか、基準として、２５０ｍぐらいの範囲ということで、そこからお出でになって、公園を利用していただけるということを基本にしていますので、当然のごとく、２５０ｍ。都市計画審議会につきましては、都市計画行政の運営を円滑に図るために置かれているものですけれども、今、委員のご提案にございました、区民から公募で選んだらどうかですけれども、そういう意味では。","voiceIndex":231,"id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"そういう意味で、先ほど答弁いただきましたが、議員は法令に基づいて入れなければならないということで、入っているわけですから、そうではなくて、市民の立場でまちづくりを考えるという方々の公募が望ましいかと思いますので、ぜひ、そのところのお考えをお聞かせいただきたいと思います。","respondent":"阿部都市計画課長","answer":"もう一つは、法令で入れなければならないから入れているのかと、そういう意味ではございませんで、各会派の方を入れてありますので、そういう意味では、区民の意見をきちっと反映していると考えております。","voiceIndex":234,"id":"exchange-100"},{"speaker":"井上委員","kind":"提案","question":"これはもう考え方で、今までも、私たちは区民の意見を反映させるためにということを、再三提案をしてまいりましたけれども、議員が市民の代表であるということで、いろいろなところで答弁をいただいております。次に放置自転車対策なんですけれども、放置防止指導啓発というのは、具体的にはどのような内容で事業が行われているのか、お知らせください。","respondent":"山口交通安全担当課長","answer":"放置防止指導啓発につきましては、駅周辺の放置されている自転車等に札つけ等をして、放置の防止を呼びかける活動です。参考ですが、本年度から、大井町駅のほうでガードマンがおりますけれども、あわせて放置防止啓発活動の一環です。","voiceIndex":236,"id":"exchange-101"},{"speaker":"井上委員","kind":"提案","question":"自転車のメリットとしては、環境型の乗り物であることとか、健康増進に役立っていること、そして足の不自由な方でも移動手段として活用している。先ほどのように、自転車利用人口が実際には増えているという認識で、自転車を、迷惑だから片づけましょうという政策ではなくて、自転車を推進する政策に転換をしていただいて予算化をしていくことを望むんですけれども、ご意見を伺いたいと思います。","respondent":"山口交通安全担当課長","answer":"品川区の自転車利用は、健康的で非常に促進したらいいじゃないかというご提案ですが、品川区は、通勤、通学等、終始一貫、自転車を自粛、駅も近いという方針ですので、また、プライベートで利用されるときには、マナーを守って模範的な利用の仕方をしていただければ。","voiceIndex":238,"id":"exchange-102"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、そこのところは、今の住民ニーズ、皆さんがどれだけ自転車を利用しているのかという現場を、社会状況もだんだん変わってくる中で、ほんとうに学生も、駅まで自転車で通ってというところがあるかと思いますので、駐輪場の見直し、駐輪場の中の費用の見直し、学生割引が使えるだとか、そういった広くいろいろなことが検討される材料になるかと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"スクールゾーンについてですが、最近、学校の教育改革プラン２１も始まりまして、従来より早く学校に行ったり、スクールゾーンと明記されている地域によってもかなり違うこともありますが、それとともに、スクールゾーンとすべき時間帯の見直しをすべきではないかと感じるんですが、その辺はどのようにお考えでしょうか。","respondent":"山口交通安全担当課長","answer":"検討の内容については、校長、父兄の方々のご意見を頂戴して、アンケートなど、そういうコンセンサスを得て、合意を得て実施したい。区だけでもできませんし、交通管理者の問題もありますけれども、そういう関係で、現在のところ、見直しを図っているところです。","voiceIndex":242,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"小学校は、８時半まででしたら、大体子どもたちは登校している。ただ、これは地域によってもかなり違いますし、施設によってもかなり違うところがありますので、校長会だけではなくて、関連機関のほうの調整、意見交換といいますか、実態を少しお聞きになって、変えていくべきところは変えていただきたいと考えておりますが、ほかの施設に関しては、いかがでしょうか。","respondent":"山口交通安全担当課長","answer":"この件につきましては、非常にデリケートな問題で、子どもの安全が最優先ということを念頭に置いて、今のところ、見直しさせていただいていますので、そこは踏み外さないように、慎重には慎重を重ねて検討してまいりたいと考えております。","voiceIndex":244,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ、進めていただきたいと思います。当然、協力者がいて設置するとはなっているんですが、これは協力者がいないことは、そうそう設置できないという現状はわかっているんですが、そこら辺もＰＴＡ等々にお願いをする、地域の方たちにお願いをするという形で、推進をしていただきたいと思っています。警察等との協力体制もとれないだろうかということは考えているんですが、その辺はいがでしょうか。","respondent":"山口交通安全担当課長","answer":"そういう状況の中では、声を聞きましたら、警察のほうで、指定ではございませんが、重点的に配置をしていただいて、協力をいただいて、取締配置をしている状況もありますので、今後、そういう状況がございましたら、管轄警察署と協力して対応したいと考えております。","voiceIndex":246,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"通報というのが一番手っとり早いことだと思いますので、校長会等々の機会がありましたら、協力をお願いをして、ＰＴＡの方たち、それから、交通整理をされている方もいらっしゃると思いますので、見かけたら通報をお願いしたいという協力を、ぜひお願いをしていただきたいと思います。","respondent":"阿部都市計画課長","answer":"一方、市街地整備基本方針に基づいて、各地区の地区計画なり、再開発も地区計画に含まれますが、そういうものがなっているという意味では、それぞれの地区計画の中で、当然景観に配慮するという項目がありますので、今回の景観ガイドプランの中身も。","voiceIndex":248,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"進め方で、ちょっと具体的によくわからないところがあるんですけれども、じゃあ、具体的に今、始まっている地域はあるのでしょうか。どういう流れで、今、進んでいるのか、現状を伝えてください。","respondent":"阿部都市計画課長","answer":"今、申し上げましたとおり、まず現に進んでいる地区計画のところについては、今申し上げたように、市街地整備基本方針の中で、それぞれの地区の特性に応じたまちづくりということになっていますので、それとの整合性はとれていると考えております。","voiceIndex":250,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"これは非常にいいかなと、私たち思っていますけれども、要は都市景観法が制定されて、どういうまち並みをつくっていくか。それというのは、最終的には都市観光というふうに続いていくわけですね。都市観光の中で、観光も含めて、ではどういうふうに形成していくかという形になると、もっと広い意味になってきてしまうと思うんですが、その辺の関係については、いかがなんでしょうか。","respondent":"阿部都市計画課長","answer":"ただ、景観法で言いますと、一度計画を決めたら、それが未来永劫いくというものではございませんので、もし計画を立てる場合、まずは何をやれるか、次に何をやれるか、そういう発展的な計画だと考えております。","voiceIndex":252,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"担当する部署はどこになるんでしょうか。都市観光になりますと産業振興課になるわけですね。その中で、じゃあだれが主導権を握ってまとめていって、方向性をつくっていくのかという、そういうところの整合性、それから事業部間にまたがってしまうというところの調整は、どのようにしていくんでしょうか。","respondent":"阿部都市計画課長","answer":"確かに、今おっしゃるとおり、いろいろな部にまたがってあります。ただ今は、私ども都市計画課が所管になりまして、庁内の産業振興課を含めた連絡会というのを持ってありますので、その中で、私どもは当面の中心になりながら進めていくという考え方です。","voiceIndex":254,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問","question":"品川区においては、都市観光というのを推進していって、活性化をしていくというのは一つの大きな柱になり得る事業だと思いますので、いろいろな方たちが関与しながら、ダブって仕事をしないでほしいなと思います。次に、投資型マンションについてですけれども、これが、品川区においてどういう形になってきているか、現状がおわかりでしたら、ちょっと教えてください。","respondent":"浜脇住宅課長","answer":"私どものほうに相談に来るといいますか、開発指導に来るときに、これが何とかマンションですよということではございませんから、必ずしもつかんでおりませんし、分譲なのか、投資型なのかというのは、向こうから表示されたことはございませんので、私どものほうでは、今現在。","voiceIndex":256,"id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"投資型ですから、一つの部屋ごとにオーナーが違うということもあり得るわけですよ。それから、今、言われているのが、１０年サイクルだろうと。そうなると、やはり品川区として、知りませんでしたということにならないわけで、ある程度、品川区の中での責任というか、実態把握の状態は、せめてしておかなければならないんではないかなと思うんですが、その辺の考え方はいかがでしょうか。","respondent":"浜脇住宅課長","answer":"私どもも、連絡先については、建物の見えるところに連絡先を書いて、そういう対応については、管理会社に行って、お住まいとか、あるいは、何かあったときには対応してくれという話を日ごろからしております。","voiceIndex":258,"id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"現状は難しいかとは思いますけれども、やはりこれは、１０年、２０年、３０年経ったとき、地域がどうなるかということにかかわってきますので、追いかけられるところは追いかけるという形に、ぜひ工夫をしていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":260,"id":"exchange-113"},{"speaker":"藤田委員","kind":"質問・要望","question":"私からは１２６ページの交通安全対策につきまして、もう１点は、ちょっとページはわからないんですが、土木事務所に関する質問をいたします。１点目、自転車に安全に乗ってもらおうということで、子どもたちに対して免許制度を実施しているという区がありますが、こうしたシステムを、どのように評価しているのか、その辺をお伺いしたいと思います。","respondent":"山口交通安全担当課長、藤田道路公園課長","answer":"委員お尋ねの子どもの免許証の関係ですが、たしか、平成１４年４月、都内では荒川区で初めて実施されたと記憶しております。現在、都内で実施されているところについては、昨年末現在ですが、１２区市町村というデータがあります。数としては、各事務所２カ所ぐらいずつは持っておりますので、全体で１０カ所前後と考えています。","voiceIndex":262,"id":"exchange-114"},{"speaker":"藤田委員","kind":"質問・要望","question":"子どもの自転車の安全につきましては、やっぱり子どもの事故を防ぐという意味で、少しでも効果があることであれば、いろいろな考えを参考にして、品川区はやっていただきたい。これは要望しておきます。面積の広いところ、狭いところいろいろあると思いますが、こうした資材置き場を統廃合する計画はないんでしょうか。","respondent":"藤田道路公園課長","answer":"例えば、東品川シルバーセンターの近所に、以前、資材置き場があったんですけれども、それは有効活用を図ろうということで、土木事務所の材料置き場等から外して、今、活用を図っているところです。こうしたことは、今後とも継続してやっていきたいと考えています。","voiceIndex":265,"id":"exchange-115"},{"speaker":"藤田委員","kind":"質問","question":"品川区は２２km2 という狭い区ですので、緊急的に何かあっても、例えば、その地域の事務所１カ所でも対応できると思うんです。今、各地域で問題になっています。例えば、そういうところの２階を、１階でもいいです、有料のオートバイ置き場なり、自転車置き場にする、２階は資材を置いて、リフトで持ち出すというような工夫をすれば、何ら問題ではないかと思うんですけれども、いかがでしょうか。","respondent":"藤田道路公園課長","answer":"そういった面では、ある程度のあいたスペースというのは必要かなと考えています。ただ、委員おっしゃるとおり、有効活用を積極的に図っていくということは必要なことだと思ってあります。そういった面では、工夫をしていきたいと考えています。","voiceIndex":267,"id":"exchange-116"},{"speaker":"藤田委員","kind":"質問・要望","question":"私は、もちろん全部そうしろと言ってないんですよ。実際に見ていただいて、まちでどういうものが問題になっているのか。何もなくせと言っているんではないということをぜひ知っていただいて、ここで、なかなか、はいわかりましたとは言いづらい部分がありますから、もう一遍そういった視点で、資材置き場はどうあるべきかということを、ぜひ検討していただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-117"},{"speaker":"石田委員","kind":"質問","question":"私からは、１３１ページ、木造住宅耐震診断支援事業、防水板設置工事助成事業も絡むと思いますが、まず初めにお聞きしたいのは、阪神大震災等で家屋の倒壊により亡くなられた方が非常に多かった、火災等よりも非常に多かったという現実的な事実があるわけです。ここの部分の考え方をどう整理されて、どこまで突っ込んでやろうと、まちづくり事業部では考えられてやっているのか、まずそこをお聞きしたい。","respondent":"片田建築課長","answer":"私どものまちづくりにおける安全性を高めたいということで、耐震診断を昨年から実施しているものです。ご質問は、その意気込みといいますか、その辺の考え方ということで、認識しました。","voiceIndex":271,"id":"exchange-118"},{"speaker":"石田委員","kind":"質問","question":"木造住宅、古いところを、今、不燃化促進とか、密集市街地とか、これは非常にやられているのはわかります。しかしながら、木造住宅が厳然として残っているというのも事実であります。今の意識啓発でいくと、個人の所有者という部分がありますが、どれだけ税金を投入するんだと。だから、そこの辺の意気込みを、どのように考えてられてこういう政策を打っているのかというのを、改めてお聞きしたい。","respondent":"片田建築課長","answer":"逆に、区のほうとしても把握している部分としては、ご案内のとおり、平成１３年の土地利用現況調査からすれば、２万二、三千棟というようなお話を、これまでも説明させていただいているところです。","voiceIndex":273,"id":"exchange-119"},{"speaker":"石田委員","kind":"質問","question":"それも一つの考え方でしょう。それらをいかに、耐震補強工事にいかせるか、そこに手を入れたらいいんじゃないですか。具体的にどういう形で耐震補強工事に進めるんですか。ということがもうわかっているんであれば、そこを品川区として、亡くなられる方を減らすためには、どうやって手を入れるかというのを、私はちゃんとしっかりしたシミュレーションのもとに考えるべきだと思うんですけれども、改めて。","respondent":"濱野助役","answer":"しかしながら、いわゆる区の財政力と、区の規模をもって、今言われたようないわゆる減災というところまで、この耐震改修、あるいは耐震診断等によって、そこの効果を出すまでの財政投入というのはなかなか難しいと考えています。","voiceIndex":275,"id":"exchange-120"},{"speaker":"石田委員","kind":"提案","question":"これはもちろん東京規模にもなるけれども、品川区から提案をして、東京都を動かして、東京都が動けば絶対できるんだけれども、そういうのを品川区から提案するなり、これはあるちゃんとした人が言っている部分もあるんだけれども、そういういろいろなシミュレーションをして訴えていくということを、ぜひやっていただきたいと思うんですけれども、そこら辺の考え方を教えていただきたい。","respondent":"濱野助役","answer":"この問題について、知恵は一生懸命絞ってまいりたいと思っています。いわゆるインセンティブ、誘因というような形での知恵というものは、一生懸命絞ってまいりたいと考えております。","voiceIndex":277,"id":"exchange-121"},{"speaker":"石田委員","kind":"意見","question":"ぜひそういう面で、いろいろなやり方があると、私は思っておりますので、この部分については、また違う場面でやりたいと思っていますけれども、最終的には命を守るというのが、区民の命がここで一番なくなるというところに、やっぱりしっかりとした手をつけるというのが一番だと考えていますので、ぜひその点を考えて、やっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":279,"id":"exchange-122"},{"speaker":"松澤委員","kind":"質問・要望","question":"私からは３点、成果報告書の１２７ページの都市計画道路整備事業に関連して、補助２６号線の問題、１３０ページ、都市防災不燃化促進事業に関連して、戸越公園一体周辺地区の都市防災不燃化促進事業について、１２８ページ、細街路拡幅整備事業についてお伺いしたいと思います。補助２６号線の問題ですけれども、先日、囲いをのぞいてみましたら、大井町線の下がもうできているんですね。","respondent":"阿部都市計画課長","answer":"１件大きいところがあったんですけれども、それもほぼ解決すると聞いてあります。今のところの完了年度ですけれども、平成２１年度の予定です。","voiceIndex":281,"id":"exchange-123"},{"speaker":"松澤委員","kind":"質問","question":"それからもう一つ、あれは第１期工事、第２期工事ということで、平成１８年度までが第１期工事で、大井町線の下をくぐるとなっているんですけれども、そうしますと、補助２６号線の下敷きであります鮫洲大山線、防災道路ですからくぐって上がってきますよね。そうしますと、その時点で、その部分まで供用できるんでしょうか。それについて、ちょっとお伺いしたいと思います。","respondent":"阿部都市計画課長","answer":"今のところは、平成２１年度というのは、踏み切りのところで今度ＪＲをくぐります、そこを含めましてですので、今のところ、平成２１年度の完了予定です。全線が平成２１年度です。今のところは、途中で開放するということは聞いてございません。","voiceIndex":283,"id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"平成１８年度までにできるということは、あそこまで完成すると思うんですよ。そうしたら、道路の一区間ができたら、部分開通というんですか、当然供用開始すべきだと思うし、そうすれば便利ですし、補助２６号線の向こうから大崎高校をくぐって来ることができるわけですから、考えていないというのではなくて、やはり区民のために、一部分でも運行すべきだと思うんですが、その辺の考えは、いかがですか。","respondent":"阿部都市計画課長","answer":"一部分ですけれども、基本的には、補助２６号線は区役所前までを全体として供用開始をするというのが都の第二建築事務所の考え方と聞いてあります。ですから、今のところ、申し上げたとおり、途中で供用開始をするとは聞いていないという意味あります。","voiceIndex":285,"id":"exchange-125"},{"speaker":"松澤委員","kind":"質問","question":"何でこういうことを言いたいかというと、防災道路なんですから、その下に歩道もついている、やはり、何かあったときには、少しでも便利なためには、開始すべきだと思う。それが開通すれば、パイバスですから、それが区道になると思うんですよ、その辺の考え方。そうすれば、区民にとってみれば、道路そのものが区道になれば、やはり便利ですから、その辺の考え方はどうかということを聞いているわけです。","respondent":"阿部都市計画課長","answer":"今の委員のご指摘も踏まえまして、私どもとしては、第二建設事務所の所管ですので、申し上げていきたいと考えています。","voiceIndex":287,"id":"exchange-126"},{"speaker":"松澤委員","kind":"意見","question":"はい、わかりました、いいです。平成１８年度から２７年度まで１０年計画ということで、三つの計画、都市防災不燃化促進事業の戸越公園一体周辺地区、防災生活圏促進事業、やはり、戸越公園を広域避難所とするために、避難してくる人たちのための不燃化、あるいは、道路づくりだと思っているんです。あるいは、計画があるのかもしれませんが、その見通しについて、お聞かせください。","respondent":"伊勢住環境整備担当課長","answer":"実は、防災生活圏促進事業で、大原通りと言っている通りがあるんですけれども、そこの道路拡幅について説明会がございました。","voiceIndex":289,"id":"exchange-127"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、今の話はできそうだというふうに受けとってよろしいんですね。わかりました。実はその拡幅とともに、もう一つは、戸越公園の駅そのものを高架にできないかなと。あれを高架にすることによって、大分踏み切りが立体交差になりますし、それによって、防災のときに避難して来る人たちにとっては、随分楽だと思うんですよ。その辺の考え方についても、お伺いしたいと思います。","respondent":"阿部都市計画課長","answer":"確かに、高架化すればいいとは考えてありますけれども、今のところ、東急のほうには、高架化の考えはないと聞いてあります。","voiceIndex":291,"id":"exchange-128"},{"speaker":"松澤委員","kind":"質問","question":"確かに、東急単独ではやらないでしょう。それは、莫大なお金がかかるからですよね。武蔵小山駅ではやりましたよね。これは、補助２６号線との、一つの都市計画道路との問題ですよね。あそこには補助２６号線があり、補助２９号線という未完の計画線もありますよね。やはり行政はそこまで考えていただかないといけないと思うんですけれども、その辺、いかがでしょうか。","respondent":"岩田まちづくり事業部次長","answer":"現在、目黒線のほうに全勢力をつぎ込んでおります。立体化につきましては、委員、ご指摘のここだけではなくて、京浜急行の八ツ山の立体化の問題も、区としては大きな問題として抱えておりますので、全体の問題として検討させていただきたいと思います。","voiceIndex":293,"id":"exchange-129"},{"speaker":"松澤委員","kind":"質問","question":"思いのたけを言ったものですから、おそらく、僕が議員のうちにはできないと思いますけれども。もう一つ、今のと相反するんですけれども、広域避難場所、戸越公園一体周辺防災まちづくり、この中に、補助２９号線が書かれているんですよね。品川区、東京都、まちの人、三者三様かもしれませんけれども、その考え方をお聞きしたいと思います。","respondent":"阿部都市計画課長","answer":"ただ、平成１４年に出ました危険度の問題の中で、計画線の沿線の危険度が高いということが出ましたので、私どもとしては、新たな考え方から、この都市計画道路の整備が必要であろうと考えています。","voiceIndex":295,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、議会意思、区民の意思というものが、全会派一致で通ったものが、防災で必要だということで、簡単に復活してくるものなんでしょうか。その辺、しっかりとご答弁願います。","respondent":"福田まちづくり事業部長","answer":"なぜならば、それは、その時点における区民の意思にほかならないと考えておるからです。しかしながら、この都市計画線が不必要なのかと問題をつくり直して考えてみますと、現時点で、単に廃止すればそれでいいんだという認識に立つことはなかなか難しく思って思います。","voiceIndex":297,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。きょうのところは、この辺でとめておきます。次の細街路拡幅整備事業についてですけれども、これも、９５４万５,０００円助成金を出して細街路を拡幅しています。この助成についてですけれども、確か、区道に接して下がった部分だけの助成というふうに理解しているんですけれども、助成内容全体、幾らぐらい助成しているのか、どういう細街路に出るのかについて、お聞きしたいと思います。","respondent":"片田建築課長","answer":"地面は所有者の持ち物なんですけれども、区のほうに管理させていただけませんかといったようなお話を、協議の段階でさせていただいて、できるだけそういうような方向で行っているとものです。","voiceIndex":299,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、効果的な内容と書かれていますので、ある程度、その内容というのは煮詰まっていると思うんです。私、前回質問をしたときに、２項道路が整備されてきたんで、奨励金を廃止するかなという意識を持ったんですが、効果的な内容について、どのような考えを持っているのかお聞かせください。","respondent":"片田建築課長","answer":"そういうものを総合的に見直して、限りある予算の中でどう効果的にできるかということを、今現在、検討を進めているものです。委員ご質問の奨励金のこと、あるいは塀の撤去費用の助成金とかそういうことも含めて、今後検討の視野の中には入れて進めるということを考えてあります。","voiceIndex":303,"id":"exchange-133"},{"speaker":"松澤委員","kind":"確認","question":"私は、みんなのもの、国のもの、区のものだというふうに思っておるものですから、しなくてもいいような形だと思っているんです。実は、２項道路で一番大事なのは、下がらない部分なんですよね。それが撤去できないじゃないですか。２項道路は、奥が下がっても、表が下がらないために使えない。そこまですれば、２項道路が整備されて、防災機能がぐんと高まると思うんですが、その辺はいかがでしょうか。","respondent":"片田建築課長","answer":"そういうことも含めて、きちっと話し合いができるようなことでは対応をしていますけれども、確かに、そういう民法上のこともございまして、課題はありますけれども、区のほうとしても、きちっと整備していただくように。","voiceIndex":305,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問・要望","question":"ほんとうに路地を歩いていると、あっ、ここは下がっている、広くなったなと感じるところがいっぱいあるんです。ですから、今、建築課長がおっしゃられましたように、広報活動をしっかりしてもらって、２項道路はみんなのものですよという形で、さらに広げる努力をしていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":307,"id":"exchange-135"},{"speaker":"宮崎委員","kind":"質問","question":"私は、成果報告書１３１ページの木造住宅耐震診断支援について、時間があったら、１３２ページの区営住宅の問題もやりたいと思います。耐震診断は、昨年度から始まりました。先ほども石田委員のほうから質問がありましたが、問題意識は同じかなと思いました。改めて、昨年度４０件の耐震診断、その結果、概要をお聞かせいただければと思います。","respondent":"片田建築課長","answer":"申請されたのは４２件、そのうち、２件が取りやめたことを含めて、助成支援したのは４０件ほどあります。その後の状況を把握した部分としては、耐震診断を行った上で、診断を踏まえた補強設計ですけれども、それを、現時点で４件ほどが検討している。","voiceIndex":309,"id":"exchange-136"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、４０件受けて、問題なしというところは何件ぐらいあったのかということ。それから、今９件ですけれども、実際上補強が必要だというのは、設計が４件と、工事中３件、終わったのが２件で９件ということですと、何らかの補強が必要だという診断されたのは、全部で９件だったということですか。それとも違うのか。","respondent":"片田建築課長","answer":"診断を受けて、どこをどういうふうに補強したらいいのかとか、あらあらの見積もりまでご案内しているところがありますので、効果的な補強について、ご自分が意識を持って補強設計をして、これから工事を行うという流れが、現時点で。","voiceIndex":311,"id":"exchange-137"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと改めて、診断を受けて、そういう意味ではすべてが問題ありということなんだけれども、補強工事までいかなかった方が、そうすると３１件。その方々の理由ですね、そこのところはどういうふうにつかんでおられるんですか。","respondent":"片田建築課長","answer":"ちょっとその理由につきましては、追跡調査というわけではございませんけれども、ご案内をして、アンケート調査を含めて、なぜ現時点で補強設計まで進まないのかというところは、今後、把握していく予定です。","voiceIndex":313,"id":"exchange-138"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先の都議会でも、都知事が、地震はいつ来てもおかしくないので、万全な備えを講じるというふうに述べています。一つは被害想定見直しと、もう一つが、木造住宅の耐震化促進に取り組むという発言だったと思うんです。今時点で、ちょっとわかっていることがあるのか。それから、区との関係でも、どういうふうに今後、具体的な中身が進んでいくのか、わかっている範囲でお聞かせいただきたいと思います。","respondent":"片田建築課長","answer":"だた、その方向としては、先ほどもちょっと答弁の中でご説明したかもしれませんけれども、やはり、各区のそれぞれのいろいろな特徴がありますけれども、それを下支えしていくといったことで、とりわけ東京都が独自の手法を使うとかいうことではなくて。","voiceIndex":315,"id":"exchange-139"},{"speaker":"宮崎委員","kind":"質問","question":"これが平成１３年の時点ですから、その後４年ほど経っていますから、その分減っていると思うんですけれども、いずれにしても、残されているという言い方は、ちょっと失礼かもしれないんですけれども、住宅がどういうふうに耐震化されていくのか。そうすると、これらの木造住宅は、どういうふうに耐震化されていくのかというところは、どういうふうに見ておられますか。","respondent":"片田建築課長","answer":"それでも古い建物の補強をするということに関して、診断を含めて、融資あっ旋等の支援をするという内容ですので、区として、ではこの２万棟前後のものを、具体的に計画を持って、何棟行うという考え方ではございませんで、これまでの他区の実績等々を含めて、きちっとやっぱり。","voiceIndex":317,"id":"exchange-140"},{"speaker":"宮崎委員","kind":"質問","question":"２万棟前後というお話でしたけれども、やっぱりこれをどういうふうにしていくのかというところがポイントだと思うんですよ。一般質問でも紹介しましたけれども、木造住宅耐震補強事業者共同組合の調査結果がマスコミにも出ました。先ほど９件が補強工事に結びついたというお話でしたけれども、これが呼び水という点ではどのぐらいの効果があるのかというところの評価は、どういうふうにされていますか。","respondent":"片田建築課長","answer":"呼び水としての評価という考え方ですけれども、他区の事例を見ても、横浜市でも、かなり無料診断みたいな形で行った中でも、改修につながった割合というのは１％を切るような状況であったことは認識しておりますし、区のほうとしては。","voiceIndex":319,"id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"呼び水ということであると、やっぱり、補強工事までつなげる、その最初の入口ですから、ここのところまでどう行くのかというところがやっぱり大事だと思うんですよ。木造住宅耐震補強事業共同組合の調査は大体１２０万円が平均だと言っています。しかし、私が紹介した方も、１００万円がせいぜいじゃないかと、そういうふうにおっしゃっていました。その点、改めてお考えをお聞かせいただきたいと思います。","respondent":"福田まちづくり事業部長","answer":"耐震診断と補強工事の施策の一番難しいと思うところは、区民の皆さんは、地震が来るのではないかという危機意識を持っていらっしゃる、このことは間違いないと思うんです。私ども、行政もそういう危機意識を持っております。","voiceIndex":321,"id":"exchange-142"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、呼び水ということですと、区民の自発をいかに促すか、そこにしっかり手を結べるか、そこまで手を差し伸べないと、私は呼び水とはならないと思うんです。ですから、ひとつ大きなネックになっているのは、やっぱりいわゆる自己責任の部分がかなり強いと思います。１件の火事が広く被害をもたらすという危機意識をぜひ持っていただきたい。重ねて要望しますけれども、お願いします。","respondent":"福田まちづくり事業部長","answer":"ただ、私どもは、その両者をどちらも否定しているのではなくて、そのバランスをとる、そういう問題……。","voiceIndex":323,"id":"exchange-143"},{"speaker":"木下委員","kind":"質問・要望","question":"５時も回りまして、最後から２番目ですので、よろしくお願いいたします。しっかりやっていきたいと思います。成果報告書１３１ページ、建築行政費に関連してちょっと質問させていただきたいと思います。斎場建設について、今までの流れですとか、状況等、わかる範囲でご説明いただければと思います。","respondent":"浜脇住宅課長","answer":"昨年１０月ごろに、事前カードというのが出されました。それから、事前協議書等が出されまして、地元の方々と説明会を２回ほどやってあります。それ以降に２月になりまして、事業主のほうから、要綱に基づく協定書というものを出されております。","voiceIndex":326,"id":"exchange-144"},{"speaker":"木下委員","kind":"質問","question":"建築審査申請が出て、今膠着状態ということです。新聞でも８月１５日に、その反対運動を受けて、斎場建設に対する指導要綱を１５日に施行と、京都のほうでは、住民と協定締結もというふうに載っておりました。ですから、要綱にもう一歩踏み込んだ形での項目を入れたらいかがかなと思うんですけれども、区のほうとしての見解等をお伺いさせていただければと思います。","respondent":"浜脇住宅課長","answer":"私どもとすれば、今ここですぐに改正をするということではなくて、その土地、地域に応じた建物が建設されてしかるべきというふうな部分がありますので、今の要綱を、いきなり住民の協定なくして建てないんだということまでは考えてございません。","voiceIndex":328,"id":"exchange-145"},{"speaker":"木下委員","kind":"質問・要望","question":"今のところは考えていないというご答弁じゃないかなと思うんですけれども、ぜひ検討していただきたいと、私は思います。今度は別件で、１２６ページの土木管理費、土木総務費について、ちょっとお伺いします。その方は、隣の用水路があいているんで、お借りしたい、もしくは買いたいということでのご相談だったんです。ちょっと、ご見解のほどお聞かせ願えますでしょうか。","respondent":"松代管理工事課長","answer":"そういったものを、譲与事務の後、きちんと把握をしまして、公的に利用しないような土地につきましては、積極的に地元の方に払い下げ等も含めて、対応していきたいと考えているところです。","voiceIndex":330,"id":"exchange-146"},{"speaker":"木下委員","kind":"質問","question":"ちょっとまた、おおよそでも構わないんですけれども、わかる範囲でよろしいので、実際、そういう形で対価を払って借りていらっしゃるなり、購入していらっしゃるなりの方と違って、不当という言葉は、今までの流れで知らずに使っていらっしゃるのかもしれないんですが、使っていらっしゃる方は、大体どのぐらいなのか、わかる範囲で教えていただければと思います。","respondent":"松代管理工事課長","answer":"これにつきましては、先ほど申し上げましたように、順次、実態に合わせたような形で、私どもがきちんと管理するもの、もしくは、そういった形で実際に使われているような部分であれば、払い下げをするというような形で、方針を決めて、今、積極的に取り組んでいるところです。","voiceIndex":332,"id":"exchange-147"},{"speaker":"木下委員","kind":"質問","question":"１５９路線あって、１万５,３００ｍですか。そのうち、使われている部分というのは、ある程度推測というか、わからないですか。","respondent":"松代管理工事課長","answer":"まさに、今まで申し上げましたように、適切な管理をまずしていくには、そういった実態を把握しつつ、実態に合わせたような形で、私どもが管理する、もしくは払い下げるといったことで整理していく内容だと思って、引き続き、この作業は進めていくべきものだと考えています。","voiceIndex":334,"id":"exchange-148"},{"speaker":"木下委員","kind":"質問・要望","question":"ぜひ把握していただいて、うちの地元のほうなんかでも、坪あたり２００万円ですとか、土地というのはかなり高価ですから、借りるにしても、かなりの金額になるかと思います。ではまた変わりまして、１３０ページ、都市開発費、密集住宅市街地整備促進事業に関連する部分で、ちょっとお聞きしたいと思います。ふと思ったのは、その中で、電柱はそのままなんですよ。","respondent":"片田建築課長","answer":"ただ、合意形成ができるように努力していきたいと思います。","voiceIndex":336,"id":"exchange-149"},{"speaker":"三上委員","kind":"質問","question":"２点、１２６ページ、駅周辺等放置自転車対策事業、それから、１２７ページの都市計画道路整備事業に関係して、お伺いしたいと思います。開通できないなら、できないなりの、そういう整備の仕方、いつまでも放置しておくのではなくて、そういうことをどう考えているのか、現状、第二建設事務所とどう打ち合わせをされているか、ちょっとお伺いしたいと思います。","respondent":"山口交通安全担当課長、阿部都市計画課長","answer":"協議会でお集まりいただいた方には、このように、皆さんの協力がなければなかなか解決に向かわない状態で、これから、今後の協力を求めた経緯です。暫定開放の件ですけれども、それも可能なのか、どうか、その辺を含めて、第二建設事務所のほうと調整していきたいと考えています。","voiceIndex":339,"id":"exchange-150"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、こういう状態がずっと放置されるということは、武蔵小山駅前にできたら、同じようになりますよ。これは答弁を求めませんけれども、こういうことだって、しっかりと考え方をやっていただきたい。暗いし、雨が降ったら滑るし、雨のたまったところに足を突っ込んじゃったとか、そういうことでいるわけですから、いつまでもこういう状態を放置しないで、整備できるものなら、もうしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":342,"id":"exchange-151"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1252#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":109883,"voices":343}}]);
